/* ======================= CHAPITRE ======================= */
const DEMO_REGISTRY = {};
let currentChapterTitle = null;
let currentChapterCode = null;
let currentChapterLevel = null;

// opts.silencieux : chapitre préparé sans être affiché (session COURS, cours-exos.js : ses parties y
// sont montrées vivantes, animations comprises) ; renvoie la fin du chargement du cours personnalisé.
function openChapitre(c, tab, lvlOverride, opts){
  const lvl = lvlOverride || currentLevel;
  const silencieux = !!(opts && opts.silencieux);
  // Élève : un chapitre hors de son niveau reste fermé aussi par un lien direct (adresse, recherche…).
  if(!silencieux && currentUserRole==='eleve' && c && isChapterLocked(lvl, c.t)){ onLockedChapterClick(); return; }
  const chapView = document.getElementById('view-chapitre');
  chapView.classList.toggle('lvl-6e', lvl==='6e');
  chapView.classList.toggle('lvl-cm', lvl==='cm1');  // CM1 : vert
  chapView.classList.toggle('lvl-cm2', lvl==='cm2'); // CM2 : vert émeraude foncé
  chapView.classList.toggle('lvl-ce2', lvl==='ce2'); // CE2 : vert tilleul
  chapView.classList.toggle('lvl-5e', lvl==='5e');
  chapView.classList.toggle('lvl-4e', lvl==='4e'); // 4e : sa propre couleur (bleu-vert), pour distinguer le niveau d'un coup d'œil
  chapView.classList.toggle('lvl-3e', lvl==='3e'); // 3e : violet prune
  const demo = DEMO_REGISTRY[lvl+'|'+c.t];
  currentChapterTitle = c.t;
  currentChapterCode = c.code;
  currentChapterLevel = lvl;
  document.getElementById('chap-code-tag').textContent = c.code;
  document.getElementById('chap-code-tag').style.background = CATS[c.cat].bg;
  document.getElementById('chap-code-tag').style.color = CATS[c.cat].text;
  document.getElementById('chap-title').textContent = c.t;
  document.getElementById('chap-meta').textContent = `${c.p ? 'pages ' + c.p + ' · ' : ''}${c.s} semaine(s) · ${c.d}`;
  // En-tête visible UNIQUEMENT à l'impression (voir @media print, styles.css) -- signalé :
  // "en haut de page à gauche : Chapitre 1... puis N1 - Nombres décimaux."
  // c.n n'est pas toujours transmis par l'appelant (ex. carte cliquée, reconstruite depuis
  // son dataset qui ne l'inclut pas) -- recherché par code dans la liste de chapitres du bon
  // niveau si absent (signalé : "Chapitre undefined" à l'impression).
  const chapNum = c.n ?? (CHAPITRES_BY_LEVEL[lvl] || CH6).find(x=>x.code===c.code)?.n;
  document.getElementById('printChapHeader').innerHTML = `Chapitre ${chapNum ?? ''}`;
  document.getElementById('printChapBigTitle').textContent = `${c.code} - ${c.t}`.toUpperCase();

  const allIds = new Set();
  Object.values(DEMO_REGISTRY).forEach(d=>{ allIds.add(d.cours); allIds.add(d.methode); allIds.add(d.exos); if(d.histoire) allIds.add(d.histoire); });
  allIds.forEach(id=>{ const el=document.getElementById(id); if(el) el.style.display='none'; });
  document.getElementById('cours-generic').style.display = demo?'none':'block';
  document.getElementById('methode-generic').style.display = demo?'none':'block';
  document.getElementById('exos-generic').style.display = demo?'none':'block';
  document.getElementById('histoire-generic').style.display = (demo && demo.histoire) ? 'none' : 'block';
  if(demo){
    document.getElementById(demo.cours).style.display='block';
    document.getElementById(demo.methode).style.display='block';
    document.getElementById(demo.exos).style.display='block';
    if(demo.histoire) document.getElementById(demo.histoire).style.display='block';
  }

  document.querySelectorAll('.tab-btn').forEach(b=>b.classList.remove('active'));
  document.querySelectorAll('.tab-panel').forEach(p=>p.classList.remove('active'));
  const wantTab = tab||'cours';
  document.querySelector(`.tab-btn[data-tab="${wantTab}"]`).classList.add('active');
  document.getElementById('panel-'+wantTab).classList.add('active');
  document.getElementById('view-chapitre').dataset.onglet = wantTab; // « Exporter en PDF » : onglet Cours seulement

  document.getElementById('quizArea').innerHTML='';
  if(demo) demo.init();
  // Loupe plein écran sur les exercices -- jusqu'ici, injectCourseAddButtons (qui l'injecte)
  // n'était appelée que sur les conteneurs cours/méthode par chaque chapitre, jamais sur les
  // exercices. Fix universel ici, au lieu de modifier chaque fichier de chapitre un par un.
  if(demo) injectZoomButtons(document.getElementById(demo.exos));
  // Cours personnalisés (cours-perso.js) : version du professeur ou de l'établissement.
  const cpFin = typeof cpOnChapterOpen==='function' ? cpOnChapterOpen(demo||null) : null;
  // Petites vignettes d'Oliv'IA (olivia-deco.js) : « À savoir ! », « Muscle ton jeu ! »…
  if(typeof olivDecorer==='function') olivDecorer(demo||null);
  // Questions flash prêtes (flash-prets.js) : bouton pour le professeur, au primaire.
  if(typeof fpMaj==='function') fpMaj(lvl, c.t);
  // Planches d'exercices imprimables (planches.js) : professeur, parent.
  if(typeof plMaj==='function') plMaj(lvl, c);
  if(!silencieux) showView('view-chapitre');
  return cpFin;
}
document.querySelectorAll('.tab-btn').forEach(btn=>{
  btn.addEventListener('click',()=>{
    document.querySelectorAll('.tab-btn').forEach(b=>b.classList.remove('active'));
    document.querySelectorAll('.tab-panel').forEach(p=>p.classList.remove('active'));
    btn.classList.add('active');
    document.getElementById('panel-'+btn.dataset.tab).classList.add('active');
    document.getElementById('view-chapitre').dataset.onglet = btn.dataset.tab;
  });
});

/* ---- draggable point demo ---- */
function svgPointFromEvent(svg,evt){
  const pt = svg.createSVGPoint();
  const t = evt.touches?evt.touches[0]:evt;
  pt.x=t.clientX; pt.y=t.clientY;
  const ctm = svg.getScreenCTM().inverse();
  return pt.matrixTransform(ctm);
}
/* A point that belongs to a line/segment is marked with a short perpendicular tick,
   not a dot -- matches French collège convention. */
function setTick(el, cx, cy, angleRad, len){
  len = len||11;
  const dx = Math.cos(angleRad+Math.PI/2)*len/2, dy = Math.sin(angleRad+Math.PI/2)*len/2;
  el.setAttribute('x1',cx-dx); el.setAttribute('y1',cy-dy);
  el.setAttribute('x2',cx+dx); el.setAttribute('y2',cy+dy);
}
/* Code d'égalité de longueur : un trait fin et INCLINÉ par rapport au segment (convention du
   petit trait oblique), pour ne jamais ressembler à une marque de point (qui, elle, est perpendiculaire). */
function setSlantTick(el, cx, cy, angleRad, len){
  len = len||14;
  const tilt = angleRad + 65*Math.PI/180;
  const dx = Math.cos(tilt)*len/2, dy = Math.sin(tilt)*len/2;
  el.setAttribute('x1',cx-dx); el.setAttribute('y1',cy-dy);
  el.setAttribute('x2',cx+dx); el.setAttribute('y2',cy+dy);
}
/* Registre des démonstrations géométriques pas-à-pas (équerre/règle/réquerre) : chaque chapitre
   y enregistre ses figures pour que l'ajout au cahier puisse reconstituer TOUTES les étapes
   en vignettes côte à côte, plutôt que de figer uniquement l'étape actuellement affichée. */
window.GEO_STEP_DEMOS = window.GEO_STEP_DEMOS || {};
function registerGeoStepDemo(svgId, config){ window.GEO_STEP_DEMOS[svgId] = config; }
/* Même principe que registerGeoStepDemo, mais pour une "scène" mixte (SVG + image HTML
   superposée en CSS, comme les figures du rapporteur) plutôt qu'un simple <svg> isolé.
   config attend : { steps():Array, getIdx():number, goto(i), capture(i):Promise<dataURI> }
   -- capture(i) doit renvoyer une image de TOUTE la scène à l'étape i (voir arCaptureRapporteurScene). */
window.SCENE_STEP_DEMOS = window.SCENE_STEP_DEMOS || {};
function registerSceneStepDemo(sceneId, config){ window.SCENE_STEP_DEMOS[sceneId] = config; }
async function captureSceneFilmstrip(steps, gotoFn, captureFn, originalIdx){
  const panels = [];
  for(let i=0;i<steps.length;i++){
    gotoFn(i);
    const dataUri = await captureFn(i);
    const imgTag = dataUri
      ? `<img src="${dataUri}" style="width:260px;height:auto;border-radius:6px;border:1px solid rgba(28,43,57,.12);flex:none;display:block;" alt="Étape ${i+1}"/>`
      : `<div style="width:260px;height:150px;flex:none;background:#f2f2f2;border-radius:6px;border:1px solid rgba(28,43,57,.12);"></div>`;
    panels.push(`<div style="display:flex;align-items:center;gap:14px;flex-wrap:wrap;">
      ${imgTag}
      <div style="font-size:.8rem;color:var(--ink-soft);line-height:1.4;"><b>Étape ${i+1}.</b> ${steps[i].note}</div>
    </div>`);
  }
  gotoFn(originalIdx);
  return `<div class="cahier-film" style="display:flex;flex-direction:column;gap:14px;">${panels.join('')}</div>`;
}
/* Convertit un SVG en image PNG (data URI), rastérisée à une taille en pixels fixe
   et explicite (plutôt que de compter sur un <img> pour redimensionner un SVG, ce
   qu'html2canvas gère de façon peu fiable -- images énormes, tronquées ou absentes). */
/* Copie, sous forme d'attribut style inline, l'apparence RÉELLEMENT appliquée (via CSS calculé)
   de chaque élément du SVG en direct vers son clone -- indispensable car les classes CSS
   externes (ex. .vertex-handle{fill:transparent} pour les poignées de glisser-déposer, invisibles
   au repos) ne sont pas incluses quand le SVG est sérialisé et rendu isolément comme une image :
   sans ça, ces éléments retombent sur le remplissage noir par défaut du SVG. */
function inlineComputedStyles(liveRoot, cloneRoot){
  const props = ['fill','stroke','stroke-width','stroke-dasharray','stroke-linecap','stroke-linejoin',
    'opacity','fill-opacity','stroke-opacity','font-family','font-size','font-weight','text-anchor'];
  const liveEls = [liveRoot, ...liveRoot.querySelectorAll('*')];
  const cloneEls = [cloneRoot, ...cloneRoot.querySelectorAll('*')];
  const n = Math.min(liveEls.length, cloneEls.length);
  for(let i=0;i<n;i++){
    let cs;
    try{ cs = getComputedStyle(liveEls[i]); } catch(e){ continue; }
    let extra = '';
    props.forEach(p=>{
      const val = cs.getPropertyValue(p);
      if(val) extra += `${p}:${val};`;
    });
    const existing = cloneEls[i].getAttribute('style') || '';
    cloneEls[i].setAttribute('style', existing + ';' + extra);
  }
}
/* Convention d'impression pour les points d'une figure (voir aussi setTick/setCross) :
   - un sommet de polygone/triangle ne se marque pas d'un point (l'intersection des côtés suffit) ;
   - une extrémité, une origine ou un point sur une droite se marque d'une petite croix.
   Les points concernés portent l'attribut data-marker="hidden" ou "cross" dans le SVG source ;
   cette fonction les transforme juste avant la rastérisation (elle ne touche jamais à la version
   interactive à l'écran, seulement au clone utilisé pour le cahier/PDF). */
function applyPrintMarkers(clone){
  clone.querySelectorAll('[data-marker]').forEach(el=>{
    const role = el.getAttribute('data-marker');
    if(role === 'hidden'){ el.remove(); return; }
    if(role === 'cross'){
      const style = el.getAttribute('style') || '';
      const isInvisible = /(^|;)\s*display\s*:\s*none/.test(style) || /(^|;)\s*opacity\s*:\s*0(?:[^.\d]|$)/.test(style) || el.getAttribute('opacity')==='0'; // « fill-opacity:0 » n'est PAS invisible : c'est un point dessiné en croix à l'écran (6e G2)
      if(isInvisible){ el.remove(); return; }
      const cx = parseFloat(el.getAttribute('cx')||0);
      const cy = parseFloat(el.getAttribute('cy')||0);
      const color = el.getAttribute('fill') || '#1C1B2E';
      const size = 6;
      const g = document.createElementNS('http://www.w3.org/2000/svg','g');
      g.innerHTML = `<line x1="${cx-size}" y1="${cy-size}" x2="${cx+size}" y2="${cy+size}" stroke="${color}" stroke-width="1.6" stroke-linecap="round"/>`
        + `<line x1="${cx-size}" y1="${cy+size}" x2="${cx+size}" y2="${cy-size}" stroke="${color}" stroke-width="1.6" stroke-linecap="round"/>`;
      el.replaceWith(g);
    }
  });
}
/* Les images insérées dans un SVG (ex. la réquerre, une photo PNG posée par <image href="assets/...">)
   ne sont PAS chargées quand le SVG est lui-même affiché comme image (règle de sécurité des
   navigateurs) : elles disparaissaient du cahier et du PDF -- signalé : « les réquerres disparaissent
   sur le document ». On les remplace dans le clone par leur contenu en data URI (mis en cache). */
const svgImagesCache = {};
async function inlineSvgImages(clone){
  const XLINK = 'http://www.w3.org/1999/xlink';
  for(const im of Array.from(clone.querySelectorAll('image'))){
    const href = im.getAttribute('href') || im.getAttributeNS(XLINK, 'href');
    if(!href || href.startsWith('data:')) continue;
    try{
      if(!svgImagesCache[href]){
        svgImagesCache[href] = fetch(new URL(href, location.href)).then(r=>{ if(!r.ok) throw new Error('HTTP '+r.status); return r.blob(); })
          .then(blob=>new Promise((res, rej)=>{ const fr = new FileReader(); fr.onload = ()=>res(fr.result); fr.onerror = rej; fr.readAsDataURL(blob); }));
      }
      const data = await svgImagesCache[href];
      im.setAttribute('href', data);
      im.removeAttributeNS(XLINK, 'href');
    } catch(e){ delete svgImagesCache[href]; console.warn('svgToRasterDataUri: image non intégrée', href, e); }
  }
}
function svgToRasterDataUri(svgEl, displayWidth){
  return new Promise(async (resolve)=>{
    const vbAttr = svgEl.getAttribute('viewBox');
    const vbParts = vbAttr ? vbAttr.trim().split(/\s+/).map(Number) : [0,0,400,240];
    const vbW = vbParts[2] || 400, vbH = vbParts[3] || 240;
    // Un chapitre peut mettre sa figure à jour juste avant la photo (ex. 6e G2 : repères des points).
    (window.AVANT_CAPTURE_SVG || []).forEach(f=>{ try{ f(svgEl); } catch(e){ console.error('svgToRasterDataUri: AVANT_CAPTURE_SVG', e); } });
    const clone = svgEl.cloneNode(true);
    if(document.contains(svgEl)){
      try{ inlineComputedStyles(svgEl, clone); } catch(e){ console.error('svgToRasterDataUri: échec figement des styles', e); }
    } // sinon (figure statique déjà détachée) : ses attributs littéraux sont fiables tels quels --
      // les calculer via getComputedStyle sur un nœud détaché résoudrait mal les variables CSS et
      // écraserait les bonnes valeurs par des valeurs par défaut.
    try{ applyPrintMarkers(clone); } catch(e){ console.error('svgToRasterDataUri: échec transformation des marqueurs', e); }
    clone.removeAttribute('id');
    clone.querySelectorAll('[id]').forEach(el=>el.removeAttribute('id'));
    clone.removeAttribute('style');
    clone.setAttribute('width', vbW);
    clone.setAttribute('height', vbH);
    clone.setAttribute('xmlns', 'http://www.w3.org/2000/svg');
    try{ await inlineSvgImages(clone); } catch(e){ console.error('svgToRasterDataUri: échec intégration des images', e); }
    let svgDataUri;
    try{
      const svgString = new XMLSerializer().serializeToString(clone);
      svgDataUri = 'data:image/svg+xml;base64,' + btoa(unescape(encodeURIComponent(svgString)));
    } catch(e){ console.error('svgToRasterDataUri: échec de sérialisation', e); resolve(null); return; }
    const img = new Image();
    const scale = 2; // netteté sur écrans haute densité / impression
    const displayHeight = displayWidth * (vbH / vbW);
    img.onload = () => {
      try{
        const canvas = document.createElement('canvas');
        canvas.width = Math.round(displayWidth*scale);
        canvas.height = Math.round(displayHeight*scale);
        const ctx = canvas.getContext('2d');
        ctx.imageSmoothingEnabled = true;
        if('imageSmoothingQuality' in ctx) ctx.imageSmoothingQuality = 'high';
        ctx.fillStyle = '#ffffff';
        ctx.fillRect(0,0,canvas.width,canvas.height);
        ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
        resolve(canvas.toDataURL('image/png'));
      } catch(e){ console.error('svgToRasterDataUri: échec de rastérisation', e); resolve(null); }
    };
    img.onerror = (e) => { console.error('svgToRasterDataUri: échec de chargement de l\'image SVG', e); resolve(null); };
    img.src = svgDataUri;
  });
}
async function captureGeoFilmstrip(svgEl, steps, gotoFn, originalIdx){
  const panels = [];
  for(let i=0;i<steps.length;i++){
    gotoFn(i, false);
    const dataUri = await svgToRasterDataUri(svgEl, 360); // 360 px : net aussi en lecture étape par étape (cahier à l'écran)
    const imgTag = dataUri
      ? `<img src="${dataUri}" style="width:170px;height:auto;border-radius:6px;border:1px solid rgba(28,43,57,.12);flex:none;display:block;" alt="Étape ${i+1}"/>`
      : `<div style="width:170px;height:100px;flex:none;background:#f2f2f2;border-radius:6px;border:1px solid rgba(28,43,57,.12);"></div>`;
    panels.push(`<div style="display:flex;align-items:center;gap:14px;flex-wrap:wrap;">
      ${imgTag}
      <div style="font-size:.8rem;color:var(--ink-soft);line-height:1.4;"><b>Étape ${i+1}.</b> ${steps[i].note}</div>
    </div>`);
  }
  gotoFn(originalIdx, false);
  return `<div class="cahier-film" style="display:flex;flex-direction:column;gap:14px;">${panels.join('')}</div>`;
}

/* ---- Pas à pas dans le cahier : lecture étape par étape à l'écran ----
   Demandé : "On avait évoqué le fait de mettre les pas à pas dans le cahier (sauf à l'impression).
   j'ai inséré les constructions des symétriques dans un quadrillage mais on perd l'aspect animation".
   L'ajout au cahier enregistre toujours toutes les étapes en images (captureGeoFilmstrip /
   captureSceneFilmstrip) : c'est ce qui s'imprime. À l'écran, chaque suite d'étapes du cahier (y
   compris celles ajoutées avant ce changement, reconnues à leurs vignettes « Étape n. ») devient un
   lecteur : une étape à la fois, Précédente / Suivante, « Animer » (défilement automatique) et
   « Tout voir ». L'impression et le PDF (fenêtre à part) gardent la colonne complète. */
function cahierAnimerEtapes(root){
  (root || document).querySelectorAll('.view .nb-body:not([data-cs-vu])').forEach(corps=>{ corps.dataset.csVu = '1'; corps.querySelectorAll('div').forEach(d=>{
    const kids = Array.from(d.children);
    if(kids.length < 2 || !kids.every(k => k.tagName==='DIV' && k.querySelector(':scope > img') && /^\s*Étape\s+\d+/.test(k.textContent||''))) return;
    d.dataset.csFait = '1'; d.classList.add('cs-film'); d.dataset.csI = '0';
    kids.forEach((k,i)=>{ k.classList.add('cs-panel'); k.classList.toggle('cs-on', i===0); });
    const bar = document.createElement('div'); bar.className = 'cs-bar';
    bar.innerHTML = `<button type="button" data-cs="prev" title="Étape précédente" disabled>‹</button><span class="cs-n">Étape 1 / ${kids.length}</span>
      <button type="button" data-cs="next" class="cs-main">Étape suivante ›</button><button type="button" data-cs="play" title="Faire défiler les étapes automatiquement">▶ Animer</button>
      <button type="button" data-cs="all" title="Afficher toutes les étapes l'une sous l'autre">Tout voir</button>`;
    d.parentNode.insertBefore(bar, d);
    if(cahierDemoDuFilm(d)) cahierEtape(d, -1); // démonstration rejouable : on part de la figure de départ
  }); });
}
function cahierEtape(film, i, animer){
  const kids = Array.from(film.children), n = kids.length, bar = film.previousElementSibling, d = cahierDemoDuFilm(film);
  // Avec une démonstration rejouable, le lecteur commence à la figure de départ (i = -1), avant l'étape 1.
  const min = d ? -1 : 0;
  i = Math.max(min, Math.min(n-1, i)); film.dataset.csI = String(i);
  cahierStopEtape(film);
  kids.forEach((k,j)=>{ k.classList.toggle('cs-on', j===Math.max(i,0)); k.classList.remove('cs-anime','cs-depart'); k.querySelectorAll(':scope > svg.cs-vivant, :scope > .cs-dep').forEach(x=>x.remove()); });
  if(bar){ bar.querySelector('.cs-n').textContent = i<0 ? 'Départ' : `Étape ${i+1} / ${n}`; bar.querySelector('[data-cs="prev"]').disabled = i===min; bar.querySelector('[data-cs="next"]').disabled = i===n-1; }
  if(!d) return;
  if(i<0) cahierJouerEtape(film, 0, null, 'depart');
  else cahierJouerEtape(film, i, null, animer ? '' : 'fin'); // même dessin que le chapitre (polices comprises), animé ou non
}
/* Mouvements intermédiaires. Demandé : "ça ne montre pas toutes les étapes !" -> "Les mouvements
   intermédiaires". Le cahier ne garde qu'une image par étape (c'est ce qui s'imprime) ; quand la
   figure vient d'une démonstration qui sait se redessiner à tout instant (config.anim de
   registerGeoStepDemo, ex. constructions dans un quadrillage), le lecteur retrouve cette démonstration
   par le texte de ses étapes -- y compris pour les entrées déjà ajoutées -- et rejoue l'étape par-dessus
   l'image : flèches qui avancent carreau par carreau, numéros, points qui apparaissent. */
function cahierDemoDuFilm(film){
  if(film._csDemo !== undefined) return film._csDemo;
  const norm = t => String(t||'').replace(/\s+/g,' ').trim(), tmp = document.createElement('div');
  const notes = Array.from(film.children).map(k => { const t = k.querySelector(':scope > div'); return norm((t ? t.textContent : '').replace(/^\s*Étape\s+\d+\.\s*/, '')); });
  let trouve = null;
  Object.values(window.GEO_STEP_DEMOS || {}).some(d => {
    if(!d || !d.anim || typeof d.steps !== 'function') return false;
    let st; try{ st = d.steps(); }catch(e){ return false; }
    if(!st || st.length !== notes.length) return false;
    const ok = st.every((x,i) => { tmp.innerHTML = x.note; return norm(tmp.textContent) === notes[i]; });
    if(ok) trouve = d;
    return ok;
  });
  if(trouve){ film._csDemo = trouve; film.classList.add('cs-a'); film.querySelectorAll(':scope > .cs-panel > img').forEach(im => { im.title = 'Cliquer pour rejouer les mouvements de cette étape'; }); }
  return trouve; // pas mémorisé si absent : le chapitre peut s'enregistrer plus tard
}
function cahierStopEtape(film){ cancelAnimationFrame(film._csRaf); clearTimeout(film._csT); film._csRaf = film._csT = null; }
// Rejoue l'étape i du film ; fin() est appelée une fois le mouvement terminé (ou tout de suite sans démonstration).
// fige = 'depart' (figure avant l'étape 1) ou 'fin' (étape i terminée) : dessin sans mouvement.
function cahierJouerEtape(film, i, fin, fige){
  cahierStopEtape(film);
  const d = cahierDemoDuFilm(film), panel = film.children[i];
  if(!d || !panel){ if(fin) fin(0); return; }
  panel.classList.remove('cs-depart'); panel.querySelectorAll(':scope > .cs-dep').forEach(x=>x.remove());
  let v = panel.querySelector(':scope > svg.cs-vivant');
  if(!v){
    v = document.createElementNS('http://www.w3.org/2000/svg', 'svg'); v.setAttribute('class', 'cs-vivant'); v.setAttribute('viewBox', d.anim.viewBox);
    // Largeur/hauteur explicites (+ aspect-ratio) : sans elles, Safari (iPhone) peut donner une hauteur nulle
    // à un SVG en width:100% / height:auto dans un conteneur flex -- la figure disparaissait sur smartphone.
    const vb = String(d.anim.viewBox).split(/[\s,]+/).map(Number);
    if(vb[2] > 0 && vb[3] > 0){ v.setAttribute('width', vb[2]); v.setAttribute('height', vb[3]); v.style.aspectRatio = vb[2] + ' / ' + vb[3]; }
    panel.insertBefore(v, panel.firstChild);
  }
  panel.classList.add('cs-anime');
  // Filet de sécurité : si la figure redessinée n'a pas de taille à l'écran, on revient à l'image enregistrée.
  requestAnimationFrame(() => { if(v.isConnected && panel.classList.contains('cs-on') && !film.classList.contains('cs-tout') && panel.getBoundingClientRect().width > 50 && v.getBoundingClientRect().height < 20){
    film._csDemo = null; film.classList.remove('cs-a'); cahierEtape(film, Math.max(0, Number(film.dataset.csI)||0)); } });
  const n = Math.max(1, d.anim.n(i)), t0 = performance.now();
  if(fige){
    try{ v.innerHTML = d.anim.rendu(i, fige === 'depart' ? 0 : n); }catch(e){ panel.classList.remove('cs-anime'); v.remove(); return; }
    if(fige === 'depart'){
      panel.classList.add('cs-depart');
      const t = document.createElement('div'); t.className = 'cs-dep';
      t.textContent = 'Figure de départ. Cliquez sur « Étape suivante » (ou sur la figure) pour voir la construction pas à pas, ou sur « ▶ Animer » pour tout enchaîner.';
      panel.appendChild(t);
    }
    return;
  }
  const tic = now => {
    if(!v.isConnected){ cahierStopEtape(film); return; }
    const p = Math.min(n, (now - t0) / 650);
    try{ v.innerHTML = d.anim.rendu(i, p); }catch(e){ panel.classList.remove('cs-anime'); v.remove(); if(fin) fin(0); return; }
    if(p < n) film._csRaf = requestAnimationFrame(tic); else if(fin) fin(1);
  };
  v.innerHTML = d.anim.rendu(i, 0);
  film._csRaf = requestAnimationFrame(tic);
}
function cahierStopLecture(film, bar){
  film._csLecture = false; cahierStopEtape(film);
  const b = bar && bar.querySelector('[data-cs="play"]'); if(b) b.textContent = '▶ Animer';
}
document.addEventListener('click', e=>{
  // Clic sur la figure d'une étape : on rejoue ses mouvements.
  const fig = e.target.closest('.cs-film.cs-a .cs-panel.cs-on > img, .cs-film.cs-a .cs-panel.cs-on > svg.cs-vivant');
  if(fig){ const film = fig.closest('.cs-film'), k = Number(film.dataset.csI)||0; cahierStopLecture(film, film.previousElementSibling);
    if(k<0) cahierEtape(film, 0, true); else cahierJouerEtape(film, k); return; }
  const b = e.target.closest('.cs-bar [data-cs]'); if(!b) return;
  const bar = b.closest('.cs-bar'), film = bar.nextElementSibling; if(!film || !film.classList.contains('cs-film')) return;
  const i = Number(film.dataset.csI)||0, n = film.children.length, act = b.dataset.cs;
  if(act==='play' && film._csLecture){ cahierStopLecture(film, bar); return; }
  cahierStopLecture(film, bar);
  if(act==='prev') cahierEtape(film, i-1);
  else if(act==='next') cahierEtape(film, i+1, true);
  else if(act==='all'){ cahierEtape(film, Math.max(i,0)); const tout = film.classList.toggle('cs-tout'); b.textContent = tout ? 'Une étape à la fois' : 'Tout voir'; bar.classList.toggle('cs-tout', tout); }
  else if(act==='play'){
    film.classList.remove('cs-tout'); bar.classList.remove('cs-tout'); bar.querySelector('[data-cs="all"]').textContent = 'Tout voir';
    film._csLecture = true; b.textContent = '⏸ Pause';
    // Chaque étape joue ses mouvements, puis courte pause avant la suivante (1,6 s par étape sans démonstration).
    const suite = k => {
      if(!film._csLecture || !film.isConnected) return;
      cahierEtape(film, k);
      cahierJouerEtape(film, k, anime => {
        if(!film._csLecture) return;
        film._csT = setTimeout(() => { if(k >= n-1) cahierStopLecture(film, bar); else suite(k+1); }, anime ? 1100 : 1600);
      });
    };
    suite(i>=n-1 || i<0 ? 0 : i);
  }
});
// Les cahiers sont rendus à plusieurs endroits (cahier de la classe, accordéon par jour, correction) :
// on transforme chaque suite d'étapes dès qu'elle apparaît à l'écran.
let csPlanifie = false;
new MutationObserver(()=>{ if(csPlanifie) return; csPlanifie = true; requestAnimationFrame(()=>{ csPlanifie = false; cahierAnimerEtapes(document); }); }).observe(document.body, { childList:true, subtree:true });

// Dessin d'une méthode pas à pas (demandé : « il y a des consignes sans illustrations, c'est compliqué ») :
// une étape peut porter fig (le dessin à cette étape) ; sinon on garde le dernier dessin donné.
function stepAvecFig(col, steps, idx){
  let fig = null; for(let i = idx; i >= 0 && fig == null; i--) if(steps[i].fig != null) fig = steps[i].fig;
  return fig ? `<div class="step-avec-fig">${col}<div class="step-fig">${fig}</div></div>` : col;
}
function makeStepDemo(steps, displayId){
  let idx = 0;
  function render(){
    const el = document.getElementById(displayId);
    if(!el) return;
    el._stepDemoSteps = steps; // permet à l'ajout au cahier de reconstituer toutes les étapes, pas juste l'étape affichée
    const atEnd = idx === steps.length-1;
    const lines = steps.slice(0, idx+1).map((s,i)=>{
      const isFinal = atEnd && i===idx;
      return `<div class="${isFinal?'step-final':''}">${s.expr}</div>`;
    }).join('');
    el.innerHTML = stepAvecFig(`<div class="step-column">${lines}</div>`, steps, idx) + `<div class="step-note">${steps[idx].note}</div>`;
    renderStaticMath(el);
  }
  return {
    next(){ if(idx<steps.length-1) idx++; render(); },
    reset(){ idx=0; render(); },
    render,
  };
}
/* Variante SANS empilement : n'affiche que l'étape courante (qui remplace la précédente),
   jamais l'historique complet -- demandé : "sans écrire des lignes et des lignes. Il y a une
   seule expression qui se remplit petit à petit". Utile pour une démo où l'expression ELLE-
   MÊME évolue visuellement d'une étape à l'autre (ex. un squelette qui se complète), plutôt
   qu'un calcul qui se déroule pas à pas (où voir chaque ligne précédente a du sens). */
function makeSingleStepDemo(steps, displayId){
  let idx = 0;
  function render(){
    const el = document.getElementById(displayId);
    if(!el) return;
    el._stepDemoSteps = steps;
    el.innerHTML = stepAvecFig(`<div class="step-column"><div>${steps[idx].expr}</div></div>`, steps, idx) + `<div class="step-note">${steps[idx].note}</div>`;
    renderStaticMath(el);
  }
  return {
    next(){ if(idx<steps.length-1) idx++; render(); },
    reset(){ idx=0; render(); },
    render,
  };
}
/* Révèle une justification rédigée ligne par ligne, au clic sur "Étape suivante" -- même mise en
   page que .redaction-template/.we-row (voir la "Rédaction type" de chaque chapitre), mais pour
   la correction d'un exercice de rédaction/démonstration : chaque étape ajoute la phrase
   suivante au lieu de tout montrer d'un coup. rows: [{expr, comment}] (comment optionnel) --
   .we-row:last-child met déjà en évidence la dernière ligne (la conclusion) via le CSS existant. */
function makeRedactionStepDemo(rows, displayId){
  let idx = 0;
  function render(){
    const el = document.getElementById(displayId);
    if(!el) return;
    const lines = rows.slice(0, idx+1).map(r=>
      `<div class="we-row"><span class="we-expr">${r.expr}</span><span class="we-comment">${r.comment||''}</span></div>`
    ).join('');
    el.innerHTML = `<div class="redaction-template">${lines}</div>`;
  }
  return {
    next(){ if(idx<rows.length-1) idx++; render(); },
    reset(){ idx=0; render(); },
    render,
  };
}
function rotateAroundPoint(p, center, angleDeg){
  const a = angleDeg*Math.PI/180;
  const dx=p.x-center.x, dy=p.y-center.y;
  return {x:center.x+dx*Math.cos(a)-dy*Math.sin(a), y:center.y+dx*Math.sin(a)+dy*Math.cos(a)};
}
function setCross(el1,el2,cx,cy,size){
  size=size||6;
  el1.setAttribute('x1',cx-size); el1.setAttribute('y1',cy-size); el1.setAttribute('x2',cx+size); el1.setAttribute('y2',cy+size);
  el2.setAttribute('x1',cx-size); el2.setAttribute('y1',cy+size); el2.setAttribute('x2',cx+size); el2.setAttribute('y2',cy-size);
}

/* ---- 2.A : symétrique d'une droite (dynamique) ---- */
async function callClaude(userPrompt, maxTokens, meta){
  const { data:{ session } } = await sb.auth.getSession();
  if(!session) throw new Error('no-session');
  const res = await fetch(SUPABASE_URL+'/functions/v1/ai-proxy', {
    method:'POST',
    headers:{ 'Content-Type':'application/json', 'Authorization': 'Bearer '+session.access_token },
    // meta.images : [{media_type, data(base64)}] -- photos jointes (professeurs, voir ai-proxy v18).
    body: JSON.stringify({ prompt: userPrompt, maxTokens: maxTokens||800, feature:(meta&&meta.feature)||null, chapitre:(meta&&meta.chapitre)||null, niveau:(meta&&meta.niveau)||null, images:(meta&&meta.images)||undefined }),
  });
  const data = await res.json();
  if(data.error) throw new Error(data.error);
  return data.text || '';
}

/* ---- quiz demo (static, standing in for the future AI call) ---- */
const DEMO_QUIZZES = {};
let currentQuizBank = null;
function renderQuizHTML(bank, prefixHtml){
  const area=document.getElementById('quizArea');
  currentQuizBank = bank;
  let html = prefixHtml || '';
  bank.forEach((item,qi)=>{
    // « Question 1 » au-dessus de l'énoncé, et non « 1. » devant -- demandé : ne pas numéroter « 1. »,
    // « 2. » devant une question, surtout si elle commence par un nombre ou un calcul.
    html+=`<div class="quiz-q"><div class="quiz-num">Question ${qi+1}</div><div style="font-weight:600;margin-bottom:8px;">${item.q}</div>`;
    item.opts.forEach((o,oi)=>{
      html+=`<button class="quiz-opt" onclick="answerQuiz(this,${qi},${oi})">${o}</button>`;
    });
    html+='</div>';
  });
  area.innerHTML=html;
  renderStaticMath(area); // fractions en LaTeX (cm1Frac) dans les questions et les réponses
}
function generateDemoQuiz(){
  const bank = DEMO_QUIZZES[currentChapterLevel+'|'+currentChapterTitle] || DEMO_QUIZZES['5e|Symétrie centrale'];
  renderQuizHTML(bank, '<p class="hint">Démonstration avec des questions pré-écrites.</p>');
}
async function generateQuiz(){
  const area = document.getElementById('quizArea');
  if(!currentUser){ area.innerHTML = '<p class="hint">Connectez-vous pour générer un quiz par IA (ou essayez la démo pré-écrite ci-dessous).</p>'; return; }
  const content = getVisibleCoursContent();
  const courseText = (content.innerText || content.textContent || '').trim();
  if(!courseText){ area.innerHTML = '<p class="hint">Aucun contenu de cours disponible pour ce chapitre.</p>'; return; }
  area.innerHTML = '<p class="hint">Génération du quiz en cours…</p>';
  const prompt = `Tu es ${iaEnseignant(currentChapterLevel)}. ${iaContexteNiveau(currentChapterLevel)}
Voici le cours d'un chapitre :

${courseText.slice(0,6000)}

Génère un quiz de 5 questions à choix multiples pour vérifier la compréhension de ce cours, adaptées à son niveau. Chaque question a exactement 3 options, une seule correcte. Réponds UNIQUEMENT avec un tableau JSON valide (sans texte avant ni après, sans balises markdown), au format exact :
[{"q":"...","opts":["...","...","..."],"correct":0}]
Le champ "correct" est l'index (0, 1 ou 2) de la bonne réponse dans "opts".`;
  try{
    const raw = await callClaude(prompt, 1500, {feature:'quiz', chapitre:currentChapterTitle});
    const match = raw.match(/\[[\s\S]*\]/);
    if(!match) throw new Error('no-json');
    const quiz = JSON.parse(match[0]);
    if(!Array.isArray(quiz) || !quiz.length) throw new Error('empty');
    renderQuizHTML(quiz, '<p class="hint">✓ Quiz généré par IA à partir de ce cours.</p>');
  }catch(err){
    area.innerHTML = '<p class="hint"><span class=gicon>warning</span> Échec de la génération'+(err.message==='no-session'?' (connectez-vous)':'')+'. Réessayez, ou utilisez la démo pré-écrite ci-dessous.</p>';
  }
}
function answerQuiz(btn,qi,oi){
  const parent=btn.parentElement;
  const correct=currentQuizBank[qi].correct;
  parent.querySelectorAll('.quiz-opt').forEach((b,i)=>{
    b.disabled=true;
    if(i===correct) b.classList.add('correct');
    else if(i===oi) b.classList.add('wrong');
  });
}

/* ======================= AUTOMATISMES ======================= */
/* Voir calcul-mental/calcul-mental.js, chargé en fin de page. */


/* ======================= EXPORT DU COURS (PDF réel via html2pdf, sans popup) ======================= */
function getVisibleCoursContent(){
  const panel = document.getElementById('panel-cours');
  for(const child of panel.children){
    if(child.tagName==='DIV' && !child.classList.contains('figure-toolbar') && getComputedStyle(child).display!=='none') return child;
  }
  return panel;
}
/* Clique réellement (comme le ferait un utilisateur) sur chaque bouton "Étape suivante"
   trouvé, plusieurs fois de suite, jusqu'à ce que le contenu de sa démo ne change plus --
   déroule ainsi n'importe quelle démonstration par étapes jusqu'à sa fin, AVANT capture PDF,
   sans avoir besoin de connaître les noms internes des fonctions/variables propres à chaque
   chapitre (schéma répété dans une trentaine de chapitres, signalé : "on n'a que la première
   étape... afficher la dernière étape pour voir la division dans son entièreté"). Agit sur la
   page RÉELLE (avant clonage), donc le contenu cloné juste après reflète déjà la fin de
   chaque démo.
   Effet de bord assumé : les démos affichées à l'écran sautent aussi à leur dernière étape
   après un export PDF (l'utilisateur peut cliquer "Recommencer" pour les réinitialiser). */
function advanceAllStepDemosToEnd(container){
  const buttons = Array.from(container.querySelectorAll('button')).filter(b=>b.textContent.trim().startsWith('Étape suivante'));
  const avances = [];
  for(const btn of buttons){
    const wrap = btn.closest('.figure-wrap');
    for(let i=0;i<40;i++){
      const before = wrap ? wrap.innerHTML : null;
      btn.click();
      const after = wrap ? wrap.innerHTML : null;
      if(before===after) break; // plus aucun changement -- dernière étape déjà atteinte
      if(wrap && !avances.includes(wrap)) avances.push(wrap);
    }
  }
  return avances;
}
/* Remet à leur première étape les démonstrations que l'export ou l'impression a fait avancer --
   signalé : « quand on lance l'impression/pdf, je perds des informations sur la page (plus de
   réquerre par exemple) » : les figures restaient figées à leur dernière étape (« On retire la
   réquerre »). On clique sur le bouton « Recommencer » de chacune, une fois la capture terminée. */
function resetAdvancedStepDemos(wraps){
  (wraps || []).forEach(wrap=>{
    const btn = Array.from(wrap.querySelectorAll('button')).find(b=>b.textContent.trim().startsWith('Recommencer'));
    if(btn) btn.click();
  });
}
// Même mécanisme pour l'impression native (Ctrl/Cmd+P), pas seulement le bouton "Télécharger
// en PDF" -- déroule les démos de la vue actuellement affichée avant que le navigateur ne
// capture la page pour l'impression. IMPORTANT : reste synchrone (pas d'await/setTimeout) --
// l'événement beforeprint n'attend JAMAIS la résolution d'une promesse avant de continuer,
// une version asynchrone risquerait de ne pas avoir fini avant la capture réelle.
let demosAvanceesImpression = [];
window.addEventListener('beforeprint', ()=>{ demosAvanceesImpression = advanceAllStepDemosToEnd(document.body); });
window.addEventListener('afterprint', ()=>{ resetAdvancedStepDemos(demosAvanceesImpression); demosAvanceesImpression = []; });
async function advanceAllStepDemosToEndAsync(container){
  const buttons = Array.from(container.querySelectorAll('button')).filter(b=>b.textContent.trim().startsWith('Étape suivante'));
  const avances = [];
  for(const btn of buttons){
    const wrap = btn.closest('.figure-wrap');
    for(let i=0;i<40;i++){
      const before = wrap ? wrap.innerHTML : null;
      btn.click();
      const after = wrap ? wrap.innerHTML : null;
      if(before===after) break; // plus aucun changement -- dernière étape déjà atteinte
      if(wrap && !avances.includes(wrap)) avances.push(wrap);
    }
    await new Promise(r=>setTimeout(r,0)); // laisse le navigateur respirer entre chaque démo, évite l'alerte "page ne répond pas"
  }
  return avances;
}
// Option de masquage réservée aux profs/admins (signalé : "en mode connecté prof... une
// option pour éditer les pdf en demandant quel contenu on veut masquer") -- les élèves n'ont
// pas d'usage de cette option, export direct pour eux sans passer par la modale.
function openExportPdfOptions(){
  if(typeof familleSansImpression==='function' && familleSansImpression()) return;
  if(!isStaffGlobal){ exportCoursPDF(); return; }
  document.getElementById('exportHideDefinitions').checked = false;
  document.getElementById('exportHideProprietes').checked = false;
  document.getElementById('exportHideRegles').checked = false;
  populateExportParagraphChoices();
  document.getElementById('exportPdfOptionsOverlay').style.display='flex';
}
function closeExportPdfOptions(){
  document.getElementById('exportPdfOptionsOverlay').style.display='none';
}
// Liste les paragraphes numérotés (.lesson-header) du chapitre actuellement affiché, sous
// forme de cases à cocher, toutes cochées par défaut (= comportement précédent : tout
// exporter) -- signalé : "il serait mieux de pouvoir dire aussi quel paragraphe on souhaite
// exporter".
function populateExportParagraphChoices(){
  const box = document.getElementById('exportParagraphChoices');
  const headers = getVisibleCoursContent().querySelectorAll(':scope > .lesson-header:not(.cp-hidden)');
  if(!headers.length){ box.innerHTML = '<span class="hint">(chapitre sans paragraphes numérotés -- export intégral)</span>'; return; }
  box.innerHTML = Array.from(headers).map(h=>{
    const num = h.querySelector('.num')?.textContent.trim() || '';
    const title = h.querySelector('h3')?.textContent.trim() || '';
    return `<label class="hint" style="display:block;margin:0 0 6px;"><input type="checkbox" class="export-paragraph-check" data-num="${num}" checked> ${num}. ${title}</label>`;
  }).join('');
}
function toggleAllExportParagraphs(){
  const boxes = document.querySelectorAll('.export-paragraph-check');
  const allChecked = Array.from(boxes).every(b=>b.checked);
  boxes.forEach(b=>{ b.checked = !allChecked; });
}
// Retire du clone tout ce qui appartient à un paragraphe numéroté décoché. Structure ciblée :
// tous les éléments d'un même paragraphe (badges, def-box, figures...) sont des frères
// directs entre un .lesson-header et le suivant (jamais imbriqués dans un conteneur par
// paragraphe) -- on bascule donc un simple booléen "keep" à chaque .lesson-header rencontré.
function filterCoursByParagraph(clone){
  const checks = Array.from(document.querySelectorAll('.export-paragraph-check'));
  if(!checks.length || checks.every(c=>c.checked)) return; // rien de décoché -- export intégral, inchangé
  const selectedNums = new Set(checks.filter(c=>c.checked).map(c=>c.dataset.num));
  let keep = true;
  Array.from(clone.children).forEach(el=>{
    if(el.classList.contains('lesson-header')){
      keep = selectedNums.has(el.querySelector('.num')?.textContent.trim());
    }
    if(!keep) el.remove();
  });
}
/* Vide le contenu de chaque encadré définition/propriété/règle sélectionné pour être masqué,
   sans retirer l'encadré lui-même (qui reste visible, avec son étiquette) -- laisse de la
   place pour l'écriture manuscrite. Structure ciblée : <span class="def-badge|prop-badge">
   LIBELLÉ</span> suivi directement d'un <div class="def-box">contenu</div> -- la catégorie
   (Définitions/Propriétés/Règle(s)) se lit uniquement dans le TEXTE du badge, pas dans une
   classe CSS dédiée (prop-badge sert à la fois pour "Propriétés" ET "Règle"/"Règles"). */
function blankOutSelectedBoxes(clone){
  const hideDef = document.getElementById('exportHideDefinitions')?.checked;
  const hideProp = document.getElementById('exportHideProprietes')?.checked;
  const hideRegle = document.getElementById('exportHideRegles')?.checked;
  if(!hideDef && !hideProp && !hideRegle) return;
  // Lignes fines en pointillés (façon papier réglé) à la place du contenu masqué, pour
  // guider l'écriture manuscrite de l'élève -- 4 lignes, hauteur proche de l'espace laissé
  // avant (3 <br>).
  const writingLines = Array.from({length:4}).map(()=>
    '<div style="border-bottom:1px dotted #999;height:22px;margin-bottom:6px;"></div>'
  ).join('');
  clone.querySelectorAll('.def-badge, .prop-badge').forEach(badge=>{
    const label = badge.textContent.trim();
    // startsWith (pas ===) : les badges varient en nombre et en singulier/pluriel selon les
    // chapitres ("Propriété", "Propriété 1", "Propriétés 2", "Définition", "Définitions"...) --
    // une égalité stricte ne matchait que la forme plurielle sans numéro, ratant la grande
    // majorité des badges "Propriété" (signalé : "j'avais coché de ne pas mettre... il a mis
    // les propriétés").
    const shouldHide = (label.startsWith('Définition') && hideDef) || (label.startsWith('Propriété') && hideProp) || (label.startsWith('Règle') && hideRegle);
    if(!shouldHide) return;
    const box = badge.nextElementSibling;
    if(box && box.classList.contains('def-box')){
      box.innerHTML = writingLines;
      // Marge basse forcée explicitement (18px, la même que .def-box en CSS) -- garantit
      // l'espacement avec le paragraphe suivant, indépendamment d'un éventuel effet de perte
      // de marge dû au regroupement en bloc insécable (glueWithNextSibling, plus bas dans
      // cette même fonction d'export) qui enveloppe ensuite cet encadré dans un nouveau
      // conteneur. Signalé : "le paragraphe 2 est collé (ou chevauche)".
      box.style.marginBottom = '10px';
    }
  });
}
/* Mise en page compacte des figures pour le PDF -- signalé : « ça prend trop de place. Je ne peux
   pas distribuer autant de feuilles aux élèves » (9 pages pour 5 paragraphes de 6e G2). Les étapes
   d'une construction, jusqu'ici une par ligne (vignette + texte à côté), sont disposées en grille :
   4 vignettes par ligne (3 pour les scènes plus larges, comme le rapporteur), le texte de l'étape
   sous sa vignette. Les figures isolées sont limitées en hauteur. Ne concerne que le PDF : le cahier
   de l'élève garde son lecteur étape par étape. */
function compacterPourPdf(clone){
  clone.querySelectorAll('.cahier-film').forEach(film=>{
    const large = film.querySelector('img[style*="260px"]');
    film.style.cssText = `display:grid;grid-template-columns:repeat(${large ? 3 : 4},minmax(0,1fr));gap:10px 12px;`;
    Array.from(film.children).forEach(panneau=>{
      panneau.style.cssText = 'display:flex;flex-direction:column;align-items:stretch;gap:4px;';
      const vignette = panneau.firstElementChild, texte = panneau.lastElementChild;
      if(vignette && vignette !== texte){ vignette.style.width = '100%'; vignette.style.height = vignette.tagName === 'IMG' ? 'auto' : '70px'; }
      if(texte && vignette !== texte){ texte.style.fontSize = '9px'; texte.style.lineHeight = '1.3'; }
    });
  });
  // Hauteur limitée à 230 px en gardant les proportions : on fixe la LARGEUR (la largeur affichée
  // à l'écran, réduite si la hauteur dépasserait 230 px). Laisser width:auto donnait l'image à sa
  // taille réelle, deux fois plus grande que la figure (rastérisée ×2 pour la netteté) -- signalé :
  // « Le premier tableau reste très grossier. Il est énorme par rapport au second tableau ».
  clone.querySelectorAll('img[alt="Figure"]').forEach(img=>{
    const l = Number(img.dataset.largeur) || 0, r = Number(img.dataset.ratio) || 0;
    if(!l || !r) return;
    img.style.width = Math.round(Math.min(l, 230 / r)) + 'px'; img.style.maxWidth = '100%'; img.style.height = 'auto';
  });
}
async function exportCoursPDF(){
  if(typeof familleSansImpression==='function' && familleSansImpression()) return;
  const hint=document.getElementById('exportHint');
  // Feedback IMMÉDIAT au clic, avant tout travail lourd -- signalé : "on n'a pas d'indication
  // au départ de l'appui sur le bouton, on ne sait pas si ça travaille ou pas".
  hint.textContent='Préparation du PDF…';
  await new Promise(r=>setTimeout(r,0)); // laisse le navigateur peindre ce message avant de continuer
  if(typeof html2pdf==='undefined'){ hint.textContent="La bibliothèque PDF n'a pas pu se charger (pas de connexion internet ?), utilisez Ctrl/Cmd+P pour imprimer à la place."; return; }
  const content = getVisibleCoursContent();
  const title = document.getElementById('chap-title').textContent || 'cours';
  const demosAvancees = await advanceAllStepDemosToEndAsync(content);
  const clone = content.cloneNode(true);
  clone.querySelectorAll(':scope > .cp-hidden').forEach(el=>el.remove()); // blocs masqués par le professeur (cours personnalisé)
  filterCoursByParagraph(clone);
  blankOutSelectedBoxes(clone);
  clone.querySelectorAll('.add-to-cahier-btn').forEach(el=>el.remove());
  if(typeof ordNettoyer==='function') ordNettoyer(clone); // jeu « Remettre dans l'ordre » : texte en clair, sans bouton
  clone.querySelectorAll('.read-aloud-btn, .learn-btn, .lrn-bar, .zoom-btn, .ord-btn').forEach(el=>el.remove());
  clone.querySelectorAll('.oliv-b, .oliv-sh, .oliv-haut').forEach(el=>{ el.classList.remove('oliv-b','oliv-sh','oliv-haut',...[...el.classList].filter(c=>c.startsWith('oliv-'))); delete el.dataset.oliv; }); // vignettes d'Oliv'IA
  clone.querySelectorAll('.lrn-active').forEach(el=>el.classList.remove('lrn-active')); // mode apprentissage : texte en clair
  clone.querySelectorAll('.figure-toolbar').forEach(el=>el.remove());
  // Réduction spécifique au PDF : .katex a font-size:1.18em globalement sur le site (voir
  // styles.css), ce qui fait ressortir les formules -- fréquentes dans les exemples --
  // nettement plus grosses que le texte environnant une fois exportées.
  clone.querySelectorAll('.katex').forEach(el=>{ el.style.fontSize='1em'; });
  // Réduction spécifique au PDF : .we-expr (les exemples en police à chasse fixe, ex. "A =
  // 28 + 45 + 72 + 15") a font-size:1.05rem sur le site -- nettement plus large que le texte
  // environnant une fois exporté (signalé : "les exemples... sont écrits trop gros").
  clone.querySelectorAll('.we-expr').forEach(el=>{ el.style.fontSize='0.85em'; });
  clone.querySelectorAll('.interaction-hint').forEach(el=>el.remove());
  try{ await expandStepDemosInClone(clone); }
  finally{ resetAdvancedStepDemos(demosAvancees); } // la page affichée retrouve ses figures de départ
  compacterPourPdf(clone);
  // Empêche un saut de page de couper un paragraphe (ou une formule) en deux au milieu d'une
  // phrase -- protégé dans tous les cas, pas seulement s'il contient une formule (signalé :
  // "le dernier texte est coupé").
  clone.querySelectorAll('p, li, .step-column > div').forEach(el=>{
    el.style.pageBreakInside='avoid'; el.style.breakInside='avoid';
    if(el.querySelector('.tex')){
      el.style.lineHeight='2.2'; // laisse assez de place verticale au numérateur/dénominateur d'une fraction
    }
  });
  // PDF uniquement : les grilles "auto-fit" (ex. "Calculs astucieux", 2 colonnes sur le site)
  // n'ont pas la place de tenir sur la largeur réduite du wrapper PDF (700px, contre ~1032px
  // sur le site) et retombent sur 1 seule colonne -- forcé à 2 colonnes fixes pour l'export,
  // indépendamment de la largeur (signalé : "il n'y a plus deux calculs par ligne").
  clone.querySelectorAll('[style*="grid-template-columns"]').forEach(el=>{
    if(el.getAttribute('style').includes('auto-fit')) el.style.gridTemplateColumns = 'repeat(2, 1fr)';
    // Marquer chaque case (def-box) insécable ne suffit pas : si le saut de page tombe QUAND
    // MÊME à l'intérieur de la grille (CSS Grid, positionnement en 2D), html2pdf ne sait pas
    // repousser correctement une seule case sans casser l'alignement des autres -- constaté :
    // la case A tranchée en deux, sa suite réapparaissant décalée, désolidarisée de B/C/D.
    // La grille entière est donc protégée comme un seul bloc insécable (petite, tient sans
    // problème sur une page).
    el.style.pageBreakInside='avoid'; el.style.breakInside='avoid';
  });
  // Un encadré (définition/propriété/règle/exemple) coupé au milieu par un saut de page est
  // illisible -- protégé dans tous les cas, pas seulement s'il contient une formule (signalé :
  // "du contenu peut être coupé : c'est moche").
  clone.querySelectorAll('.def-box').forEach(el=>{
    el.style.pageBreakInside='avoid'; el.style.breakInside='avoid';
  });
  // Même protection pour les encadrés "calcul posé" (multiplication posée, division posée...),
  // qui suivent tous la même convention de mise en page : une carte centrée dans un conteneur
  // display:flex;justify-content:center, en dehors de toute .def-box.
  clone.querySelectorAll('div[style*="justify-content:center"]').forEach(wrap=>{
    Array.from(wrap.children).forEach(child=>{
      child.style.pageBreakInside='avoid'; child.style.breakInside='avoid';
    });
  });
  // Empêche un saut de page de séparer un titre (ou un badge Règle/Définition) du contenu qui le suit juste après :
  // html2pdf ne "colle" pas fiablement deux éléments voisins avec page-break-before/after, donc on les regroupe
  // physiquement dans un même conteneur, qui lui est traité comme un bloc insécable.
  function glueWithNextSibling(el){
    if(!el || !el.parentNode) return; // déjà déplacé par un regroupement précédent
    if(el.parentNode.classList && el.parentNode.classList.contains('pdf-glue-group')) return;
    const next = el.nextElementSibling;
    if(!next) return;
    const groupDiv = document.createElement('div');
    groupDiv.className = 'pdf-glue-group';
    groupDiv.style.pageBreakInside='avoid'; groupDiv.style.breakInside='avoid';
    el.parentNode.insertBefore(groupDiv, el);
    groupDiv.appendChild(el);
    groupDiv.appendChild(next);
  }
  // Ordre inverse du document : un badge doit d'abord se lier à sa def-box juste après ; ensuite seulement
  // le titre qui précède peut se lier à ce groupe déjà formé (sinon le titre "volerait" le badge en premier,
  // laissant sa def-box orpheline).
  Array.from(clone.querySelectorAll('.lesson-header, .sub-header, .example-title, .def-badge, .prop-badge')).reverse().forEach(glueWithNextSibling);
  // Empêche une figure -- animée à étapes ou simple image -- d'être coupée entre deux pages.
  clone.querySelectorAll('.figure-wrap').forEach(el=>{
    el.style.pageBreakInside='avoid'; el.style.breakInside='avoid';
  });
  // Important : html2canvas rend une page blanche si l'élément capturé est en position fixed/absolute
  // (bug connu). On le garde donc dans le flux normal, juste masqué visuellement par un parent
  // de hauteur nulle et overflow:hidden.
  const clip = document.createElement('div');
  clip.style.cssText='height:0;overflow:hidden;';
  const wrapper = document.createElement('div');
  // Taille d'écriture réduite (14px -> 12px, cascade sur tout le contenu) -- signalé : "la
  // génération PDF donne une structure trop grosse, on peut réduire la taille d'écriture
  // globale". html2canvas/html2pdf ignore le CSS d'impression du site (@media print), donc
  // toute mise en forme spécifique au PDF doit être faite ici, directement sur ce wrapper.
  // Largeur = la largeur utile de la page (A4 moins 2 × 10 mm de marge = 190 mm ≈ 718 px), celle du conteneur
  // dans lequel html2pdf recopie le cours : avec 700 px + 2 × 20 px de marge intérieure, le cours débordait.
  wrapper.style.cssText='width:718px;box-sizing:border-box;background:#fff;padding:20px;font-family:Inter,sans-serif;color:#1C1B2E;font-size:12px;line-height:1.5;';
  // "Chapitre N" (petit) + "CODE - TITRE" en majuscules (grand titre), comme pour
  // l'impression native (signalé : "ni chapitre... ni pagination", puis "écrire en gros N1 -
  // NOMBRES ENTIERS comme titre et supprimer N1 Nombres entiers en dessous de Chapitre 1").
  const chapNumEl = document.getElementById('printChapHeader');
  const bigTitleEl = document.getElementById('printChapBigTitle');
  const headerHtml = chapNumEl && chapNumEl.innerHTML
    ? `<div style="font-family:'Space Grotesk',sans-serif;font-size:10px;color:#666;margin-bottom:6px;line-height:1.4;">${chapNumEl.innerHTML}</div>`
    : '';
  const bigTitle = (bigTitleEl && bigTitleEl.textContent) || title;
  wrapper.innerHTML = headerHtml + `<h1 style="font-family:'Space Grotesk',sans-serif;font-size:20px;">${escapeHtml(bigTitle)}</h1>` + clone.innerHTML;
  clip.appendChild(wrapper);
  document.body.appendChild(clip);
  // Le thème de couleur (bleu en 5e, orange en 6e) est défini par des règles CSS SCOPÉES à
  // #view-chapitre.lvl-5e / .lvl-6e (ex. .lesson-header) -- le wrapper, détaché de ce
  // conteneur, ne matchait JAMAIS ces règles et retombait silencieusement sur les couleurs
  // par défaut (orange, celles de 6e). Signalé : "le fond des paragraphes doit être en bleu
  // car c'est notre thème en classe de 5e. Mais là il est généré en orange." Fix : porte
  // temporairement le MÊME id + la MÊME classe de niveau que le vrai conteneur, juste le
  // temps de la résolution des couleurs, pour que les mêmes règles scopées s'appliquent bien.
  const realChapView = document.getElementById('view-chapitre');
  const wrapperHadId = wrapper.id;
  wrapper.id = 'view-chapitre';
  if(realChapView){
    // Copie UNIQUEMENT la classe de niveau (lvl-5e/lvl-6e) -- copier toute la className
    // ramenait aussi la classe "view", porteuse d'une animation d'apparition en fondu
    // (opacity:0 -> 1 sur 0,35s), capturée en pleine animation par html2canvas et donnant un
    // rendu "voilé" (signalé : "ça paraît tout pâle, comme voilé").
    wrapper.className = ['lvl-cm', 'lvl-cm2', 'lvl-6e', 'lvl-5e', 'lvl-4e', 'lvl-3e'].filter(c => realChapView.classList.contains(c)).join(' ');
  }
  // Toutes les lectures d'abord, puis toutes les écritures : alterner les deux forçait le navigateur à
  // recalculer les styles à chaque élément.
  Array.from(wrapper.querySelectorAll('*')).map(el=>{
    const cs = window.getComputedStyle(el);
    return [el, cs.color, cs.backgroundColor, cs.borderTopColor, cs.borderRightColor, cs.borderBottomColor, cs.borderLeftColor];
  }).forEach(([el, c, bg, bt, br, bb, bl])=>{
    el.style.setProperty('color', c, 'important');
    el.style.setProperty('background-color', bg, 'important');
    el.style.setProperty('border-top-color', bt, 'important');
    el.style.setProperty('border-right-color', br, 'important');
    el.style.setProperty('border-bottom-color', bb, 'important');
    el.style.setProperty('border-left-color', bl, 'important');
  });
  wrapper.id = wrapperHadId; // retiré aussitôt -- évite tout id dupliqué durable dans le document
  // Attend que TOUTES les polices personnalisées (Space Grotesk, JetBrains Mono, Inter) soient
  // réellement chargées et appliquées avant de mesurer quoi que ce soit -- sans ça,
  // wrapper.scrollHeight peut être mesuré avec des polices de repli (tailles différentes),
  // qui se substituent ensuite en cours de capture par html2canvas, causant un calcul de
  // pagination incohérent d'une fois sur l'autre selon la vitesse de connexion. Signalé :
  // "ce n'est pas stable" -- symptôme caractéristique d'une dépendance au timing réseau.
  if(document.fonts && document.fonts.ready) await document.fonts.ready;
  hint.textContent='Génération du PDF en cours…';
  // html2canvas photographie la page EN TENANT COMPTE DU DÉFILEMENT : si l'on a fait défiler le
  // chapitre avant de cliquer, tout le contenu est décalé d'autant (pages blanches au début,
  // blocs coupés, sauts de page au mauvais endroit). Signalé : « C'est instable ! » (deux
  // exports successifs, deux résultats différents selon l'endroit où l'on se trouvait).
  // On remonte donc en haut le temps de la capture, puis on revient à la position de lecture.
  const defilX = window.scrollX, defilY = window.scrollY;
  window.scrollTo(0, 0);
  const revenir = ()=>window.scrollTo(defilX, defilY);
  // html2canvas recopie TOUTE la page avant de photographier le cours (plusieurs dizaines de milliers
  // d'éléments : vues masquées, autres chapitres…) -- signalé : « L'export en PDF des cours est toujours
  // très long et on a ce message [la page ne répond pas] qui s'affiche plusieurs fois de suite ». Mesuré :
  // 24 s de blocage pour un cours de 370 éléments, 0,8 s en ne recopiant que le cours (la copie que
  // html2pdf place dans son calque .html2pdf__overlay) et les styles de la page (head).
  let calquePdf = null;
  const horsExport = el=>{
    if(el.tagName==='HEAD' || (el.closest && el.closest('head'))) return false;
    if(!calquePdf || !calquePdf.isConnected) calquePdf = document.querySelector('.html2pdf__overlay');
    return !(calquePdf && (el===calquePdf || calquePdf.contains(el) || el.contains(calquePdf)));
  };
  html2pdf().set({margin:10, filename:title.replace(/[^\w-]+/g,'_')+'.pdf', html2canvas:{scale:1.5, useCORS:true, foreignObjectRendering:false, scrollX:0, scrollY:0, windowHeight:wrapper.scrollHeight, ignoreElements:horsExport}, jsPDF:{unit:'mm',format:'a4'}, pagebreak:{mode:['css']}})
    .from(wrapper).toCanvas().then(function(){
      // html2pdf place ses sauts de page tous les 1046 px (hauteur utile arrondie à l'inférieur), mais découpait
      // ensuite l'image tous les 1047,3 px (calcul fait sur la largeur arrondie de l'image) -- signalé : « il
      // reste encore parfois des défauts de découpage » : 1,3 px de décalage par page, qui s'accumulait jusqu'à
      // faire apparaître le haut du badge suivant en bas de page. La découpe suit donc exactement la même
      // hauteur que les sauts de page (la page imprimée fait 276,5 mm au lieu de 277, invisible).
      const ps = this.prop.pageSize, largeur = this.prop.canvas.width, hauteur = Math.round(ps.inner.px.height*1.5);
      ps.inner.ratio = (hauteur + 0.5)/largeur;
      ps.inner.height = ps.inner.width*hauteur/largeur;
    }).toPdf().get('pdf').then(pdf=>{
      // Pagination "page / total" -- html2pdf ne le fait pas nativement, on la tamponne
      // nous-mêmes via l'API jsPDF sous-jacente, une fois toutes les pages générées.
      const total = pdf.internal.getNumberOfPages();
      for(let i=1;i<=total;i++){
        pdf.setPage(i);
        pdf.setFontSize(9);
        pdf.setTextColor(120);
        pdf.text(`${i} / ${total}`, pdf.internal.pageSize.getWidth()/2, pdf.internal.pageSize.getHeight()-6, {align:'center'});
      }
    }).save()
    .then(()=>{ clip.remove(); revenir(); hint.textContent='PDF téléchargé ✓'; setTimeout(()=>hint.textContent='',4000); })
    .catch(()=>{ clip.remove(); revenir(); hint.textContent="Échec de la génération dans ce navigateur, essayez Ctrl/Cmd+P pour imprimer à la place."; });
}


/* ======================= OUTIL PROF : rendu maths ======================= */
function katexSpan(expr){
  try{ return katex.renderToString(expr, {throwOnError:false}); }
  catch(e){ return expr; }
}
/* Police italique arrondie pour les variables (x, y, n...), cohérente avec l'aspect du chapitre
   Calcul littéral, sans dépendre du chargement de KaTeX (contrairement à katexSpan, qui peut
   dupliquer visuellement le texte si sa feuille de style ne charge pas -- overkill pour une
   simple lettre isolée). */
/* Rend en LaTeX (via KaTeX) tout élément statique du cours marqué class="tex",
   son contenu texte étant la source LaTeX à afficher (ex. \frac{3}{4}).
   Réutilisable pour n'importe quel chapitre. */
function renderStaticMath(container){
  if(!container) return;
  container.querySelectorAll('.tex').forEach(el=>{
    if(el.dataset.rendered) return;
    el.dataset.texSource = el.textContent; // conserve la source brute (lecture vocale, voir toggleReadAloud)
    el.innerHTML = katexSpan(el.textContent);
    el.dataset.rendered = '1';
  });
}
function cleanExpr(s){
  s = s.replace(/\*/g, '\\times ');
  // Convertit aussi une fraction simple à l'intérieur de l'expression -- nombre/lettre, ou un
  // appel de fonction d'un côté ou des deux (ex. le "1/x" de lim(x,0,1/x), ou "f(x)/x") -- sinon
  // elle resterait en texte brut avec un simple "/" au lieu d'une vraie fraction, une fois
  // passée à KaTeX (qui ne la réinterprète pas après coup).
  const terme = '[a-zA-Z0-9]+(?:\\([^()]*\\))?';
  s = s.replace(new RegExp(`(${terme})/(${terme})`, 'g'), (m,a,b)=>`\\dfrac{${a}}{${b}}`);
  return s;
}
function escapeHtml(s){ return (s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
/* Nom affiché "Nom Prénom" -- signalé : "dans supervision, résultats, administration, il faut
   afficher Nom et Prénom" (depuis la séparation des deux champs, build 605). Retombe sur l'un
   des deux seul s'il manque, puis sur null (l'appelant décide alors du repli, ex. l'e-mail). */
function profileDisplayName(p){
  if(!p) return null;
  const nom = (p.nom||'').trim();
  const prenom = (p.prenom||'').trim();
  return [nom, prenom].filter(Boolean).join(' ') || null;
}
/* Modales "propres" (alerte, confirmation, saisie), pour remplacer les alert()/confirm()/
   prompt() natifs du navigateur -- ceux-ci ont un rendu très daté et ne s'intègrent pas au
   reste du site. Chacune renvoie une Promise, à utiliser avec await. */
function niceModal({message, showInput, inputValue, buttons}){
  return new Promise(resolve=>{
    const overlay = document.getElementById('niceModalOverlay');
    // Voir le commentaire équivalent dans tbOpenLetterPicker : en plein écran, seuls les
    // descendants de l'élément mis en plein écran restent visibles par-dessus son
    // arrière-plan -- on relocalise donc la modale (position:fixed, donc son affichage ne
    // dépend pas de son parent réel dans le DOM) dans cet élément le temps de l'afficher.
    (document.fullscreenElement || document.body).appendChild(overlay);
    document.getElementById('niceModalMessage').textContent = message;
    const input = document.getElementById('niceModalInput');
    input.style.display = showInput ? 'block' : 'none';
    input.value = inputValue||'';
    const btnBox = document.getElementById('niceModalButtons');
    btnBox.innerHTML = '';
    const close = (val)=>{ overlay.style.display='none'; resolve(val); };
    buttons.forEach(b=>{
      const btn = document.createElement('button');
      btn.className = 'btn'+(b.secondary?' secondary':'');
      btn.textContent = b.label;
      btn.onclick = ()=> close(showInput && b.value===true ? input.value : b.value);
      btnBox.appendChild(btn);
    });
    overlay.style.display = 'flex';
    if(showInput){ input.focus(); input.select(); input.onkeydown = (e)=>{ if(e.key==='Enter') close(input.value); }; }
  });
}
function niceAlert(message){
  return niceModal({message, buttons:[{label:'OK', value:true}]});
}
function niceConfirm(message){
  return niceModal({message, buttons:[{label:'Annuler', value:false, secondary:true},{label:'Confirmer', value:true}]});
}
function nicePrompt(message, defaultValue){
  return niceModal({message, showInput:true, inputValue:defaultValue, buttons:[{label:'Annuler', value:null, secondary:true},{label:'OK', value:true}]});
}
function renderMathText(raw){
  let text = raw.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
  // Chaque bloc déjà rendu par KaTeX (fraction, racine, exposant, $...$) est mis de côté
  // derrière un jeton opaque le temps du reste du traitement, pour qu'aucune règle suivante
  // (multiplication, variables) ne vienne s'insérer À L'INTÉRIEUR du LaTeX déjà construit et
  // le casser (c'était le bug de "(5x+3x)/2" : la règle des variables repérait le x à
  // l'intérieur de \frac{5x+3x}{2} et y insérait une balise, rendant le LaTeX illisible pour KaTeX).
  const protectedBlocks = [];
  function protect(html){ protectedBlocks.push(html); return `\u0000${protectedBlocks.length-1}\u0000`; }

  // 0) mini mise en forme : **gras** et {{couleur|texte}}
  // [[ ... ]] : encadré « À apprendre » (comme une définition du cours) -- les élèves y retrouvent, dans le
  // cahier et en séance, l'écoute, le mode apprentissage et le jeu « Remettre dans l'ordre ».
  text = text.replace(/\[\[\s*([\s\S]+?)\s*\]\]/g, '\u0001$1\u0002');
  const COLOR_MAP={rouge:'#D93025',bleu:'#1F3A5C',vert:'#2C5A2E',orange:'#E35D3A'};
  text = text.replace(/\*\*([^*]+)\*\*/g, (m,inner)=>`<b>${inner}</b>`);
  text = text.replace(/__([^_]+)__/g, (m,inner)=>`<u>${inner}</u>`);
  text = text.replace(/\{\{(rouge|bleu|vert|orange)\|([^}]+)\}\}/g, (m,c,inner)=>`<span style="color:${COLOR_MAP[c]}">${inner}</span>`);

  // 1) explicit LaTeX between $...$
  // (les signes < et > ont été échappés plus haut pour le HTML : KaTeX doit les recevoir tels quels,
  // sinon « $\frac{1}{3} > \frac{1}{2}$ » s'affichait en rouge -- KaTeX échappe lui-même son rendu)
  text = text.replace(/\$([^$]+)\$/g, (m,expr)=>{
    const brut = expr.replace(/&lt;/g,'<').replace(/&gt;/g,'>'), h = katexSpan(brut);
    return protect(h === brut ? expr : h); // KaTeX indisponible : on garde le texte échappé
  });
  // 2) sqrt(...) -- processed before fractions so "sqrt(2)/3" isn't mistaken for a fraction
  text = text.replace(/sqrt\(([^()]+)\)/g, (m,inner)=>protect(katexSpan(`\\sqrt{${cleanExpr(inner)}}`)));
  // 3) fractions with a parenthesised expression on one or both sides: (2*2)/(3*2), (2+1)/4, 3/(1+2)
  text = text.replace(/\(([^()]+)\)\/\(([^()]+)\)/g, (m,a,b)=>protect(katexSpan(`\\dfrac{${cleanExpr(a)}}{${cleanExpr(b)}}`)));
  text = text.replace(/\(([^()]+)\)\/(\d+(?:[.,]\d+)?)/g, (m,a,b)=>protect(katexSpan(`\\dfrac{${cleanExpr(a)}}{${b.replace(',','.')}}`)));
  text = text.replace(/(\d+(?:[.,]\d+)?)\/\(([^()]+)\)/g, (m,a,b)=>protect(katexSpan(`\\dfrac{${a.replace(',','.')}}{${cleanExpr(b)}}`)));
  // 4) plain fractions a/b (integers or decimals) -- traité avant la règle avec appel de
  // fonction ci-dessous, pour qu'un nombre décimal (ex. 3.5/4) soit capturé en entier d'abord,
  // plutôt que de laisser cette dernière n'en voler qu'un morceau (ex. juste "5/4").
  text = text.replace(/(\d+(?:[.,]\d+)?)\/(\d+(?:[.,]\d+)?)/g, (m,a,b)=>protect(katexSpan(`\\dfrac{${a.replace(',','.')}}{${b.replace(',','.')}}`)));
  // 4bis) fractions avec un appel de fonction d'un côté ou des deux (ex. f(x+3)/x, x/g(x)) --
  // même logique que cleanExpr, appliquée ici au texte libre (pas seulement à l'intérieur de sqrt()).
  {
    const terme = '[a-zA-Z][a-zA-Z0-9]*\\([^()]*\\)|[a-zA-Z0-9]+';
    text = text.replace(new RegExp(`(${terme})\\/(${terme})`, 'g'), (m,a,b)=>protect(katexSpan(`\\dfrac{${a}}{${b}}`)));
  }
  // 5) exponents  base^exp  (exp = digits or {...})
  text = text.replace(/([A-Za-z0-9\)\]])\^(-?\d+(?:[.,]\d+)?|\{[^}]+\})/g, (m,base,exp)=>{
    const e = exp.startsWith('{') ? exp.slice(1,-1) : exp;
    return protect(katexSpan(`${base}^{${e}}`));
  });
  // 6) astérisque isolé restant (hors fractions/racines/exposants déjà traités ci-dessus,
  //    et hors ** de gras déjà consommé) : c'est une multiplication, simple signe ×.
  text = text.replace(/\*/g, '×');
  // 7) variable (x, y, z, n, k, t...) ou lettre majuscule isolée (A, B, E... utilisée pour nommer
  //    une expression ou un point, comme partout ailleurs sur le site), isolée ou précédée d'un
  //    coefficient collé (5x, 12y, 2,5x... = multiplication implicite, notation mathématique
  //    standard). Rendu par le MÊME moteur KaTeX que les fractions (protégé de la même façon),
  //    pour garantir exactement la même police, taille et graisse partout -- mélanger KaTeX pour
  //    les fractions et une simple police italique pour le reste donnait des tailles/styles
  //    incohérents d'une ligne à l'autre.
  // Limites de mot « Unicode » (et non \b, qui ignore les lettres accentuées) : sans ça, le L de
  // « Léa » ou le R de « Répondez » passait pour une lettre isolée et s'affichait en italique.
  text = text.replace(/(?<![\p{L}\p{N}_])(\d+(?:[.,]\d+)?)?([xyznktA-Z])(?![\p{L}\p{N}_])/gu, (m,digits,letter,offset,str)=>{
    // Exclut deux tournures françaises courantes, non des variables mathématiques :
    // - le "t" euphonique entouré de tirets ("coupe-t-il", "y a-t-il", "mange-t-elle"...)
    // - le "y" du pronom dans "il y" ("il y a", "il y en a"...)
    if(!digits){
      if(letter==='t' && str[offset-1]==='-' && str[offset+1]==='-') return m;
      if(letter==='y' && str.slice(offset+1, offset+3)===' a') return m;
    }
    const expr = digits ? `${digits.replace(',','.')}${letter}` : letter;
    return protect(katexSpan(expr));
  });
  text = text.replace(/\n/g,'<br>');
  // Préserve les tabulations et espaces multiples intentionnels (indentation, alignement) --
  // sans cette conversion, le HTML les collabore en un seul espace. Un espace isolé entre deux
  // mots reste un espace normal (le texte continue de faire un retour à la ligne naturel) ;
  // seules les TABULATIONS et les RÉPÉTITIONS de 2 espaces ou plus (clairement intentionnelles)
  // sont converties en espaces insécables pour être visuellement conservées.
  text = text.replace(/\t/g, '&nbsp;&nbsp;&nbsp;&nbsp;');
  text = text.replace(/ {2,}/g, (m)=>'&nbsp;'.repeat(m.length));
  // on restitue les blocs protégés
  text = text.replace(/\u0000(\d+)\u0000/g, (m,i)=>protectedBlocks[+i]);
  return text.replace(/\u0001/g, '<div class="def-box lecon-box">').replace(/\u0002(<br>)?/g, '</div>');
}
/* Mise en page de l'outil de correction : mêmes lignes/colonnes glissables-déposables que dans
   le module évaluation (contexte 'global'), avec un bouton Valider qui cache la barre d'outils
   et les pointillés d'édition une fois la correction terminée -- pour un écran plus lisible en
   cours, sans perdre la possibilité de revenir éditer. */
let corRows = [1];
let corValidated = false;
/* Comme dans le module Évaluation (qui n'a pas de grand rectangle de saisie sous le titre --
   juste les blocs), la zone de texte libre peut être retirée pour ne garder que les blocs
   insérés. Réversible via le bouton "+ Zone de texte libre" qui réapparaît à sa place. */
function corRemoveTextarea(){
  document.getElementById('correctionInputWrap').style.display = 'none';
  document.getElementById('btnCorAddTextarea').style.display = 'inline-flex';
  renderCorrectionPreview();
}
function corAddTextarea(){
  document.getElementById('correctionInputWrap').style.display = 'block';
  document.getElementById('btnCorAddTextarea').style.display = 'none';
  renderCorrectionPreview();
}
function corSetRowCols(rowIdx, n){
  corRows[rowIdx] = Math.max(1, Math.min(6, parseInt(n)||1));
  renderCorrectionPreview();
}
function corAddRow(){
  corRows.push(1);
  renderCorrectionPreview();
}
function corRemoveRow(rowIdx){
  if(corRows.length<=1) return;
  // Les blocs de la ligne retirée rejoignent la ligne précédente, pour ne pas les perdre.
  (blocksStores['global']||[]).forEach(b=>{
    const r = b.row||0;
    if(r===rowIdx) b.row = Math.max(0, rowIdx-1);
    else if(r>rowIdx) b.row = r-1;
  });
  corRows.splice(rowIdx,1);
  renderCorrectionPreview();
}
function corToggleValidated(){
  corValidated = !corValidated;
  const btn = document.getElementById('btnCorValidate');
  btn.innerHTML = corValidated ? '<span class=gicon>edit</span> Éditer' : '✓ Valider';
  btn.style.background = corValidated ? 'rgba(31,58,92,.08)' : 'rgba(35,140,90,.12)';
  btn.style.color = corValidated ? '#1F3A5C' : '#1F7A4D';
  document.getElementById('corLayoutRow').style.display = corValidated ? 'none' : 'flex';
  document.getElementById('corToolsRow').style.display = corValidated ? 'none' : 'flex';
  // le bouton Valider/Éditer lui-même doit rester visible même caché des deux rangées ci-dessus
  if(corValidated){
    document.getElementById('correctionPreview').insertAdjacentElement('afterend', btn);
  } else {
    document.getElementById('corLayoutRow').appendChild(btn);
  }
  renderCorrectionPreview();
}
function corRenderRowsControls(){
  document.getElementById('corRowsControls').innerHTML = corRows.map((n,i)=>`
    <span class="hint" style="margin:0 4px 0 8px;">L${i+1} : <input type="number" value="${n}" min="1" max="6" onchange="corSetRowCols(${i},this.value)" style="width:40px;"></span>
    ${corRows.length>1 ? `<button type="button" onclick="corRemoveRow(${i})" style="border:none;background:rgba(217,48,37,.1);color:#D93025;border-radius:5px;padding:2px 6px;cursor:pointer;font-size:.75rem;"><span class=gicon>close</span></button>` : ''}
  `).join('');
}
function renderCorrectionPreview(){
  const textareaVisible = document.getElementById('correctionInputWrap').style.display !== 'none';
  const raw = textareaVisible ? document.getElementById('correctionInput').value : '';
  const rendered = raw.trim() ? renderMathText(raw) : '';
  const previewHtml = rendered || (textareaVisible ? '<span class="hint">L\'aperçu de la correction (mise en forme automatique) apparaît ici au fur et à mesure de la saisie.</span>' : '');
  const cleanBlocks = blocksRowsHTML('global', corRows, false, corCellBorders);
  document.getElementById('correctionPreview').innerHTML = corHeaderHTML() + previewHtml + (corValidated ? cleanBlocks : blocksRowsHTML('global', corRows, true, corCellBorders));
  updateProjectionWindow(rendered + cleanBlocks);
  corRenderRowsControls();
  attachResizeObservers();
}
/* En-tête (titre de l'exercice, n° d'exercice, date) : rempli par le professeur dans le
   formulaire, il doit être visible des élèves au même titre que la correction elle-même. */
function corHeaderHTML(){
  const titre = (document.getElementById('corTitre')?.value || '').trim();
  const exo = (document.getElementById('corExoNum')?.value || '').trim();
  const date = document.getElementById('corDate')?.value || '';
  if(!titre && !exo && !date) return '';
  const dateFmt = date ? new Date(date+'T00:00:00').toLocaleDateString('fr-FR', {weekday:'long', day:'numeric', month:'long'}) : '';
  const parts = [exo, titre].filter(Boolean).join(' · ');
  return `<div class="cor-header">
    ${dateFmt ? `<div class="cor-header-date">${escapeHtml(dateFmt)}</div>` : ''}
    ${parts ? `<div class="cor-header-title">${escapeHtml(parts)}</div>` : ''}
  </div>`;
}
/* Fenêtre de projection : une vraie fenêtre de navigateur séparée (pas juste un agrandissement
   dans la page), à faire glisser sur un second écran / vidéoprojecteur, et librement
   redimensionnable -- pour ne projeter aux élèves que la correction, jamais l'outil de saisie. */
let ceProjWin = null;
function updateProjectionWindow(html){
  if(!ceProjWin || ceProjWin.closed) return;
  const headEl = ceProjWin.document.getElementById('projHeader');
  if(headEl) headEl.innerHTML = corHeaderHTML();
  const el = ceProjWin.document.getElementById('projContent');
  if(el) el.innerHTML = html;
}
async function toggleProjection(){
  const btn = document.getElementById('btnProjection');
  if(ceProjWin && !ceProjWin.closed){
    ceProjWin.close();
    ceProjWin = null;
    btn.innerHTML = '<span class=gicon>desktop_windows</span> Ouvrir la fenêtre de projection';
    return;
  }
  ceProjWin = window.open('', 'atelierMathsProjection', 'width=1100,height=720,resizable=yes');
  if(!ceProjWin){ await niceAlert("La fenêtre n'a pas pu s'ouvrir : autorisez les pop-up pour ce site."); return; }
  ceProjWin.document.open();
  ceProjWin.document.write(`<!DOCTYPE html><html><head><meta charset="utf-8">
    <title>Correction -- projection</title>
    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/KaTeX/0.16.9/katex.min.css">
    <link rel="stylesheet" href="${document.querySelector('link[href*="styles.css"]').href}">
    <style>
      html,body{margin:0;padding:0;background:#FFFFFF;height:100%;}
      body{padding:4vw 5vw;box-sizing:border-box;}
      #projHeader{font-family:'Space Grotesk',Arial,sans-serif;margin-bottom:1.4vw;}
      #projHeader .cor-header-title{font-weight:700;font-size:clamp(1.1rem, 2.2vw, 1.8rem);color:#0C5BA0;}
      #projHeader .cor-header-date{font-size:clamp(.85rem, 1.4vw, 1.1rem);color:#5B6472;margin-top:.2em;text-transform:capitalize;}
      #projContent{
        font-family:'Space Grotesk',Arial,sans-serif;color:#20242E;
        font-size:clamp(1.2rem, 2.8vw, 2.2rem);line-height:1.7;font-weight:400;
        max-width:100%;text-align:left;
      }
      #projContent .hint{color:#9aa0a8;font-weight:400;}
      #projContent b{color:#0C5BA0;}
      .katex{font-size:1.18em;}
    </style>
  </head><body><div id="projHeader"></div><div id="projContent"></div></body></html>`);
  ceProjWin.document.close();
  renderCorrectionPreview();
  btn.innerHTML = '<span class=gicon>close</span> Fermer la fenêtre de projection';
  const watcher = setInterval(()=>{
    if(!ceProjWin || ceProjWin.closed){
      clearInterval(watcher);
      ceProjWin = null;
      btn.innerHTML = '<span class=gicon>desktop_windows</span> Ouvrir la fenêtre de projection';
    }
  }, 800);
}
function wrapSelection(before, after){
  const ta = document.getElementById('correctionInput');
  const start = ta.selectionStart, end = ta.selectionEnd;
  const val = ta.value;
  const selected = val.slice(start,end) || 'texte';
  ta.value = val.slice(0,start) + before + selected + after + val.slice(end);
  ta.focus();
  ta.selectionStart = start + before.length;
  ta.selectionEnd = start + before.length + selected.length;
  renderCorrectionPreview();
}
function applyBold(){ wrapSelection('**','**'); }
function applyLecon(){ wrapSelection('[[',']]'); }
function applyColor(color){ wrapSelection('{{'+color+'|','}}'); }

/* ---- mini outil de figure géométrique ---- */
let figState = {points:[], shapes:[], mode:'point', selected:[], refShape:null, nextLabel:0};
/* Contenu joint (figures, tableaux, divisions, axes...) : un TABLEAU de blocs indépendants par
   CONTEXTE plutôt qu'une seule liste globale, pour que les mêmes 7 outils (figure, tableau,
   division, division décimale, axe, repère, disque, rectangle) servent aussi bien à l'outil de
   correction ('global') qu'à chaque exercice d'une évaluation ('ex-<id>'). editFn (facultatif)
   est le nom d'une fonction qui rouvre l'outil correspondant, pré-rempli avec les données
   d'origine (data), pour "modifier" un bloc : on supprime alors l'ancien bloc et on rouvre le
   panneau, prêt à être réinséré une fois ajusté. */
let blocksStores = { global: [] };
let pendingBlockNextId = 1;
let currentBlocksContext = 'global'; // contexte ciblé par le PROCHAIN outil qu'on ouvre
function setToolContext(ctx){ currentBlocksContext = ctx; if(!blocksStores[ctx]) blocksStores[ctx]=[]; }
function renderBlocksContext(ctx){
  if(ctx==='global'){ if(typeof renderCorrectionPreview==='function') renderCorrectionPreview(); }
  else if(typeof renderEvalExercicesList==='function') renderEvalExercicesList();
}
/* Zone de destination sélectionnée par le prof AVANT d'ouvrir un outil (cliquer sur une
   zone la met en surbrillance) : le prochain bloc ajouté (figure, tableau, texte...) y
   atterrit directement, au lieu de toujours tomber dans la colonne 0 de la dernière ligne
   puis devoir être déplacé à la main. Remise à zéro à chaque changement d'exercice/contexte
   (setToolContext), pour ne jamais viser par erreur la zone d'un autre exercice. */
let blockTargetCtx = null, blockTargetRow = 0, blockTargetCol = 0;
function selectBlockTarget(ctx, row, col){
  blockTargetCtx = ctx; blockTargetRow = row; blockTargetCol = col;
  renderBlocksContext(ctx);
}
let editingBlock = null; // {id, ctx} du bloc actuellement en cours d'édition, s'il y en a un
function addPendingBlock(type, html, data, editFn){
  const ctx = currentBlocksContext;
  const ex = getExerciseByCtx(ctx);
  let row, col;
  if(editingBlock && editingBlock.ctx===ctx){
    // Remplace le bloc édité : retire l'ANCIEN seulement maintenant (à la réinsertion
    // effective, jamais avant), en gardant sa position d'origine.
    const oldBlock = (blocksStores[ctx]||[]).find(b=>b.id===editingBlock.id);
    row = oldBlock ? oldBlock.row : ((ex && ex.rows && ex.rows.length) ? ex.rows.length-1 : 0);
    col = oldBlock ? oldBlock.col : 0;
    blocksStores[ctx] = (blocksStores[ctx]||[]).filter(b=>b.id!==editingBlock.id);
    editingBlock = null;
  } else {
    const lastRow = (ex && ex.rows && ex.rows.length) ? ex.rows.length-1 : 0;
    const useTarget = blockTargetCtx===ctx;
    row = useTarget ? blockTargetRow : lastRow;
    col = useTarget ? blockTargetCol : 0;
  }
  (blocksStores[ctx] || (blocksStores[ctx]=[])).push({id: pendingBlockNextId++, type, html, data, editFn, ctx, col, row});
  renderBlocksContext(ctx);
}
/* Annule une édition en cours SANS toucher au bloc d'origine (qui n'a jamais été retiré) --
   utilisée par le bouton "Annuler" (à la place de "Fermer sans insérer" quand on édite un
   bloc déjà existant). Signalé : "je propose qu'en mode édition, ce bouton se transforme en
   Annuler et que ça n'efface pas le contenu". */
function cancelBlockEdit(){ editingBlock = null; }
function removeBlock(id, ctx){
  ctx = ctx || currentBlocksContext;
  blocksStores[ctx] = (blocksStores[ctx]||[]).filter(b=>b.id!==id);
  renderBlocksContext(ctx);
}
function editBlock(id, ctx){
  ctx = ctx || currentBlocksContext;
  const arr = blocksStores[ctx]||[];
  const b = arr.find(x=>x.id===id);
  if(!b || !b.editFn) return;
  editingBlock = {id, ctx};
  currentBlocksContext = ctx;
  window[b.editFn](b.data);
}
/* withControls=true : version affichée au professeur, avec les boutons <span class=gicon>edit</span>/<span class=gicon>close</span> (jamais montrée
   aux élèves). withControls=false : version "propre", envoyée à la fenêtre de projection,
   enregistrée dans le cahier, ou imprimée dans la feuille d'évaluation. */
/* Retrouve l'exercice d'évaluation correspondant à un contexte de blocs ("ex-<id>"), pour
   pouvoir appliquer son réglage manuel de taille de disques. Renvoie null pour les autres
   contextes (ex. l'outil de correction, contexte "global", qui n'a pas cette notion). */
function getExerciseByCtx(ctx){
  const m = /^ex-(\d+)$/.exec(ctx||'');
  if(!m) return null;
  return evaluationExercises.find(e=>e.id===parseInt(m[1]))||null;
}
function singleBlockHTML(b, ctx, withControls, draggable){
  const sizeStyle = (b.width?`width:${b.width}px;`:'') + (b.height?`height:${b.height}px;`:'');
  // Les figures/diagrammes ont un gabarit fixe raisonnable par défaut (les étirer sur toute
  // la largeur de la page les déformerait). Le texte, en revanche, doit par défaut occuper
  // toute la largeur disponible de sa zone -- comme n'importe quel paragraphe -- sinon il se
  // retrouve coupé à 260px de large (un tiers de page environ) tant qu'on ne le redimensionne
  // pas manuellement avec la poignée.
  // Le type 'figure' (construction géométrique) a sa PROPRE largeur par défaut, calibrée
  // exactement sur l'échelle réelle de la page imprimée (680px = 180mm de zone imprimable A4,
  // voir evaluation.js) et sur la convention interne de l'outil (SCALE_PX_PER_CM=20, viewBox
  // 500 unités de large) : 500 x (37.778 px/cm réel / 20 unités/cm outil) ≈ 944px. Sans ce
  // calibrage précis, le type 'figure' serait tombé dans le générique 260px (comme les
  // petites figures ci-dessous), et un segment déclaré "5cm" se serait imprimé à environ
  // 1,38cm réels seulement -- pas du tout la longueur annoncée à l'élève.
  const defaultWidth = b.type==='axe' ? 500 : b.type==='repere' ? 340 : b.type==='graph' ? 420 : (b.type==='figure' || b.type==='figdyn') ? 944 : b.type==='texte' ? null : 260;
  let html = b.html;
  if(b.type==='disque'){
    // Réglage manuel (toujours prioritaire, fiable dans tous les contextes y compris la
    // fenêtre d'impression) : s'il est défini, on l'applique directement dans le HTML.
    const ex = getExerciseByCtx(ctx);
    if(ex && ex.diskSize) html = html.split('max-width:150px').join(`max-width:${ex.diskSize}px`);
  }
  if(b.type==='rectFrac'){
    const ex = getExerciseByCtx(ctx);
    if(ex && ex.rectSize) html = html.split('max-width:180px').join(`max-width:${ex.rectSize}px`);
  }
  if(!withControls){
    // Repli SPÉCIFIQUEMENT pour le type 'figure' (construction géométrique) : sans lui, un
    // bloc jamais redimensionné manuellement n'obtenait AUCUNE largeur du tout à
    // l'impression/dans le PDF -- le calibrage de defaultWidth (voir plus haut) n'aurait eu
    // aucun effet sur le résultat imprimé réel, seulement sur l'aperçu dans l'éditeur. Les
    // autres types de blocs gardent leur comportement d'impression inchangé (pas de risque
    // de régression sur ce qui fonctionne déjà).
    const printWidthStyle = sizeStyle || ((b.type==='figure' || b.type==='figdyn') ? `width:${defaultWidth}px;` : '');
    // divisionPosee (mode étape par étape) peut être bien plus haut qu'un bloc "figure"
    // typique -- overflow:hidden risquerait de couper les dernières étapes si le conteneur
    // se trouvait contraint en hauteur par ailleurs.
    const overflowStyle = b.type==='divisionPosee' ? '' : 'overflow:hidden;';
    return `<div class="nb-figure-row disk-sync-target" data-block-id="${b.id}" data-ctx="${ctx}" data-type="${b.type}"${(printWidthStyle||overflowStyle)?` style="${printWidthStyle}${overflowStyle}"`:''}>${html}</div>`;
  }
  // Poignée de glisser DÉDIÉE (plutôt que le bloc entier "draggable") : un texte contient du
  // contenu sélectionnable, et rendre tout le bloc "draggable" entrait en conflit avec la
  // sélection de texte à la souris (le navigateur hésite entre démarrer une sélection ou un
  // glisser-déposer). En isolant l'attribut draggable sur une petite poignée dédiée, le reste
  // du bloc reste utilisable normalement (sélection, édition), et glisser depuis la poignée
  // fonctionne de façon fiable.
  const dragHandle = draggable ? `<span draggable="true" ondragstart="evalDragStart(event,${b.id})" ondragend="evalDragEnd(event)" title="Glisser pour déplacer ce bloc" style="position:absolute;top:6px;left:6px;cursor:grab;font-size:1rem;color:var(--ink-soft);z-index:2;user-select:none;">⠿</span>` : '';
  const widthStyle = sizeStyle || (defaultWidth ? `width:${defaultWidth}px;` : 'width:100%;');
  return `<div class="nb-figure-row" style="position:relative;border:1px dashed rgba(28,43,57,.18);border-radius:8px;padding:10px 34px 10px ${draggable?'26px':'10px'};margin:8px 0;background:#fff;">
    ${dragHandle}
    <div style="position:absolute;top:6px;right:6px;display:flex;gap:4px;z-index:2;">
      ${b.editFn ? `<button type="button" onclick="editBlock(${b.id},'${ctx}')" title="Modifier ce bloc" style="border:none;background:rgba(31,58,92,.08);border-radius:6px;padding:3px 7px;cursor:pointer;font-size:.85rem;"><span class=gicon>edit</span></button>` : ''}
      <button type="button" onclick="removeBlock(${b.id},'${ctx}')" title="Supprimer ce bloc" style="border:none;background:rgba(217,48,37,.1);color:#D93025;border-radius:6px;padding:3px 7px;cursor:pointer;font-size:.85rem;"><span class=gicon>close</span></button>
    </div>
    <div class="resizable-block disk-sync-target" data-block-id="${b.id}" data-ctx="${ctx}" data-type="${b.type}" style="resize:both;overflow:hidden;display:block;max-width:100%;min-width:80px;min-height:50px;${widthStyle}">${html}</div>
  </div>`;
}
function pendingBlocksHTML(withControls, ctx){
  ctx = ctx || 'global';
  const arr = blocksStores[ctx]||[];
  if(!arr.length) return '';
  return arr.map(b=>singleBlockHTML(b, ctx, withControls, false)).join('');
}
/* Rendu en colonnes (glisser-déposer) : utilisé pour structurer un exercice d'évaluation en
   2 ou 3 colonnes (ex. une figure à gauche, l'énoncé à droite). nCols<=1 revient au rendu
   simple habituel. */
let evalDragBlockId = null;
function evalDragStart(e, id){
  evalDragBlockId = id; e.dataTransfer.setData('text/plain', String(id));
  // Sans ça, le navigateur utilise par défaut l'élément qui porte draggable="true" comme
  // aperçu de déplacement -- ici la petite poignée ⠿ elle-même (isolée du reste du bloc
  // pour ne pas entrer en conflit avec la sélection de texte, voir singleBlockHTML), ce qui
  // donnait l'impression que rien ne se soulevait visuellement pendant le glisser. On
  // indique explicitement d'utiliser le bloc entier (.nb-figure-row) comme aperçu.
  const blockEl = e.target.closest('.nb-figure-row');
  if(blockEl && e.dataTransfer.setDragImage) e.dataTransfer.setDragImage(blockEl, 20, 20);
  if(blockEl) blockEl.style.opacity = '.4'; // le bloc d'origine s'estompe pendant le glisser
}
function evalDragEnd(e){
  const blockEl = e.target.closest('.nb-figure-row');
  if(blockEl) blockEl.style.opacity = '';
}
function evalDropInRowCol(e, ctx, rowIndex, colIndex){
  e.preventDefault();
  const arr = blocksStores[ctx]||[];
  const b = arr.find(x=>x.id===evalDragBlockId);
  if(b){
    const moved = (b.row||0)!==rowIndex || (b.col||0)!==colIndex;
    b.row = rowIndex; b.col = colIndex;
    if(moved){
      // La taille mémorisée (posée par le ResizeObserver -- voir attachResizeObservers) ne
      // reflète que la largeur de l'ANCIENNE zone (ex. 1/3 de la page dans une ligne à 3
      // colonnes). En changeant de zone, on l'efface pour que le bloc retrouve une taille
      // naturelle adaptée à sa nouvelle zone, au lieu de rester figé à l'ancienne largeur.
      b.width = null; b.height = null;
    }
    ctx==='global' ? renderCorrectionPreview() : renderEvalExercicesList();
  }
  evalDragBlockId = null;
}
/* Bascule une bordure (haut/droite/bas/gauche) d'une cellule (ligne-colonne) d'un exercice --
   un peu comme un éditeur de tableau où l'on choisit quels bords de cellule apparaissent. */
let corCellBorders = {};
const CELL_BG_COLORS = {rouge:'#D93025', bleu:'#1F3A5C', vert:'#2C5A2E', orange:'#E35D3A'};
function toggleCellBorder(ctx, cellKey, side){
  let borders;
  if(ctx==='global'){
    borders = corCellBorders;
  } else {
    const ex = getExerciseByCtx(ctx);
    if(!ex) return;
    if(!ex.cellBorders) ex.cellBorders = {};
    borders = ex.cellBorders;
  }
  if(!borders[cellKey]) borders[cellKey] = {};
  borders[cellKey][side] = !borders[cellKey][side];
  ctx==='global' ? renderCorrectionPreview() : renderEvalExercicesList();
}
/* Fond coloré d'une zone/colonne -- même palette que {{couleur|texte}}, pour rester cohérent
   avec le reste du site. Cliquer une couleur déjà choisie la retire (case à cocher, pas une
   liste à choix unique imposé). */
function setCellBg(ctx, cellKey, colorKey){
  let borders;
  if(ctx==='global'){
    borders = corCellBorders;
  } else {
    const ex = getExerciseByCtx(ctx);
    if(!ex) return;
    if(!ex.cellBorders) ex.cellBorders = {};
    borders = ex.cellBorders;
  }
  if(!borders[cellKey]) borders[cellKey] = {};
  borders[cellKey].bg = (borders[cellKey].bg===colorKey) ? null : colorKey;
  ctx==='global' ? renderCorrectionPreview() : renderEvalExercicesList();
}
/* Rendu en lignes indépendantes, chacune avec son propre nombre de colonnes (ex. 3 colonnes
   puis 2 colonnes en dessous). rows est un tableau [nColsLigne1, nColsLigne2, ...]. */
function blocksRowsHTML(ctx, rows, withControls, cellBorders){
  cellBorders = cellBorders || {};
  const arr = blocksStores[ctx]||[];
  return rows.map((nCols,rowIdx)=>{
    const rowBlocks = arr.filter(b=>(b.row||0)===rowIdx);
    if(nCols<=1){
      const inner = rowBlocks.map(b=>singleBlockHTML(b, ctx, withControls, true)).join('');
      const key = rowIdx+'-0';
      const cb = cellBorders[key] || {};
      if(!withControls){
        const realBorder = (cb.right?'border-right:1.3px solid #1C1B2E;':'') + (cb.bottom?'border-bottom:1.3px solid #1C1B2E;':'') + (cb.left?'border-left:1.3px solid #1C1B2E;':'') + (cb.top?'border-top:1.3px solid #1C1B2E;':'');
        const bgStyle = cb.bg ? `background-color:${CELL_BG_COLORS[cb.bg]}22;border-radius:6px;` : '';
        return `<div style="${(realBorder||bgStyle)?'padding:6px;':''}${realBorder}${bgStyle}margin-bottom:2px;">${inner}</div>`;
      }
      const dropAttrs = `ondragover="event.preventDefault()" ondrop="evalDropInRowCol(event,'${ctx}',${rowIdx},0)"`;
      const isTarget = blockTargetCtx===ctx && blockTargetRow===rowIdx && blockTargetCol===0;
      const targetBorder = isTarget ? 'border:2px solid var(--accent);' : 'border:1px dashed rgba(28,43,57,.15);';
      const targetTag = isTarget ? `<span style="position:absolute;top:3px;right:3px;font-size:.62rem;font-weight:700;color:var(--accent);background:rgba(12,91,160,.1);border-radius:8px;padding:1px 6px;z-index:2;"><span class=gicon>location_on</span> destination</span>` : '';
      const mk = (side,icon,title) => `<button type="button" onclick="toggleCellBorder('${ctx}','${key}','${side}')" title="${title}" style="font-size:.62rem;line-height:1;border:1px solid ${cb[side]?'#0D5BA3':'rgba(28,43,57,.25)'};background:${cb[side]?'#0D5BA3':'#fff'};color:${cb[side]?'#fff':'#666'};border-radius:3px;padding:2px 4px;cursor:pointer;">${icon}</button>`;
      const borderBtns = `<div style="position:absolute;bottom:3px;right:3px;display:flex;gap:2px;z-index:2;">${mk('top','▔','Bordure haute')}${mk('right','▕','Bordure droite')}${mk('bottom','▁','Bordure basse')}${mk('left','▏','Bordure gauche')}</div>`;
      const bgSwatches = Object.keys(CELL_BG_COLORS).map(k=>`<button type="button" onclick="setCellBg('${ctx}','${key}','${k}')" title="Fond ${k}" style="width:13px;height:13px;border-radius:50%;border:${cb.bg===k?'2px solid #1C1B2E':'1px solid rgba(28,43,57,.3)'};background:${CELL_BG_COLORS[k]};cursor:pointer;padding:0;"></button>`).join('');
      const bgSwatchesBox = `<div style="position:absolute;bottom:3px;left:3px;display:flex;gap:3px;z-index:2;">${bgSwatches}</div>`;
      const cellBgStyle = cb.bg ? `background-color:${CELL_BG_COLORS[cb.bg]}22;` : '';
      return `<div ${dropAttrs} onclick="selectBlockTarget('${ctx}',${rowIdx},0)" title="Cliquer pour choisir cette zone comme destination des prochains blocs ajoutés" style="cursor:pointer;position:relative;min-height:40px;${targetBorder}border-radius:8px;padding:6px;margin-bottom:6px;background:#fff;${cellBgStyle}">${targetTag}${inner}${borderBtns}${bgSwatchesBox}</div>`;
    }
    const cols = Array.from({length:nCols}, ()=>[]);
    rowBlocks.forEach(b=>{ const c = Math.min(b.col||0, nCols-1); cols[c].push(b); });
    const colsHtml = cols.map((blocksInCol, ci)=>{
      const inner = blocksInCol.map(b=>singleBlockHTML(b, ctx, withControls, true)).join('');
      const key = rowIdx+'-'+ci;
      const cb = cellBorders[key] || {};
      // En édition : le pointillé reste l'indicateur de zone de dépôt, quel que soit le
      // réglage choisi. Dans la version propre (aperçu/export) : les vraies bordures choisies
      // s'appliquent, en trait plein.
      if(!withControls){
        const realBorder = (cb.right?'border-right:1.3px solid #1C1B2E;':'') + (cb.bottom?'border-bottom:1.3px solid #1C1B2E;':'') + (cb.left?'border-left:1.3px solid #1C1B2E;':'') + (cb.top?'border-top:1.3px solid #1C1B2E;':'');
        const bgStyle = cb.bg ? `background-color:${CELL_BG_COLORS[cb.bg]}22;border-radius:6px;` : '';
        return `<div class="eval-col" style="flex:1;min-width:0;padding:${(realBorder||bgStyle)?'6px':'0'};${realBorder}${bgStyle}">${inner}</div>`;
      }
      const dropAttrs = `ondragover="event.preventDefault()" ondrop="evalDropInRowCol(event,'${ctx}',${rowIdx},${ci})"`;
      const isTarget = blockTargetCtx===ctx && blockTargetRow===rowIdx && blockTargetCol===ci;
      const targetBorder = isTarget ? 'border:2px solid var(--accent);' : 'border:1px dashed rgba(28,43,57,.15);';
      const targetTag = isTarget ? `<span style="position:absolute;top:3px;right:3px;font-size:.6rem;font-weight:700;color:var(--accent);background:rgba(12,91,160,.1);border-radius:8px;padding:1px 5px;z-index:2;"><span class=gicon>location_on</span></span>` : '';
      const mk = (side,icon,title) => `<button type="button" onclick="toggleCellBorder('${ctx}','${key}','${side}')" title="${title}" style="font-size:.62rem;line-height:1;border:1px solid ${cb[side]?'#0D5BA3':'rgba(28,43,57,.25)'};background:${cb[side]?'#0D5BA3':'#fff'};color:${cb[side]?'#fff':'#666'};border-radius:3px;padding:2px 4px;cursor:pointer;">${icon}</button>`;
      const borderBtns = `<div style="position:absolute;bottom:3px;right:3px;display:flex;gap:2px;z-index:2;">${mk('top','▔','Bordure haute')}${mk('right','▕','Bordure droite')}${mk('bottom','▁','Bordure basse')}${mk('left','▏','Bordure gauche')}</div>`;
      const bgSwatches = Object.keys(CELL_BG_COLORS).map(k=>`<button type="button" onclick="setCellBg('${ctx}','${key}','${k}')" title="Fond ${k}" style="width:13px;height:13px;border-radius:50%;border:${cb.bg===k?'2px solid #1C1B2E':'1px solid rgba(28,43,57,.3)'};background:${CELL_BG_COLORS[k]};cursor:pointer;padding:0;"></button>`).join('');
      const bgSwatchesBox = `<div style="position:absolute;bottom:3px;left:3px;display:flex;gap:3px;z-index:2;">${bgSwatches}</div>`;
      const cellBgStyle = cb.bg ? `background-color:${CELL_BG_COLORS[cb.bg]}22;` : '';
      return `<div class="eval-col" ${dropAttrs} onclick="selectBlockTarget('${ctx}',${rowIdx},${ci})" title="Cliquer pour choisir cette zone comme destination des prochains blocs ajoutés" style="cursor:pointer;position:relative;flex:1;min-width:0;min-height:50px;${targetBorder}border-radius:8px;padding:6px;background:#fff;${cellBgStyle}">${targetTag}${inner}${borderBtns}${bgSwatchesBox}</div>`;
    }).join('');
    return `<div style="display:flex;gap:10px;align-items:flex-start;margin-bottom:6px;">${colsHtml}</div>`;
  }).join('');
}
/* Barre des 7 outils, réutilisable pour l'outil de correction ou pour un exercice d'évaluation
   -- chaque bouton fixe le contexte visé juste avant d'ouvrir le panneau de l'outil. */
/* Mémorise la taille choisie par le professeur quand il redimensionne un bloc (poignée native
   du navigateur, coin bas-droit), pour que cette taille soit conservée dans l'export/la
   projection -- sinon un redimensionnement ne survivrait pas au prochain rendu. */
function attachResizeObservers(){
  if(!window.ResizeObserver) return;
  document.querySelectorAll('.resizable-block').forEach(el=>{
    if(el.dataset.observed) return;
    el.dataset.observed = '1';
    // Seul un redimensionnement FAIT PAR LE PROFESSEUR (poignée tirée à la souris ou au doigt)
    // est enregistré. Avant, toute variation de taille l'était : passage de l'exercice en
    // colonnes, largeur de fenêtre, texte qui se réorganise... Un bloc de texte se retrouvait
    // alors figé à une largeur et une hauteur arbitraires et coupé dans l'aperçu et le PDF ; et
    // à chaque re-rendu (valider, déplacer, insérer), l'élément retiré de la page était mesuré
    // 0 x 0, ce qui effaçait au contraire les vrais redimensionnements.
    el.addEventListener('pointerdown', ()=>{
      el._manualResizeUntil = Infinity;
      window.addEventListener('pointerup', ()=>{ el._manualResizeUntil = performance.now() + 400; }, { once:true });
    });
    new ResizeObserver(entries=>{
      if(!el.isConnected || !entries[0].contentRect.width) return;
      if(!(performance.now() < (el._manualResizeUntil || 0))) return;
      const id = parseInt(el.dataset.blockId), ctx = el.dataset.ctx;
      const arr = blocksStores[ctx]||[];
      const b = arr.find(x=>x.id===id);
      if(b){ b.width = Math.round(entries[0].contentRect.width); b.height = Math.round(entries[0].contentRect.height); }
    }).observe(el);
  });
  syncDiskSizes(document);
}
/* Harmonise le diamètre de tous les disques d'un même exercice (ou de l'outil de correction) sur
   le plus petit d'entre eux, pour un rendu visuellement cohérent quand plusieurs blocs disque
   coexistent. Mesure réelle dans le DOM fourni (root) -- peut être la page d'édition, l'aperçu,
   ou même le document d'une fenêtre d'impression séparée : on y a accès directement depuis ce
   script (même origine), pas besoin que cette fenêtre exécute quoi que ce soit elle-même. */
function syncDiskSizes(root){
  if(!root) return;
  ['disque','rectFrac'].forEach(type=>{
    const contexts = new Set(Object.values(blocksStores).flat().filter(b=>b.type===type).map(b=>b.ctx));
    contexts.forEach(ctx=>{
      const shapeBlocks = (blocksStores[ctx]||[]).filter(b=>b.type===type);
      if(shapeBlocks.length<2) return;
      let minDiam = Infinity;
      shapeBlocks.forEach(b=>{
        const wrap = root.querySelector(`.disk-sync-target[data-block-id="${b.id}"]`);
        if(!wrap) return;
        const svg = wrap.querySelector('svg');
        if(svg){ const w = svg.getBoundingClientRect().width; if(w>0) minDiam = Math.min(minDiam, w); }
      });
      if(minDiam===Infinity) return;
      minDiam = Math.round(minDiam);
      shapeBlocks.forEach(b=>{
        const wrap = root.querySelector(`.disk-sync-target[data-block-id="${b.id}"]`);
        if(!wrap) return;
        wrap.querySelectorAll(':scope > div > div').forEach(d=>{ d.style.maxWidth = minDiam+'px'; });
      });
    });
  });
}
/* Version autonome de la synchronisation des tailles de disques, pour le cahier de corrections
   imprimé : contrairement à syncDiskSizes (qui s'appuie sur blocksStores, donc uniquement la
   correction en cours d'édition), le cahier assemble plusieurs corrections déjà enregistrées
   dont les données de blocs ne sont plus en mémoire au moment de l'impression -- on regroupe
   donc directement par correction affichée dans le DOM (.cahier-print-entry), sans dépendre de
   blocksStores. */
function syncDiskSizesForPrint(root){
  if(!root) return;
  root.querySelectorAll('.cahier-print-entry').forEach(entryEl=>{
    const wraps = entryEl.querySelectorAll('.disk-sync-target');
    if(wraps.length<2) return;
    let minDiam = Infinity;
    wraps.forEach(wrap=>{
      const svg = wrap.querySelector('svg');
      if(svg){ const w = svg.getBoundingClientRect().width; if(w>0) minDiam = Math.min(minDiam, w); }
    });
    if(minDiam===Infinity) return;
    minDiam = Math.round(minDiam);
    wraps.forEach(wrap=>{
      wrap.querySelectorAll(':scope > div > div').forEach(d=>{ d.style.maxWidth = minDiam+'px'; });
    });
  });
}
