/* Inscription en libre-service pour les professeurs (accès réservé aux adresses
   académiques @ac-...fr, UAI de l'établissement obligatoire). Le compte créé reste en
   attente ("pending") jusqu'à validation manuelle par l'admin (voir la partie
   Administration) -- la base de données empêche déjà, via RLS + trigger, qu'un compte
   s'auto-approuve ou s'attribue un autre rôle que "prof". */
const PROF_SIGNUP_EMAIL_RE = /^[^\s@]+@ac-[a-z-]+\.(fr|nc|pf|wf)$/i;
const PROF_SIGNUP_UAI_RE = /^[0-9]{7}[A-Za-z]$/;
function openProfSignupModal(){
  document.getElementById('profSignupModalOverlay').style.display = 'flex';
  document.getElementById('profSignupStatus').textContent = '';
}
function closeProfSignupModal(){
  document.getElementById('profSignupModalOverlay').style.display = 'none';
}
async function submitProfSignup(){
  const status = document.getElementById('profSignupStatus');
  const btn = document.getElementById('btnProfSignupSubmit');
  const prenom = document.getElementById('profSignupPrenom').value.trim();
  const nom = document.getElementById('profSignupNom').value.trim();
  const email = document.getElementById('profSignupEmail').value.trim();
  const uai = document.getElementById('profSignupUai').value.trim().toUpperCase();
  const password = document.getElementById('profSignupPassword').value;

  if(!prenom || !nom || !email || !uai || !password){
    status.textContent = 'Merci de remplir tous les champs.'; return;
  }
  if(!PROF_SIGNUP_EMAIL_RE.test(email)){
    status.textContent = "L'inscription nécessite une adresse académique, de la forme ...@ac-nomacademie.fr.";
    return;
  }
  if(!PROF_SIGNUP_UAI_RE.test(uai)){
    status.textContent = 'Le code UAI doit comporter 7 chiffres suivis d\'une lettre (ex. 0541306B).';
    return;
  }
  if(password.length < 8){
    status.textContent = 'Le mot de passe doit comporter au moins 8 caractères.'; return;
  }

  btn.disabled = true;
  status.textContent = 'Inscription en cours…';

  // Les informations d'inscription voyagent avec le compte (user_metadata) : si Supabase exige
  // la confirmation de l'adresse, l'inscription se termine toute seule au retour du lien reçu
  // par e-mail (finaliserInscriptionEnAttente, appelée par refreshAuthUI).
  const { data: signUpData, error: signUpError } = await sb.auth.signUp({ email, password, options: {
    emailRedirectTo: location.origin + '/',
    data: { inscription: 'prof', nom, prenom, uai },
  } });
  if(signUpError){
    status.textContent = 'Erreur : '+signUpError.message;
    btn.disabled = false;
    return;
  }
  const userId = signUpData.user && signUpData.user.id;
  if(!userId || !signUpData.session){
    status.textContent = "Presque fini ! Un e-mail de confirmation vient d'être envoyé à votre adresse académique : cliquez sur le lien qu'il contient pour valider votre inscription (pensez à regarder dans les indésirables).";
    btn.disabled = false;
    return;
  }

  // L'établissement doit exister dans notre référentiel (contrainte de clé étrangère sur
  // profiles.uai) : on le crée avec un nom provisoire si inconnu, l'admin complètera le
  // nom réel au moment de la validation.
  await sb.from('etablissements').upsert({ uai, nom: 'À vérifier par l\'administrateur' }, { onConflict: 'uai', ignoreDuplicates: true });

  const { error: profileError } = await sb.from('profiles').insert({
    id: userId, role: 'prof', nom, prenom, email, uai,
    signup_status: 'pending', subscription_status: 'trial',
  });
  if(profileError){
    status.textContent = 'Erreur lors de la création du profil : '+profileError.message;
    btn.disabled = false;
    return;
  }

  // Notification à contact@latelieraugmente.fr : volontairement non-bloquant -- si l'envoi
  // échoue (ex. secret RESEND_API_KEY pas encore configuré côté Supabase), l'inscription
  // elle-même reste enregistrée et valide, seule la notification est manquée.
  try{ await sb.functions.invoke('notify-prof-signup', { body: { nom, prenom, email, uai } }); }catch(e){ /* silencieux, voir commentaire ci-dessus */ }

  status.textContent = "Inscription enregistrée ! Votre compte sera activé après vérification par l'administrateur, avec 15 jours d'essai gratuit à compter de l'activation.";
  document.getElementById('profSignupPrenom').value = '';
  document.getElementById('profSignupNom').value = '';
  document.getElementById('profSignupEmail').value = '';
  document.getElementById('profSignupUai').value = '';
  document.getElementById('profSignupPassword').value = '';
  btn.disabled = false;
}
/* Démarre le paiement de l'abonnement annuel via Stripe Checkout : demande une session
   à l'Edge Function create-checkout-session (qui connaît le prix et la clé secrète côté
   serveur), puis redirige vers la page de paiement hébergée par Stripe. */
async function startStripeCheckout(){
  const status = document.getElementById('subscribeStatus');
  const btn = document.getElementById('btnSubscribe');
  btn.disabled = true;
  status.textContent = 'Redirection vers le paiement…';
  try{
    const { data, error } = await sb.functions.invoke('create-checkout-session', {
      body: { origin: window.location.origin }
    });
    if(error || !data || !data.url){
      status.textContent = "Erreur : impossible de démarrer le paiement pour le moment. Réessayez plus tard ou contactez contact@latelieraugmente.fr.";
      btn.disabled = false;
      return;
    }
    window.location.href = data.url;
  }catch(e){
    status.textContent = 'Erreur : '+e.message;
    btn.disabled = false;
  }
}
/* Inscription commencée avant la confirmation de l'adresse e-mail (lien reçu par e-mail) : le
   compte existe, pas encore le profil. On le crée à la première connexion, à partir des
   informations saisies lors de l'inscription (user_metadata). Une seule fois par page. */
let finalisationInscription = null;
function finaliserInscriptionEnAttente(user){
  if(finalisationInscription) return finalisationInscription;
  const m = (user && user.user_metadata) || {};
  finalisationInscription = (async ()=>{
    try{
      if(m.inscription==='famille' && typeof famCall==='function'){
        await famCall({ action:'inscription', prenom:m.prenom, nom:m.nom, certification:m.certification===true, cgv:m.cgv===true });
        return true;
      }
      if(m.inscription==='prof' && m.uai){
        await sb.from('etablissements').upsert({ uai: m.uai, nom: 'À vérifier par l\'administrateur' }, { onConflict: 'uai', ignoreDuplicates: true });
        const { error } = await sb.from('profiles').insert({ id: user.id, role: 'prof', nom: m.nom, prenom: m.prenom, email: user.email, uai: m.uai,
          signup_status: 'pending', subscription_status: 'trial' });
        if(error) return false;
        try{ await sb.functions.invoke('notify-prof-signup', { body: { nom: m.nom, prenom: m.prenom, email: user.email, uai: m.uai } }); }catch(e){ /* non bloquant */ }
        return true;
      }
    }catch(e){ console.warn('Finalisation de l\'inscription :', e); }
    return false;
  })();
  return finalisationInscription;
}
async function refreshAuthUI(){
  const { data:{ session } } = await sb.auth.getSession();
  const loggedOutEl = document.getElementById('accountLoggedOut'), loggedInEl = document.getElementById('accountLoggedIn');
  const navAdmin = document.getElementById('navAdmin');
  const navCorrection = document.getElementById('navCorrection'), navCahier = document.getElementById('navCahier');
  const navMesResultats = document.getElementById('navMesResultats');
  const navMesDevoirs = document.getElementById('navMesDevoirs');

  if(session){
    currentUser = session.user;
    const profileCols = 'role,nom,prenom,uai,signup_status,subscription_status,subscription_expires_at,must_change_password';
    let { data: profile } = await sb.from('profiles').select(profileCols).eq('id', currentUser.id).maybeSingle();
    if(!profile && currentUser.user_metadata && currentUser.user_metadata.inscription && await finaliserInscriptionEnAttente(currentUser)){
      ({ data: profile } = await sb.from('profiles').select(profileCols).eq('id', currentUser.id).maybeSingle());
    }
    currentUserRole = profile ? profile.role : null;
    // Offre Famille (parent, ou enfant d'une famille) : niveaux ouverts -- voir famille.js.
    const prevFamilleNiveaux = JSON.stringify(typeof familleNiveaux!=='undefined' ? familleNiveaux : null);
    if(typeof familleLoad==='function') await familleLoad(currentUserRole);
    const familleChanged = prevFamilleNiveaux !== JSON.stringify(typeof familleNiveaux!=='undefined' ? familleNiveaux : null);
    const isFamilleEnfant = currentUserRole==='eleve' && typeof famState!=='undefined' && !!famState;
    // Référent d'établissement, et licence de l'établissement (couvre tous ses professeurs).
    currentReferentEtab = null; currentEtabLicence = null;
    if(profile && profile.role!=='eleve' && profile.role!=='parent'){
      const todayStr = new Date().toISOString().slice(0,10);
      const [{ data: refEtab }, { data: myEtab }] = await Promise.all([
        sb.from('etablissements').select('uai,nom,licence_until,site_key_allowed,site_key_monthly_cap').eq('referent_id', currentUser.id).maybeSingle(),
        profile.uai ? sb.from('etablissements').select('uai,nom,licence_until').eq('uai', profile.uai).maybeSingle() : Promise.resolve({data:null}),
      ]);
      if(refEtab && profile.role!=='admin') currentReferentEtab = refEtab;
      if(myEtab && myEtab.licence_until && myEtab.licence_until >= todayStr) currentEtabLicence = myEtab.licence_until;
    }
    // Offres professeur (offres-prof.js) : niveaux ouverts d'un Professeur seul, ou de l'élève d'une
    // classe créée en libre-service.
    const prevOffreNiveaux = JSON.stringify(typeof offreNiveaux!=='undefined' ? offreNiveaux : null);
    if(typeof offreLoad==='function') await offreLoad(currentUserRole, !!currentEtabLicence);
    const offreChanged = prevOffreNiveaux !== JSON.stringify(typeof offreNiveaux!=='undefined' ? offreNiveaux : null);
    niveauxMenusMaj();

    loggedOutEl.style.display='none'; loggedInEl.style.display='block';
    const prenomTrim = profile && profile.prenom ? profile.prenom.trim() : '';
    const nomTrim = profile && profile.nom ? profile.nom.trim() : '';
    const fullName = [prenomTrim, nomTrim].filter(Boolean).join(' ');
    document.getElementById('accountNameDisplay').textContent = fullName || currentUser.email;

    // Un compte prof en attente de validation, refusé, ou dont l'abonnement a expiré ne
    // doit pas accéder aux fonctionnalités (mais reste connecté pour voir son statut).
    const pendingOrRejected = profile && profile.role==='prof' && (profile.signup_status==='pending' || profile.signup_status==='rejected');
    // Une licence établissement active lève l'expiration de l'abonnement individuel.
    // Essai de 15 jours ou offre payée dont la date est dépassée : bloqué aussi (jusqu'ici l'essai
    // n'expirait jamais, seul le statut « expired » posé à la main bloquait).
    const subscriptionExpired = profile && !currentEtabLicence && (profile.subscription_status==='expired'
      || (profile.role==='prof' && !!profile.subscription_expires_at && new Date(profile.subscription_expires_at) < new Date()));
    const accessBlocked = pendingOrRejected || subscriptionExpired;
    if(pendingOrRejected){
      document.getElementById('accountRoleDisplay').innerHTML = profile.signup_status==='pending'
        ? '<span class=gicon>hourglass_top</span> Inscription en attente de validation par l\'administrateur.'
        : '<span class=gicon>cancel</span> Inscription refusée. Contactez contact@latelieraugmente.fr.';
    } else if(subscriptionExpired){
      document.getElementById('accountRoleDisplay').innerHTML = profile.role==='prof'
        ? '<span class=gicon>warning</span> Essai ou offre terminé : choisissez votre offre dans « Mon abonnement ».'
        : '<span class=gicon>warning</span> Abonnement expiré. Contactez contact@latelieraugmente.fr pour le renouveler.';
    } else {
      document.getElementById('accountRoleDisplay').textContent =
        (currentUserRole==='admin' ? 'Administrateur' : currentUserRole==='prof' ? 'Professeur' : currentUserRole==='parent' ? 'Parent · compte Famille' : isFamilleEnfant ? 'Élève · compte Famille' : currentUserRole==='eleve' ? 'Élève' : '')
        + (currentReferentEtab ? ' · référent '+(currentReferentEtab.nom||currentReferentEtab.uai) : '')
        + (currentEtabLicence && currentUserRole==='prof' ? ' · licence établissement jusqu\'au '+new Date(currentEtabLicence+'T00:00:00').toLocaleDateString('fr-FR') : '');
    }

    // Avatar : première lettre du prénom en majuscule -- signalé : "la pastille de l'élève
    // quand il est connecté doit afficher la première lettre de son prénom en majuscule".
    // Repli sur la première lettre du nom si pas de prénom, puis sur l'icône générique --
    // jamais de case vide dans le rond.
    const avatarBtn = document.getElementById('accountAvatar');
    const avatarLetter = (prenomTrim || nomTrim || '').charAt(0).toUpperCase();
    avatarBtn.innerHTML = avatarLetter || '<span class=gicon>person</span>';
    avatarBtn.title = fullName ? `Mon compte · ${fullName}` : 'Mon compte';

    const isStaff = !accessBlocked && (currentUserRole==='admin' || currentUserRole==='prof');
    isStaffGlobal = isStaff;
    if(navCorrection) navCorrection.style.display = isStaff ? 'inline-block' : 'none';
    if(navCahier) navCahier.style.display = (accessBlocked || currentUserRole==='parent') ? 'none' : 'inline-block'; // accessible à tous les comptes connectés (prof, admin, élève), sauf accès bloqué
    if(navMesResultats) navMesResultats.style.display = (!accessBlocked && currentUserRole==='eleve') ? 'inline-block' : 'none';
    if(navMesDevoirs) navMesDevoirs.style.display = (!accessBlocked && currentUserRole==='eleve' && !isFamilleEnfant) ? 'inline-block' : 'none';
    const mtDirect = document.getElementById('mtDirect'); // séance en direct : code du tableau, en haut de « Mon travail »
    if(mtDirect) mtDirect.style.display = (!accessBlocked && currentUserRole==='eleve' && !isFamilleEnfant) ? '' : 'none';
    const navFamille = document.getElementById('navFamille');
    if(navFamille) navFamille.style.display = currentUserRole==='parent' ? 'inline-block' : 'none';
    if(navAdmin){
      navAdmin.style.display = (!accessBlocked && (currentUserRole==='admin' || currentReferentEtab)) ? 'inline-block' : 'none';
      navAdmin.textContent = currentUserRole==='admin' ? 'Administration' : 'Mon établissement';
    }
    // Outils IA : affichés selon les droits (IA du professeur, IA accordée aux élèves) -- voir
    // ia-compte.js. Le bouton reste masqué par CSS tant que l'accès n'est pas confirmé.
    const tbBtnAi = document.getElementById('tbBtnAi');
    if(tbBtnAi) tbBtnAi.style.display = accessBlocked ? 'none' : 'inline-block';
    const btnIaSettings = document.getElementById('btnIaSettings');
    if(btnIaSettings) btnIaSettings.style.display = isStaff ? 'block' : 'none';
    if(accessBlocked){ if(typeof clearAiAccess==='function') clearAiAccess(); }
    else if(typeof loadAiAccess==='function') loadAiAccess();
    const btnReportBug = document.getElementById('btnReportBug');
    if(btnReportBug) btnReportBug.style.display = isStaff ? 'block' : 'none';
    const chapSuggestRow = document.getElementById('chapSuggestRow');
    if(chapSuggestRow) chapSuggestRow.style.display = isStaff ? 'block' : 'none';
    if(typeof cpOnAuthChange==='function') cpOnAuthChange();
    // « Mon abonnement » (offres-prof.js) : pour les profs approuvés hors licence établissement --
    // offre, classes en libre-service, factures ; accessible aussi quand l'essai est terminé.
    const btnSubscribe = document.getElementById('btnSubscribe');
    if(btnSubscribe){
      const showSubscribe = profile && profile.role==='prof' && profile.signup_status==='approved' && !currentEtabLicence;
      btnSubscribe.style.display = showSubscribe ? 'block' : 'none';
      btnSubscribe.innerHTML = (profile && (subscriptionExpired || profile.subscription_status==='trial'))
        ? '<span class="gicon">credit_card</span> Choisir mon offre' : '<span class="gicon">workspace_premium</span> Mon abonnement'; // « Mes classes » = le suivi des classes (Outils prof)
    }
    const btnGenerateQuiz = document.getElementById('btnGenerateQuiz'), quizLoginHint = document.getElementById('quizLoginHint');
    if(btnGenerateQuiz) btnGenerateQuiz.style.display = 'inline-block';
    if(quizLoginHint) quizLoginHint.style.display = 'none';

    if(currentUserRole==='admin' || currentReferentEtab){ if(typeof adminApplyScopeUI==='function') adminApplyScopeUI(); await adminRefreshDropdowns(); }
    if(isStaff) await loadMyClasses();
    // Panneau "ce qui mérite votre attention" sur l'accueil, à la place d'un email de rappel --
    // voir renderProfHomeDigest plus bas.
    if(isStaff) await renderProfHomeDigest();
    else { const digestEl=document.getElementById('profHomeDigest'); if(digestEl){ digestEl.style.display='none'; digestEl.innerHTML=''; } }
    if(typeof homeOrdonner==='function') homeOrdonner();
    if(currentUserRole==='eleve') await loadMyStudentClasses();
    // Pastille "devoirs en attente" sur le bouton "Mes devoirs" -- signalé : "les élèves sont-ils
    // prévenus... ?". accountClassesList doit déjà être peuplée (loadMyStudentClasses ci-dessus).
    if(typeof refreshDevoirsNavBadge==='function') await refreshDevoirsNavBadge();

    // Première connexion (ou tout compte créé/réinitialisé par un administrateur) : la
    // modale de changement de mot de passe s'ouvre automatiquement, sans possibilité de
    // l'ignorer, tant que le mot de passe n'a pas été changé.
    if(profile && profile.must_change_password && !mdpJusteChange) openChangePasswordModal(true);
    // Retour du lien « mot de passe oublié » reçu par e-mail.
    if(/[?&]reinit=1/.test(location.search)) ouvrirReinitialisation();

    // Restriction d'accès aux chapitres non gratuits : levée pour tout compte élève, et
    // pour un compte prof/admin approuvé et à jour (essai ou abonnement actif).
    const wasRestricted = restrictedVisitor;
    restrictedVisitor = accessBlocked || !(currentUserRole==='eleve' || currentUserRole==='parent' || isStaff);
    if((wasRestricted !== restrictedVisitor || familleChanged || offreChanged) && currentLevel) renderNiveau(currentLevel);
  } else {
    currentUser = null; currentUserRole = null; currentClassId = null; currentReferentEtab = null; currentEtabLicence = null; currentReferentEtab = null; currentEtabLicence = null;
    loggedOutEl.style.display='block'; loggedInEl.style.display='none';
    isStaffGlobal = false;
    const avatarBtnOut = document.getElementById('accountAvatar');
    if(avatarBtnOut){ avatarBtnOut.innerHTML = '<span class=gicon>person</span>'; avatarBtnOut.title = 'Mon compte'; }
    if(navCorrection) navCorrection.style.display='none';
    if(navCahier) navCahier.style.display='none';
    if(navMesResultats) navMesResultats.style.display='none';
    if(navMesDevoirs) navMesDevoirs.style.display='none';
    const navFamilleOut = document.getElementById('navFamille');
    if(navFamilleOut) navFamilleOut.style.display='none';
    const hadFamille = typeof familleNiveaux!=='undefined' && familleNiveaux!==null;
    if(typeof familleClear==='function') familleClear();
    if(typeof offreClear==='function') offreClear();
    const navMesDevoirsBadgeOut = document.getElementById('navMesDevoirsBadge');
    if(navMesDevoirsBadgeOut) navMesDevoirsBadgeOut.style.display='none';
    if(navAdmin) navAdmin.style.display='none';
    const tbBtnAiOut = document.getElementById('tbBtnAi');
    if(tbBtnAiOut) tbBtnAiOut.style.display='none';
    const btnIaSettingsOut = document.getElementById('btnIaSettings');
    if(btnIaSettingsOut) btnIaSettingsOut.style.display='none';
    if(typeof clearAiAccess==='function') clearAiAccess();
    const btnReportBugOut = document.getElementById('btnReportBug');
    if(btnReportBugOut) btnReportBugOut.style.display='none';
    const chapSuggestRowOut = document.getElementById('chapSuggestRow');
    if(chapSuggestRowOut) chapSuggestRowOut.style.display='none';
    if(typeof cpOnAuthChange==='function') cpOnAuthChange();
    const btnGenerateQuiz = document.getElementById('btnGenerateQuiz'), quizLoginHint = document.getElementById('quizLoginHint');
    if(btnGenerateQuiz) btnGenerateQuiz.style.display='none';
    if(quizLoginHint) quizLoginHint.style.display='inline';
    const digestElOut = document.getElementById('profHomeDigest');
    if(digestElOut){ digestElOut.style.display='none'; digestElOut.innerHTML=''; }

    const wasRestrictedOut = restrictedVisitor;
    restrictedVisitor = true;
    if((!wasRestrictedOut || hadFamille) && currentLevel) renderNiveau(currentLevel);
  }
  // Outils de L'Atelier réservés aux comptes (demo.js) : cadenas dans le menu pour les visiteurs ; un
  // outil encore ouvert au moment de la déconnexion laisse la place à l'accueil.
  document.body.classList.toggle('connecte', !!currentUser);
  if(!currentUser){ const av = document.querySelector('.view.active');
    if(av && ['view-cm','view-compte','view-convertisseur','view-figure-sandbox','view-tableau','view-programmation'].includes(av.id)){ showView('view-home'); setActiveTopnav(null); } }
  // reflète l'état de connexion sur les boutons "+ Cahier" déjà injectés dans les cours ouverts
  updateCourseAddButtonsState();
  // Mode découverte (demo.js) : automatismes re-verrouillés / déverrouillés, et un visiteur qui
  // se connecte depuis une page de démonstration arrive directement dans l'outil.
  if(typeof renderCMPicker==='function' && document.getElementById('cmPicker')) renderCMPicker();
  if(currentUser && typeof demoOuvrirOutil==='function') demoOuvrirOutil();
  // Espace famille affiché (connexion / déconnexion depuis cette page) : on le redessine.
  const famView = document.getElementById('view-famille');
  if(famView && famView.classList.contains('active') && typeof renderFamille==='function') renderFamille();
}
sb.auth.onAuthStateChange((event)=>{
  refreshAuthUI();
  if(event === 'PASSWORD_RECOVERY') ouvrirReinitialisation();
});

/* Panneau "Ce qui mérite votre attention" sur la page d'accueil, pour prof/admin -- signalé :
   "ça pourrait être intéressant [un récap par email]... nos comptes sont fermés également aux
   adresses hors de notre domaine". Aucun mécanisme d'envoi ne marche de façon fiable pour tout
   le monde (domaines Google Education fermés, parfois même aux comptes enseignants) -- tout
   reste donc dans l'app, consulté à la connexion, sans dépendre d'aucun service externe.
   S'appuie sur deux fonctions SECURITY DEFINER (get_teacher_pending_digest,
   get_teacher_a_reprendre_digest) qui ne renvoient que les devoirs du prof connecté
   (auth.uid()). Ne montre que ce qui demande une action (devoirs pas rendus proches/dépassés de
   la date limite, "à reprendre" toujours en attente) -- pas les médailles, qui sont valorisantes
   mais pas "à traiter". */
async function renderProfHomeDigest(){
  const box = document.getElementById('profHomeDigest');
  if(!box) return;
  try{
    const [{ data: pending, error: e1 }, { data: aReprendre, error: e2 }] = await Promise.all([
      sb.rpc('get_teacher_pending_digest'),
      sb.rpc('get_teacher_a_reprendre_digest'),
    ]);
    if(e1 || e2 || (!(pending&&pending.length) && !(aReprendre&&aReprendre.length))){
      box.style.display = 'none'; box.innerHTML = '';
      return;
    }
    // Regroupé par classe -- signalé : "afficher par classe pour une meilleure lecture". Les
    // libellés viennent d'accountClassesList (déjà peuplée par loadMyClasses juste avant, voir
    // refreshAuthUI), pas d'une requête supplémentaire.
    const classLabelById = new Map(accountClassesList.map(c=>[c.id, c.label]));
    const byClass = new Map(); // class_id -> { pendingRows:[], aReprendreByDevoir: Map(devoirId -> {titre, eleves:[]}) }
    const classEntry = (classId)=>{
      if(!byClass.has(classId)) byClass.set(classId, { pendingRows:[], aReprendreByDevoir: new Map() });
      return byClass.get(classId);
    };
    (pending||[]).forEach(r=>classEntry(r.class_id).pendingRows.push(r));
    (aReprendre||[]).forEach(r=>{
      const arMap = classEntry(r.class_id).aReprendreByDevoir;
      if(!arMap.has(r.devoir_id)) arMap.set(r.devoir_id, { titre: r.devoir_titre, eleves: [] });
      arMap.get(r.devoir_id).eleves.push(profileDisplayName({nom:r.student_nom, prenom:r.student_prenom}) || '?');
    });
    const classesHtml = Array.from(byClass.entries())
      .sort((a,b)=>(classLabelById.get(a[0])||'').localeCompare(classLabelById.get(b[0])||'', 'fr'))
      .map(([classId, entry])=>{
        const pendingHtml = entry.pendingRows.map(r=>{
          const dateStr = r.date_limite ? new Date(r.date_limite).toLocaleDateString('fr-FR') : '';
          return `<div style="display:flex;justify-content:space-between;align-items:center;gap:8px;padding:6px 0;border-bottom:1px solid rgba(28,43,57,.06);flex-wrap:wrap;">
            <span class="hint" style="margin:0;"><b>${escapeHtml(r.devoir_titre)}</b> -- ${r.nb_en_attente}/${r.nb_total} élève(s) n'ont pas encore rendu${dateStr ? ' (limite : '+dateStr+')' : ''}</span>
            <button class="btn secondary" style="font-size:.72rem;padding:4px 8px;" onclick="openDevoirSubmissions('${r.devoir_id}')">Voir</button>
          </div>`;
        }).join('');
        // Regroupé par devoir (plusieurs élèves "à reprendre" sur le même devoir tiennent sur une
        // seule ligne) plutôt qu'une ligne par élève.
        const aReprendreHtml = Array.from(entry.aReprendreByDevoir.entries()).map(([devoirId, info])=>{
          return `<div style="display:flex;justify-content:space-between;align-items:center;gap:8px;padding:6px 0;border-bottom:1px solid rgba(28,43,57,.06);flex-wrap:wrap;">
            <span class="hint" style="margin:0;"><b>${escapeHtml(info.titre)}</b> -- "à reprendre" toujours en attente : ${info.eleves.map(escapeHtml).join(', ')}</span>
            <button class="btn secondary" style="font-size:.72rem;padding:4px 8px;" onclick="openDevoirSubmissions('${devoirId}')">Voir</button>
          </div>`;
        }).join('');
        return `<div style="margin-top:12px;">
          <p style="margin:0 0 4px;font-weight:700;color:var(--accent);">${escapeHtml(classLabelById.get(classId) || 'Classe')}</p>
          ${pendingHtml}${aReprendreHtml}
        </div>`;
      }).join('');
    box.innerHTML = `
      <div class="plain-card" style="padding:20px 24px;margin-bottom:20px;">
        <p style="margin:0 0 6px;font-weight:700;font-family:'Space Grotesk',sans-serif;"><span class="gicon" style="vertical-align:middle;">notifications_active</span> Ce qui mérite votre attention</p>
        ${classesHtml}
      </div>`;
    box.style.display = 'block';
  }catch(e){ box.style.display = 'none'; box.innerHTML = ''; }
}

function updateClassDisplays(name){
  const badge = document.getElementById('activeClassBadge');
  if(badge) badge.textContent = name ? '· '+name : '';
  const classStatus = document.getElementById('classStatus');
  if(classStatus) classStatus.textContent = name || 'aucune';
  const studentClassStatus = document.getElementById('studentClassStatus');
  if(studentClassStatus) studentClassStatus.textContent = name || 'aucune';
  const cahierClassStatus = document.getElementById('cahierClassStatus');
  if(cahierClassStatus) cahierClassStatus.textContent = name || 'aucune';
  const supervisionClassStatus = document.getElementById('supervisionClassStatus');
  if(supervisionClassStatus) supervisionClassStatus.textContent = name || 'aucune';
  renderClassQuickPicker('corClassQuickPicker');
  renderClassQuickPicker('cahierClassQuickPicker');
  renderClassQuickPicker('supervisionClassQuickPicker');
  // Le sélecteur rapide du cahier (boutons cliquables, comme dans l'Outil de correction)
  // n'a d'intérêt que pour un prof/admin qui bascule entre plusieurs classes -- un élève n'a
  // qu'une seule classe, la ligne simple suffit. Signalé : "le mettre également dans la
  // rubrique cahier d'élèves pour les profs".
  const isStaff = currentUserRole==='prof' || currentUserRole==='admin';
  const cahierClassBox = document.getElementById('cahierClassBox');
  const cahierClassSimple = document.getElementById('cahierClassSimple');
  if(cahierClassBox) cahierClassBox.style.display = isStaff ? 'block' : 'none';
  if(cahierClassSimple) cahierClassSimple.style.display = isStaff ? 'none' : 'flex';
  updateAddCahierButtonState();
}
/* Boutons cliquables pour choisir directement une classe sans passer par le menu compte --
   réutilisé par l'Outil de correction (#corClassQuickPicker) et le Cahier de corrections
   (#cahierClassQuickPicker, profs/admin seulement). */
function renderClassQuickPicker(boxId){
  const box = document.getElementById(boxId);
  if(!box) return;
  if(!accountClassesList.length){ box.innerHTML=''; return; }
  // Cahier et outil de correction : les groupes sans cahier (demi-groupes…) ne sont pas proposés.
  const liste = boxId==='cahierClassQuickPicker' || boxId==='corClassQuickPicker' ? accountClassesList.filter(c=>!(c.groupe && c.cahier===false)) : accountClassesList;
  box.innerHTML = liste.map(c=>`
    <button type="button" onclick="selectClassFromModal('${c.id}')" style="border:1.5px solid ${c.id===currentClassId?'#0D5BA3':'rgba(28,43,57,.2)'};background:${c.id===currentClassId?'#0D5BA3':'#fff'};color:${c.id===currentClassId?'#fff':'#333'};border-radius:20px;padding:4px 12px;margin:2px 4px 2px 0;cursor:pointer;font-size:.85rem;">${c.id===currentClassId?'✓ ':''}${escapeHtml(c.label)}</button>
  `).join('');
}
/* Le bouton d'ajout au cahier n'a de sens que si une classe est active (le cahier est propre à
   chaque classe) -- désactivé et grisé tant qu'aucune n'est sélectionnée, pour éviter toute
   confusion sur où part la correction. */
function updateAddCahierButtonState(){
  const btn = document.getElementById('btnAddCahier');
  const hint = document.getElementById('corClassHint');
  if(!btn) return;
  const disabled = !currentClassId;
  btn.disabled = disabled;
  btn.style.opacity = disabled ? '.5' : '1';
  btn.style.cursor = disabled ? 'not-allowed' : 'pointer';
  btn.title = disabled ? 'Sélectionnez une classe ci-dessus avant d\'ajouter au cahier.' : '';
  if(hint) hint.innerHTML = disabled
    ? '<span class=gicon>warning</span> Sélectionnez une classe ci-dessus pour pouvoir ajouter des corrections au cahier.'
    : '';
}
/* Libellé du bouton principal du cahier -- "+ Ajouter aux brouillons" tant que la date est vide
   (voir startBrouillon), "+ Ajouter au cahier de corrections" dès qu'une date est renseignée --
   signalé : "le bouton ajouter au cahier se transforme en ajouter aux brouillons". Sans objet en
   cours d'édition (editCahierEntry impose déjà "Enregistrer la modification", valable que
   l'entrée éditée ait une date ou non). */
function updateAddCahierButtonLabel(){
  if(editingEntryId!==null) return;
  const btn = document.getElementById('btnAddCahier');
  if(!btn) return;
  const dateField = document.getElementById('corDate');
  const isDraft = dateField && !dateField.value;
  btn.innerHTML = isDraft ? '<span class=gicon>bookmark_add</span> + Ajouter aux brouillons' : '+ Ajouter au cahier de corrections';
}
let accountClassesList = [];
function populateAccountClassList(classesList){
  // Groupes de remédiation (groupes.js) : marqués « groupe » dans le sélecteur ; groupes archivés masqués.
  accountClassesList = classesList.filter(c=>!c.archive).map(c=>({id:c.id, label: c.groupe ? `${c.nom} · groupe (${c.niveau})` : `${c.nom} (${c.niveau})`, niveau:c.niveau, groupe:!!c.groupe, cahier:c.cahier!==false}));
}
/* Le niveau de l'outil de correction suit la classe active -- signalé : "si je choisis la classe
   de 6V, il faudrait que ça modifie tout de suite le niveau dans la partie correction". Resté
   sur "5e" par défaut, il faisait ranger des corrections de 6e sous un chapitre de 5e, que les
   collègues de 6e ne retrouvaient alors jamais (ex. "1 page 10" en 6V). */
function syncCorNiveauToClass(){
  const found = accountClassesList.find(c=>c.id===currentClassId);
  const sel = document.getElementById('corNiveau');
  const niv = found && (niveauCle(found.niveau) || found.niveau); // classe « CM1 » → chapitres « cm1 »
  if(!found || !sel || sel.value===niv) return;
  if(![...sel.options].some(o=>o.value===niv)) return;
  sel.value = niv;
  fillCorChapitres();
  if(typeof renderCorrectionPreview==='function') renderCorrectionPreview();
}
