async function submitBugReport(){
  const section = document.getElementById('bugReportSection').value;
  const chapitre = document.getElementById('bugReportChapter').value.trim();
  const message = document.getElementById('bugReportMessage').value.trim();
  const status = document.getElementById('bugReportStatus');
  if(!message){ status.textContent = 'Merci de décrire le problème avant d\'envoyer.'; return; }
  status.textContent = 'Envoi en cours...';
  const { error } = await sb.from('bug_reports').insert({
    reporter_id: currentUser ? currentUser.id : null,
    section,
    chapitre: chapitre || null,
    message,
    report_type: bugReportTypeOverride,
    build_version: document.getElementById('buildTag') ? document.getElementById('buildTag').textContent.replace('build ','') : null,
  });
  if(error){ status.textContent = "Échec de l'envoi : " + error.message; return; }
  status.textContent = bugReportTypeOverride==='suggestion' ? 'Suggestion envoyée, merci !' : 'Signalement envoyé, merci !';
  document.getElementById('bugReportMessage').value='';
  bugReportTypeOverride = 'bug';
  setTimeout(()=>{ if(document.getElementById('bugReportModalOverlay').style.display!=='none') closeBugReportModal(); }, 1200);
}
async function selectClassFromModal(id){
  currentClassId = id;
  await applyClassSelection();
}
async function loadMyClasses(){
  if(!currentUser) return;
  // Toujours "mes classes" (celles où je suis prof), même pour un compte admin+prof --
  // accountClassesList alimente le sélecteur de classe active partagé par tous les outils
  // PROF (Supervision, Cahier de correction...) ; Administration a sa propre requête séparée
  // (adminRefreshDropdowns, admin.js) qui continue de lister TOUTES les classes, c'est le bon
  // endroit pour ça. Signalé : "je vois toujours dans Supervision toutes les classes alors que
  // je ne suis pas professeur dans ces classes" -- un précédent correctif n'avait traité que le
  // nouvel onglet "Mes classes" de Supervision, pas ce sélecteur, qui est la source commune de
  // currentClassId partout ailleurs.
  const res = await sb.from('class_teachers').select('classes(id,nom,niveau,groupe,archive,cahier)').eq('teacher_id', currentUser.id);
  let classesList = (res.data||[]).map(row=>row.classes).filter(Boolean), error = res.error;
  // Classe de simulation (simulateur.js) : la seule visible dans la fenêtre professeur du simulateur,
  // cachée partout ailleurs.
  if(typeof classesSimuCharger==='function'){ await classesSimuCharger(); classesList = classesList.filter(c=>classeVisible(c.id)); }
  classesList.sort((a,b)=>(!!a.groupe - !!b.groupe) || a.nom.localeCompare(b.nom)); // classes d'abord, puis les groupes
  populateAccountClassList(classesList);
  if(!accountClassesList.some(c=>c.id===currentClassId)){
    currentClassId = accountClassesList[0] ? accountClassesList[0].id : null;
  }
  await applyClassSelection();
  if(error) console.error(error);
}
async function applyClassSelection(){
  const found = accountClassesList.find(c=>c.id===currentClassId);
  const className = found ? found.label : null;
  updateClassDisplays(className);
  syncCorNiveauToClass();
  await cahierClasseResoudre();
  if(currentClassId){
    // Population initiale légère (juste aujourd'hui) -- suffisant pour la liste prof par
    // défaut) ; renderCahierEleve() affine ensuite avec son
    // propre chargement paresseux par jour pour la vue accordéon.
    const remote = await fetchCahierEntriesForDate(todayISO());
    cahier = remote || [];
    sortCahierInPlace();
    saveCahier();
  } else {
    cahier = [];
  }
  if(document.getElementById('cahierList')) renderCahier();
  if(document.getElementById('cahierEleveContent')) renderCahierEleve();
  if(document.getElementById('view-supervision').classList.contains('active')){
    renderSupervision(); renderSupervisionCeb();
    // L'onglet Devoirs dépend lui aussi de la classe active (comme Comptes/Résultats) --
    // le re-rendre si c'est l'onglet actuellement affiché, sinon il resterait sur l'ancienne
    // classe jusqu'au prochain clic sur cet onglet.
    if(document.querySelector('.sup-tab-btn[data-suptab="classes"]')?.classList.contains('active')) renderSupervisionDevoirsTab();
    if(document.querySelector('.sup-tab-btn[data-suptab="interros"]')?.classList.contains('active') && typeof npOngletInterros==='function') npOngletInterros();
    if(document.querySelector('.sup-tab-btn[data-suptab="bilan"]')?.classList.contains('active') && typeof npOngletBilan==='function') npOngletBilan();
  }
  updateCourseAddButtonsState();
}
let teacherStudentsCache = []; // {id, nom, identifiant, statutKey, badgeHtml} -- pour filtrer sans re-requêter
async function renderTeacherStudentsListing(){
  const el = document.getElementById('teacherStudentsListing');
  if(!el) return;
  if(!currentClassId){ el.innerHTML = 'Choisissez une classe pour voir ses élèves.'; return; }
  el.innerHTML = 'Chargement…';
  const { data, error } = await sb.from('class_students').select('profiles(id,nom,prenom,email)').eq('class_id', currentClassId);
  if(error){ el.innerHTML = "Erreur : "+error.message; return; }
  const students = (data||[]).map(r=>r.profiles).filter(Boolean).sort((a,b)=>(a.nom||'').localeCompare(b.nom||''));
  if(!students.length){ el.innerHTML = 'Aucun élève dans cette classe pour l\'instant.'; teacherStudentsCache=[]; return; }
  // Dernière connexion (auth.users, normalement inaccessible via RLS classique) -- exposée à
  // un prof uniquement pour SES PROPRES élèves via une fonction dédiée SECURITY DEFINER (pas
  // question qu'un prof voie la connexion des élèves d'un autre prof).
  const { data: signIns } = await sb.rpc('get_my_students_last_sign_in');
  const lastSignInMap = new Map((signIns||[]).map(r=>[r.id, r.last_sign_in_at]));
  const loginIdentifiant = email => email ? (email.endsWith('@mathcollege.local') ? email.slice(0, -('@mathcollege.local'.length)) : email) : '(inconnu)';
  // Le site n'a pas de suivi de présence en temps réel -- une connexion très récente (moins de
  // 15 min) sert d'approximation raisonnable pour "probablement en ligne actuellement".
  // 3 états visuellement distincts, demandé : "juste du texte ne permet pas de voir qui s'est
  // déjà connecté... il faut y mettre des couleurs ou des icônes clairs" -- jamais connecté
  // (rond gris), déjà connecté au moins une fois mais pas actuellement (coche bleue), en
  // ligne actuellement (rond vert). statutKey sert au filtre.
  const ONLINE_THRESHOLD_MS = 15*60*1000;
  const connexionInfo = studentId => {
    const t = lastSignInMap.get(studentId);
    if(!t) return { key:'jamais', badge:'<span style="color:#8a8f98;font-weight:600;">⚪ Jamais connecté</span>' };
    const d = new Date(t);
    const isRecent = (Date.now()-d.getTime()) < ONLINE_THRESHOLD_MS;
    if(isRecent) return { key:'enligne', badge:'<span style="color:#1F7A4D;font-weight:700;">🟢 En ligne</span>' };
    return { key:'deja', badge:`<span style="color:#0C5BA0;font-weight:600;">🔵 Déjà connecté</span> <span class="hint">(${d.toLocaleDateString('fr-FR')} ${d.toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'})})</span>` };
  };
  teacherStudentsCache = students.map(s=>{
    const info = connexionInfo(s.id);
    return { id:s.id, nom: profileDisplayName(s)||'?', identifiant: loginIdentifiant(s.email), statutKey: info.key, badgeHtml: info.badge };
  });
  renderTeacherStudentsFiltered();
}
// Identifiant masqué par défaut (bouton "Voir l'identifiant" pour le révéler au clic) --
// demandé : "mettre un bouton Voir l'identifiant plutôt que de l'afficher". Filtre par statut
// de connexion -- demandé : "permettre un filtre sur le statut".
function renderTeacherStudentsFiltered(){
  const el = document.getElementById('teacherStudentsListing');
  if(!el) return;
  const filterSel = document.getElementById('teacherStudentsStatutFilter');
  const filter = filterSel ? filterSel.value : '';
  const filtered = filter ? teacherStudentsCache.filter(s=>s.statutKey===filter) : teacherStudentsCache;
  if(!filtered.length){ el.innerHTML = 'Aucun élève ne correspond à ce filtre.'; return; }
  const statutRowBg = {enligne:'rgba(31,122,77,.05)', deja:'rgba(12,91,160,.04)', jamais:'rgba(28,43,57,.02)'};
  el.innerHTML = `<table class="sup-table">
    <thead><tr><th>Élève</th><th>Statut</th><th style="text-align:right;">Actions</th></tr></thead>
    <tbody>
    ${filtered.map(s=>{
      const label = escapeHtml(s.nom);
      const safeName = label.replace(/'/g, "\\'");
      const idfEscaped = escapeHtml(s.identifiant).replace(/'/g, "\\'");
      return `<tr style="background:${statutRowBg[s.statutKey]||''};">
        <td style="font-weight:600;">${label}</td>
        <td>${s.badgeHtml}</td>
        <td style="text-align:right;">
          <button class="btn secondary" style="font-size:.72rem;padding:4px 8px;" onclick="teacherShowIdentifiant('${safeName}','${idfEscaped}')"><span class=gicon>visibility</span> Identifiant</button>
          <button class="btn secondary" style="font-size:.72rem;padding:4px 8px;" onclick="teacherResetPasswordPrompt('${s.id}','${safeName}')"><span class=gicon>key</span> Mot de passe</button>
        </td>
      </tr>`;
    }).join('')}
    </tbody>
  </table>`;
}
