function renderMesResultatsFiltered(){
  const el = document.getElementById('mesResultatsContent');
  if(!el) return;
  if(!mesResultatsData.length){ el.innerHTML = "Vous n'avez pas encore fait d'exercice d'automatismes."; return; }
  const exoFilter = document.getElementById('mesResFilterExercice').value;
  const fromFilter = document.getElementById('mesResFilterFrom').value;
  const toFilter = document.getElementById('mesResFilterTo').value;
  const filtered = mesResultatsData.filter(r=>{
    if(exoFilter && (r.sequence_label||'-')!==exoFilter) return false;
    const d = (r.created_at||'').slice(0,10);
    if(fromFilter && d<fromFilter) return false;
    if(toFilter && d>toFilter) return false;
    return true;
  });
  if(!filtered.length){ el.innerHTML = 'Aucun résultat pour ce filtre.'; return; }
  const totalScore = filtered.reduce((s,r)=>s+r.score,0), totalMax = filtered.reduce((s,r)=>s+r.total,0);
  const avg = totalMax ? Math.round(100*totalScore/totalMax) : 0;
  const rows = filtered.map(r=>{
    const pct = Math.round(100*r.score/r.total);
    const date = new Date(r.created_at).toLocaleString('fr-FR', {day:'numeric', month:'short', hour:'2-digit', minute:'2-digit'});
    const perfect = r.score===r.total;
    return `<div style="display:flex;justify-content:space-between;gap:12px;padding:4px 0;">
      <span>${escapeHtml(r.sequence_label||'-')}</span>
      <span style="font-weight:700;color:${pct>=70?'#1F6B3A':pct>=40?'#8A4210':'#9E1F5E'};">${r.score}/${r.total}</span>
      <span style="color:var(--ink-soft);font-family:'JetBrains Mono',monospace;font-size:.82rem;">${perfect && r.duration_ms!=null ? formatDuration(r.duration_ms) : '-'}</span>
      <span style="color:var(--ink-soft);">${date}</span>
    </div>`;
  }).join('');
  el.innerHTML = `<p class="hint" style="margin:0 0 10px;">Moyenne sur cette sélection : <b>${avg}%</b> (${filtered.length} exercice(s))</p>
    <div class="tool-shell">${rows}</div>`;
}

function isSyncEnabled(){ return !!currentClassId; }
/* Groupe « sans cahier » (réglage du groupe, groupes.js) -- demandé : « un paramètre supplémentaire
   pour les groupes : apparaître dans les cahiers ou pas. Par exemple les demi-groupes de classe n'ont
   pas besoin de cahier. » Le cahier lu et écrit est alors celui de la classe d'origine de ses élèves
   (fonction cahier_classe) : un demi-groupe de 5B travaille dans le cahier de 5B. */
let cahierClasse = { pour: null, id: null, nom: '', propre: true };
async function cahierClasseResoudre(){
  if(!currentClassId){ cahierClasse = { pour: null, id: null, nom: '', propre: true }; return; }
  const c = accountClassesList.find(x=>x.id===currentClassId);
  if(!c || !c.groupe || c.cahier!==false){ cahierClasse = { pour: currentClassId, id: currentClassId, nom: c ? c.label : '', propre: true }; return; }
  if(cahierClasse.pour===currentClassId) return;
  const { data } = await sb.rpc('cahier_classe', { p_class: currentClassId });
  cahierClasse = { pour: currentClassId, id: data && data.id || null, nom: data && data.nom || '', propre: false };
}
function cahierClasseId(){ return cahierClasse.pour===currentClassId ? cahierClasse.id : currentClassId; }
// "Afficher tout l'historique" : réservé profs/admins -- demandé : "Afficher tout
// l'historique, réservé aux professeurs."
let cahierShowAll = false;
// Chargement PARESSEUX, jour par jour, au dépli de l'accordéon -- demandé : "vu qu'on déplie
// les jours (accordéon) pour voir le contenu, pourquoi ne pas faire la recherche en base quand
// on souhaite déplier un jour précis ?" Remplace l'approche précédente par fenêtre de N jours
// (signalée trop lourde même à 7 jours) : le volume transféré correspond désormais exactement
// à ce que l'utilisateur consulte réellement, quel que soit le nombre d'entrées de l'année.
let cahierDatesList = [];           // [{date, count}] -- squelette léger de l'accordéon
let cahierLoadedDates = new Set();  // dates dont le contenu complet est déjà dans `cahier`
let cahierEditableMode = false;     // mémorisé pour le rendu différé d'un jour déplié
const CAHIER_COLS_LEGERES = 'id,class_id,niveau,chapitre,exo,titre,date,raw,html,figure,created_at,ordre,modalite,teacher_id,matiere';
/* Un cahier par classe ET par professeur -- demandé : « Il faut un cahier par classe et par prof. Un cahier ne
   peut pas mélanger plusieurs matières comme un cahier d'élève. » Chaque entrée porte son auteur (teacher_id,
   rempli par la base) et sa matière. Le professeur ne voit et ne modifie que les siennes (et les anciennes,
   sans auteur) ; l'élève choisit le cahier de l'un de ses professeurs (onglets par matière). */
let cahierProfChoisi = null; // élève : teacher_id du cahier affiché ('' : entrées sans auteur ; null : pas encore choisi)
let cahierProfsListe = [];   // élève : [{t: teacher_id ou '', m: matière}] des cahiers de la classe
function cahierMatiere(){ return window.ADP ? ((typeof adpMatiere === 'function' && adpMatiere()) || null) : 'Mathématiques'; }
function cahierFiltre(q){
  if(!currentUser) return q;
  if(currentUserRole === 'eleve'){
    if(cahierProfChoisi == null) return q;
    return cahierProfChoisi === '' ? q.is('teacher_id', null) : q.eq('teacher_id', cahierProfChoisi);
  }
  return q.or(`teacher_id.eq.${currentUser.id},teacher_id.is.null`);
}
// Élève : les cahiers de sa classe (un par professeur), et celui qu'il regarde (mémorisé par classe).
async function cahierProfsCharger(){
  cahierProfsListe = [];
  if(currentUserRole !== 'eleve' || !cahierClasseId()) return;
  const { data } = await sb.from('cahier_entries').select('teacher_id,matiere').eq('class_id', cahierClasseId()).not('date', 'is', null).limit(5000);
  const vus = new Map();
  (data || []).forEach(r => { const t = r.teacher_id || ''; if(!vus.has(t) || (!vus.get(t) && r.matiere)) vus.set(t, r.matiere || ''); });
  cahierProfsListe = [...vus.entries()].map(([t, m]) => ({ t, m: m || 'Mathématiques' })).sort((a, b) => a.m.localeCompare(b.m, 'fr'));
  let memo = null; try{ memo = localStorage.getItem('cahierProf:' + cahierClasseId()); }catch(e){}
  const pref = window.ADP ? null : cahierProfsListe.find(x => x.m === 'Mathématiques');
  cahierProfChoisi = cahierProfsListe.some(x => x.t === memo) ? memo : (pref || cahierProfsListe[0] || { t: null }).t;
}
function cahierProfsOngletsHtml(){
  if(currentUserRole !== 'eleve' || cahierProfsListe.length < 2) return '';
  const nb = {}; cahierProfsListe.forEach(x => { nb[x.m] = (nb[x.m] || 0) + 1; });
  const vu = {};
  return `<div class="nb-profs" role="tablist" aria-label="Cahier de quel professeur ?">${cahierProfsListe.map(x => { vu[x.m] = (vu[x.m] || 0) + 1;
    return `<button type="button" role="tab" class="nb-prof${x.t === cahierProfChoisi ? ' on' : ''}" onclick="cahierProfChoisir('${x.t}')">${escapeHtml(x.m)}${nb[x.m] > 1 ? ' ' + vu[x.m] : ''}</button>`; }).join('')}</div>`;
}
function cahierProfChoisir(t){
  cahierProfChoisi = t;
  try{ localStorage.setItem('cahierProf:' + cahierClasseId(), t); }catch(e){}
  renderCahierEleve();
}
// Ne récupère que les dates (avec un compte d'entrées par jour) -- construit le squelette de
// l'accordéon sans charger aucun contenu. Quasi gratuit même sur une année entière (juste des
// chaînes de date, aucune colonne lourde).
async function fetchCahierDatesList(){
  if(!cahierClasseId()) return [];
  // Exclut les brouillons (date NULL) -- signalé : "mettre des exercices en attente... sans
  // mettre de date". Ne doivent jamais apparaître dans le cahier normal (vu aussi par les
  // élèves) ni dans son accordéon par date -- seulement via "Récupérer un brouillon", voir
  // fetchCahierBrouillons plus bas.
  const { data, error } = await cahierFiltre(sb.from('cahier_entries').select('date,exo').eq('class_id', cahierClasseId())).not('date', 'is', null);
  if(error){ console.error('fetch dates list failed', error); return []; }
  const counts = new Map(), cours = new Set();
  data.forEach(r=>{ const d=r.date||''; counts.set(d, (counts.get(d)||0)+1); if(r.exo==='Cours') cours.add(d); });
  return Array.from(counts.entries()).map(([date,count])=>({date,count,cours:cours.has(date)})).sort((a,b)=>a.date.localeCompare(b.date));
}
// Récupère le contenu complet (colonnes légères, jamais blocksData/rows/cellBorders -- voir
// fetchCahierEntryEditData plus bas) d'UN SEUL jour. Appelée au dépli d'une section de
// l'accordéon, ou pour la vue prof filtrée sur une date précise.
async function fetchCahierEntriesForDate(date){
  if(!cahierClasseId()) return null;
  const { data, error } = await cahierFiltre(sb.from('cahier_entries').select(CAHIER_COLS_LEGERES).eq('class_id', cahierClasseId())).eq('date', date).order('ordre', {ascending:true, nullsFirst:false}).order('created_at', {ascending:true});
  if(error){ console.error('fetch entries for date failed', error); return null; }
  return data;
}
// Chargement complet (toutes les dates, tout le contenu léger) -- réservé à "Afficher tout
// l'historique" (profs/admins) et au filtrage explicite par période (Du/Au), qui bornent alors
// la requête via fromDate/toDate plutôt que de tout charger sans distinction.
async function syncFetchAll(fromDate, toDate){
  if(!cahierClasseId()) return null;
  // Exclut les brouillons (date NULL) -- voir le commentaire de fetchCahierDatesList.
  let q = cahierFiltre(sb.from('cahier_entries').select(CAHIER_COLS_LEGERES).eq('class_id', cahierClasseId())).not('date', 'is', null);
  if(fromDate) q = q.gte('date', fromDate);
  if(toDate) q = q.lte('date', toDate);
  const { data, error } = await q.order('ordre', {ascending:true, nullsFirst:false}).order('date').order('created_at', {ascending:true});
  if(error){ console.error('sync fetch failed', error); return null; }
  return data;
}
// Récupère à la demande les colonnes lourdes d'UNE seule entrée (édition/réouverture d'un
// bloc), non chargées par syncFetchAll() -- voir son commentaire.
async function fetchCahierEntryEditData(id){
  const { data, error } = await sb.from('cahier_entries').select('blocksData,rows,cellBorders').eq('id', id).single();
  if(error){ console.error('fetch entry edit data failed', error); return null; }
  return data;
}
// Liste des brouillons (date NULL) de la classe active -- signalé : "un bouton brouillons...
// un autre bouton permet de récupérer un brouillon existant". Colonnes légères seulement (comme
// syncFetchAll) : les colonnes lourdes (blocksData/rows/cellBorders) sont chargées à la demande
// par editCahierEntry au moment où le brouillon choisi est effectivement rouvert.
async function fetchCahierBrouillons(){
  if(!cahierClasseId()) return [];
  const { data, error } = await cahierFiltre(sb.from('cahier_entries').select(CAHIER_COLS_LEGERES).eq('class_id', cahierClasseId())).is('date', null).order('created_at', {ascending:false});
  if(error){ console.error('fetch brouillons failed', error); return []; }
  return data;
}
async function syncAddEntry(entry){
  if(!cahierClasseId()) return {ok:false, offline:true};
  const { teacher_id: _auteur, ...propre } = entry; // l'auteur est rempli par la base (professeur connecté)
  const { data, error } = await sb.from('cahier_entries').insert({ ...propre, matiere: entry.matiere || cahierMatiere(), class_id: cahierClasseId() }).select().single();
  if(error) return {ok:false, error: error.message.includes('row-level security') ? "vous n'êtes pas assigné à cette classe." : error.message};
  return {ok:true, id:data.id};
}
// Vraie mise à jour (UPDATE), plutôt que le motif supprimer+réinsérer utilisé jusqu'ici pour
// une modification -- ce dernier créait une NOUVELLE ligne à chaque édition, perdant la
// position implicite en base des entrées n'ayant jamais eu d'ordre manuel explicite (celles
// où ordre reste NULL, triées alors par un critère d'égalité non garanti -- en pratique,
// l'ordre d'insertion). Résultat : toute entrée éditée finissait en fin de liste. Signalé :
// "quand on modifie un exercice, il se met en queue d'exercices et ne reste pas à sa place."
async function syncUpdateEntry(id, entry){
  if(!id) return {ok:false, offline:true};
  const { id: _omit, teacher_id: _auteur, ...payload } = entry; // l'auteur ne change pas ; id déjà ciblé via .eq ci-dessous, inutile (et
                                            // redondant) de le renvoyer dans le contenu
  const { error } = await sb.from('cahier_entries').update(payload).eq('id', id);
  if(error) return {ok:false, error: error.message.includes('row-level security') ? "vous n'êtes pas assigné à cette classe." : error.message};
  return {ok:true, id};
}
async function syncRemoveEntry(id){
  if(!id) return {ok:false, offline:true};
  const { error } = await sb.from('cahier_entries').delete().eq('id', id);
  if(error) return {ok:false, error: error.message};
  return {ok:true};
}
// Persiste un nouvel ordre manuel pour une entrée -- demandé : "permettre au prof de modifier
// l'ordre des exercices corrigés". Silencieux en cas d'échec (l'ordre reste correct
// localement/dans cette session ; une resynchronisation ultérieure le retentera).
async function syncUpdateEntryOrdre(id, ordre){
  if(!id) return {ok:false, offline:true};
  const { error } = await sb.from('cahier_entries').update({ordre}).eq('id', id);
  if(error) return {ok:false, error: error.message};
  return {ok:true};
}

/* ================= CÔTÉ ÉLÈVE : classes ================= */
async function loadMyStudentClasses(){
  if(!currentUser) return;
  const { data, error } = await sb.from('class_students').select('classes(id,nom,niveau,groupe,archive,cahier)').eq('student_id', currentUser.id);
  // Sa classe d'abord (classe active par défaut), puis ses groupes de remédiation.
  const classesList = (data||[]).map(row=>row.classes).filter(Boolean).sort((a,b)=>!!a.groupe - !!b.groupe);
  populateAccountClassList(classesList);
  if(!currentClassId || !accountClassesList.some(c=>c.id===currentClassId)){
    currentClassId = classesList[0] ? classesList[0].id : null;
  }
  await applyClassSelection();
  if(error) console.error(error);
}

/* ======================= CAHIER DE CORRECTIONS (persisté, groupé par jour) ======================= */
function loadCahier(){
  try{ const raw=localStorage.getItem('mathcollege_cahier'); return raw?JSON.parse(raw):[]; }
  catch(e){ return []; }
}
function saveCahier(){
  try{ localStorage.setItem('mathcollege_cahier', JSON.stringify(cahier)); }catch(e){ /* stockage indisponible dans ce contexte */ }
}
let cahier = loadCahier();
let editingEntryClassId = null; // classe active au moment où la modification a commencé
let editingEntryId = null; // id STABLE (pas un index de tableau -- un index capturé au clic
                            // sur "Modifier" peut devenir invalide si `cahier` est retrié avant
                            // le clic sur "Enregistrer", menant à écraser la MAUVAISE entrée)
function sortCahierInPlace(){
  // Trie par "ordre" manuel s'il est défini (undefined/null placés en dernier, via Infinity),
  // avec la date puis le chapitre en repli/départage -- rétrocompatible : tant qu'aucun ordre
  // n'a jamais été fixé, le tri reste identique à avant (chronologique). Le chapitre en 2e
  // critère garantit que les entrées d'une même date restent bien groupées par chapitre,
  // cohérent avec le regroupement visuel (groupedEntriesHTML) -- évite un même en-tête de
  // date dédoublé si des chapitres différents étaient mélangés au sein d'un même jour.
  // Signalé ensuite : "Je ne peux pas faire remonter une interrogation sur un même jour dans le
  // cahier. Les blocs semblent figer" -- un bloc ajouté après un premier réordonnancement (ordre
  // NULL) partait en fin de liste, TOUTES dates confondues, et y retournait à chaque tri. La date
  // passe donc en premier : l'ordre manuel ne départage que les blocs d'un même jour (c'est le
  // seul déplacement permis), un bloc sans ordre se place en fin de sa journée.
  cahier.sort((a,b)=>{
    const dateCmp = (a.date||'').localeCompare(b.date||'');
    if(dateCmp!==0) return dateCmp;
    const oa = (a.ordre==null) ? Infinity : a.ordre;
    const ob = (b.ordre==null) ? Infinity : b.ordre;
    if(oa!==ob) return oa-ob;
    const chapCmp = (a.chapitre||'').localeCompare(b.chapitre||'');
    if(chapCmp!==0) return chapCmp;
    return (a.created_at||'').localeCompare(b.created_at||'');
  });
}

// Mutualisation entre profs d'un même établissement (UAI) : liste, À LA DEMANDE (bouton), tout
// ce qu'un collègue a déjà corrigé sur le niveau+chapitre en cours -- remplace une première
// version par correspondance EXACTE sur la référence d'exercice, qui s'est révélée peu fiable
// en pratique (signalé : "j'ai essayé sans succès" -- confirmé aussi sur des données réelles :
// même un seul et même prof note ses références de façon incohérente d'une entrée à l'autre,
// ex. "TD 7 page 7" / "TD ex 7 page 7" / "TD exercice 1 page 7"). Une liste à parcourir
// visuellement n'a plus ce problème.
let sharedCorrectionsList = [];
async function openSharedCorrectionsModal(){
  const overlay = document.getElementById('sharedCorrectionsModalOverlay');
  const body = document.getElementById('sharedCorrectionsModalBody');
  if(!isSyncEnabled() || !currentClassId){ await niceAlert("Sélectionnez d'abord une classe active."); return; }
  const niveau = document.getElementById('corNiveau').value;
  const chapitre = document.getElementById('corChapitre').value;
  if(!chapitre){ await niceAlert("Choisissez d'abord un chapitre."); return; }
  overlay.style.display = 'flex';
  body.innerHTML = '<p class="hint">Chargement…</p>';
  const { data, error } = await sb.rpc('list_shared_corrections', {
    p_class_id: currentClassId, p_niveau: niveau, p_chapitre: chapitre,
  });
  if(error){ body.innerHTML = '<p class="hint">Erreur : '+escapeHtml(error.message)+'</p>'; return; }
  sharedCorrectionsList = data||[];
  if(!sharedCorrectionsList.length){ body.innerHTML = '<p class="hint">Aucune correction d\'un collègue trouvée pour ce chapitre, dans votre établissement.</p>'; return; }
  body.innerHTML = sharedCorrectionsList.map((m,i)=>{
    const dateStr = m.entry_date ? new Date(m.entry_date).toLocaleDateString('fr-FR') : '';
    const refLabel = m.exo==='Cours' ? 'Cours' : (m.exo==='TD' ? 'Manuel' : ('Exercice '+m.exo));
    return `<div style="border:1px solid rgba(28,43,57,.12);border-radius:10px;padding:10px 14px;margin-bottom:8px;display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap;">
      <div>
        <div style="font-weight:600;">${escapeHtml(refLabel)}${m.titre?' : '+escapeHtml(m.titre):''}</div>
        <div class="hint" style="margin:2px 0 0;"><span class=gicon style="font-size:.9em;vertical-align:-2px;">group</span> ${escapeHtml(m.prof_nom||'Collègue')} · ${escapeHtml(m.classe_nom||'')} · ${dateStr}</div>
      </div>
      <button type="button" class="btn secondary" style="padding:4px 10px;font-size:.78rem;flex:none;" onclick="reuseSharedCorrectionEntry(${i})">Réutiliser</button>
    </div>`;
  }).join('');
}
function closeSharedCorrectionsModal(){
  document.getElementById('sharedCorrectionsModalOverlay').style.display = 'none';
}
function reuseSharedCorrectionEntry(i){
  const match = sharedCorrectionsList[i];
  if(!match) return;
  document.getElementById('corExoNum').value = match.exo==='-'?'':match.exo;
  document.getElementById('corTitre').value = match.titre||'';
  const hasText = !!(match.raw && match.raw.trim());
  document.getElementById('correctionInput').value = match.raw||'';
  document.getElementById('correctionInputWrap').style.display = hasText ? 'block' : 'none';
  document.getElementById('btnCorAddTextarea').style.display = hasText ? 'none' : 'inline-flex';
  if(match.blocksData){
    blocksStores['global'] = JSON.parse(JSON.stringify(match.blocksData));
    corRows = match.rows ? JSON.parse(JSON.stringify(match.rows)) : [1];
    corCellBorders = match.cellBorders ? JSON.parse(JSON.stringify(match.cellBorders)) : {};
  } else if(match.figure){
    blocksStores['global'] = [{id: pendingBlockNextId++, type:'legacy', html: match.figure, data:null, editFn:null, row:0, col:0}];
    corRows = [1]; corCellBorders = {};
  }
  renderCorrectionPreview();
  closeSharedCorrectionsModal();
}
/* Vide le champ date pour préparer un brouillon -- signalé : "un bouton brouillons en effet qui
   annule la date par défaut". Rien d'autre à faire ici : addToCahier() enregistre déjà avec
   date:null dès que ce champ est vide, updateAddCahierButtonLabel() ajuste le libellé du bouton
   principal en conséquence. */
function startBrouillon(){
  document.getElementById('corDate').value = '';
  updateAddCahierButtonLabel();
  document.getElementById('correctionForm').scrollIntoView({behavior:'smooth', block:'start'});
}
/* Exclut les brouillons (date vide) d'un affichage normal du cahier -- ne doivent apparaître
   qu'au clic sur "Récupérer un brouillon" (openBrouillonPicker), jamais dans le cahier vu par
   les élèves ni dans la propre liste du prof juste après un ajout. */
function cahierDated(arr){ return (arr||[]).filter(e=>!!e.date); }
/* Petite fenêtre listant les brouillons de la classe active -- signalé : "un autre bouton permet
   de récupérer un brouillon existant". Colonnes légères seulement (voir fetchCahierBrouillons) ;
   le contenu détaillé se charge à la demande via editCahierEntry, comme pour une entrée datée
   normale. */
async function openBrouillonPicker(){
  if(!currentClassId){ niceAlert("Sélectionnez d'abord une classe active (boutons en haut de page)."); return; }
  const overlay = document.createElement('div');
  overlay.className = 'modal-overlay';
  overlay.id = 'brouillonPickerOverlay';
  overlay.innerHTML = `<div class="modal-card" style="max-width:480px;">
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px;">
      <strong style="font-family:'Space Grotesk',sans-serif;font-size:1.1rem;"><span class=gicon>bookmark</span> Brouillons</strong>
      <button class="modal-close" onclick="this.closest('.modal-overlay').remove()"><span class=gicon>close</span></button>
    </div>
    <div id="brouillonPickerList"><p class="hint">Chargement…</p></div>
  </div>`;
  document.body.appendChild(overlay);
  overlay.addEventListener('click', e=>{ if(e.target===overlay) overlay.remove(); });
  const list = await fetchCahierBrouillons();
  window._brouillonPickerList = list;
  const box = document.getElementById('brouillonPickerList');
  if(!box) return; // fenêtre déjà refermée entre-temps
  if(!list.length){ box.innerHTML = '<p class="hint">Aucun brouillon pour cette classe.</p>'; return; }
  box.innerHTML = list.map((e,i)=>`
    <div style="display:flex;justify-content:space-between;align-items:center;gap:8px;padding:8px 0;border-bottom:1px solid rgba(28,43,57,.06);">
      <span><b>${escapeHtml(e.titre||'(sans titre)')}</b><br><span class="hint" style="margin:0;">${escapeHtml(e.chapitre||'')}${e.exo && e.exo!=='-' ? ' · Exercice '+escapeHtml(e.exo) : ''}</span></span>
      <button class="btn secondary" style="font-size:.72rem;padding:4px 8px;" onclick="loadBrouillonEntry(${i})">Reprendre</button>
    </div>`).join('');
}
/* Charge un brouillon choisi dans l'éditeur -- le pousse d'abord dans `cahier` (il n'y est pas,
   la liste normale l'exclut, voir cahierDated) pour qu'editCahierEntry le retrouve normalement,
   ET pour qu'addToCahier reconnaisse ensuite la MÊME entrée (via editingEntryId) au moment de
   l'enregistrer -- une simple mise à jour de la ligne existante plutôt qu'un doublon, dès qu'une
   date est renseignée. */
function loadBrouillonEntry(i){
  const entry = (window._brouillonPickerList||[])[i];
  if(!entry) return;
  const overlay = document.getElementById('brouillonPickerOverlay');
  if(overlay) overlay.remove();
  cahier.push(entry);
  editCahierEntry(cahier.length-1);
}
async function addToCahier(){
  if(!currentClassId){ niceAlert("Sélectionnez d'abord une classe active (boutons en haut de page)."); return; }
  const textareaVisible = document.getElementById('correctionInputWrap').style.display !== 'none';
  const raw = textareaVisible ? document.getElementById('correctionInput').value.trim() : '';
  const figureHtml = blocksRowsHTML('global', corRows, false, corCellBorders);
  if(!raw && !(blocksStores['global']||[]).length) return; // rien à sauvegarder
  const entry = {
    niveau: document.getElementById('corNiveau').value,
    chapitre: document.getElementById('corChapitre').value,
    exo: document.getElementById('corExoNum').value || '-',
    titre: document.getElementById('corTitre').value.trim(),
    modalite: corModalite(),
    // Date vide = brouillon (voir startBrouillon) -- ne retombe PLUS sur aujourd'hui par défaut,
    // signalé : "un bouton brouillons... qui annule la date par défaut". Reste null tant que le
    // prof n'a pas explicitement choisi une date, plutôt que de silencieusement la fixer.
    date: document.getElementById('corDate').value || null,
    raw: raw,
    figure: figureHtml,
    blocksData: JSON.parse(JSON.stringify(blocksStores['global']||[])),
    rows: JSON.parse(JSON.stringify(corRows)),
    cellBorders: JSON.parse(JSON.stringify(corCellBorders)),
  };
  // Vue par semaine : le jour de l'exercice est chargé AVANT l'ajout local -- chargé après, il
  // ramènerait l'exercice une seconde fois (la copie locale n'a pas encore son id serveur).
  await corChargerJour(entry.date);
  let oldServerId = null, deplacement = false;
  if(editingEntryId!==null){
    // Classe active changée pendant la modification (signalé : « je me suis trompé de classe, je
    // clique sur modifier, je change la classe. Mais l'exercice se retrouve dans les deux
    // classes ») : c'est un DÉPLACEMENT de la même ligne, jamais un nouvel ajout.
    if(editingEntryClassId && editingEntryClassId!==currentClassId && editingEntryId){
      const de = (accountClassesList.find(c=>c.id===editingEntryClassId)||{}).label || 'l\'ancienne classe';
      const vers = (accountClassesList.find(c=>c.id===currentClassId)||{}).label || 'la classe active';
      if(!(await niceConfirm(`Déplacer cet exercice de ${escapeHtml(de)} vers ${escapeHtml(vers)} ?`))) return;
      deplacement = true;
    }
    if(deplacement) entry.ordre = null; // son rang manuel n'a pas de sens dans l'autre classe
    // Recherche fraîche de la position ACTUELLE de l'entrée éditée, par son id stable -- ne
    // JAMAIS faire confiance à un index capturé plus tôt (voir commentaire sur editingEntryId).
    const idx = cahier.findIndex(e=>e.id===editingEntryId);
    if(idx!==-1){
      oldServerId = cahier[idx].id || null;
      if(!deplacement) entry.ordre = cahier[idx].ordre; // reporte l'ordre manuel existant, sinon perdu à chaque
                                        // modification (l'entrée retombait tout en bas --
                                        // sortCahierInPlace place les entrées sans ordre en dernier)
      cahier[idx] = entry;
    } else {
      // L'entrée éditée n'est plus dans la liste chargée (autre classe affichée, rechargement) :
      // elle garde son id en base -- mise à jour de la MÊME ligne, pas un doublon.
      oldServerId = editingEntryId || null;
      cahier.push(entry);
    }
    editingEntryId = null; editingEntryClassId = null;
    updateAddCahierButtonLabel();
    document.getElementById('btnCancelEdit').style.display = 'none';
  } else {
    cahier.push(entry);
  }
  sortCahierInPlace();
  saveCahier();
  renderCahier();
  clearCorrectionInput();
  if(isSyncEnabled()){
    if(oldServerId){
      entry.id = oldServerId;
      const res = await syncUpdateEntry(oldServerId, deplacement ? {...entry, class_id: currentClassId} : entry);
      if(!res.ok && !res.offline){ await niceAlert("<span class=gicon>warning</span> Enregistré localement, mais échec de synchronisation avec le serveur : "+(res.error||'erreur inconnue')+". Vérifiez l'adresse du script et le code secret dans la configuration de synchronisation."); }
    } else {
      const res = await syncAddEntry(entry);
      if(res.ok){ entry.id = res.id; saveCahier(); renderCahier(); }
      else if(!res.offline){ await niceAlert("<span class=gicon>warning</span> Enregistré localement, mais échec de synchronisation avec le serveur : "+(res.error||'erreur inconnue')+". Vérifiez l'adresse du script et le code secret dans la configuration de synchronisation."); }
    }
  }
}
async function editCahierEntry(i){
  const e = cahier[i];
  document.getElementById('corNiveau').value = e.niveau;
  fillCorChapitres();
  document.getElementById('corChapitre').value = e.chapitre;
  document.getElementById('corExoNum').value = e.exo==='-'?'':e.exo;
  document.getElementById('corTitre').value = e.titre||'';
  corModalite(e.modalite||null);
  // Reste vide pour un brouillon (e.date null) -- ne retombe plus sur aujourd'hui, sinon
  // rouvrir un brouillon lui assignait silencieusement une date et le faisait sortir des
  // brouillons sans que le prof l'ait demandé.
  document.getElementById('corDate').value = e.date||'';
  const hasText = !!(e.raw && e.raw.trim());
  document.getElementById('correctionInput').value = e.raw||'';
  document.getElementById('correctionInputWrap').style.display = hasText ? 'block' : 'none';
  document.getElementById('btnCorAddTextarea').style.display = hasText ? 'none' : 'inline-flex';
  // blocksData/rows/cellBorders ne sont plus chargés par le fetch principal (voir
  // syncFetchAll) : on les récupère ici à la demande, uniquement à ce moment précis où ils
  // deviennent réellement utiles (modification effective de l'entrée).
  if(e.id && e.blocksData===undefined && isSyncEnabled()){
    const full = await fetchCahierEntryEditData(e.id);
    if(full){ e.blocksData = full.blocksData; e.rows = full.rows; e.cellBorders = full.cellBorders; }
  }
  if(e.blocksData){
    // Entrée enregistrée avec la structure des blocs (depuis ce correctif) : tout redevient
    // modifiable normalement (déplacer, éditer, supprimer bloc par bloc).
    blocksStores['global'] = JSON.parse(JSON.stringify(e.blocksData));
    corRows = e.rows ? JSON.parse(JSON.stringify(e.rows)) : [1];
    corCellBorders = e.cellBorders ? JSON.parse(JSON.stringify(e.cellBorders)) : {};
  } else if(e.figure){
    // Ancienne entrée, enregistrée avant ce correctif : seul le rendu final avait été gardé,
    // pas la structure -- affiché tel quel, mais non détaillable bloc par bloc.
    blocksStores['global'] = [{id: pendingBlockNextId++, type:'legacy', html: e.figure, data:null, editFn:null, row:0, col:0}];
    corRows = [1];
    corCellBorders = {};
  } else {
    blocksStores['global'] = [];
    corRows = [1];
    corCellBorders = {};
  }
  renderCorrectionPreview();
  editingEntryId = e.id;
  editingEntryClassId = currentClassId; // pour reconnaître un changement de classe avant l'enregistrement
  document.getElementById('btnAddCahier').innerHTML = '<span class=gicon>save</span> Enregistrer la modification';
  document.getElementById('btnCancelEdit').style.display = 'inline-block';
  document.getElementById('correctionForm').scrollIntoView({behavior:'smooth', block:'start'});
  document.getElementById('correctionInput').focus();
}
function cancelEditCahier(){
  editingEntryId = null; editingEntryClassId = null;
  updateAddCahierButtonLabel();
  document.getElementById('btnCancelEdit').style.display = 'none';
  clearCorrectionInput();
}
/* Modalité de l'exercice (outil de correction) : correction du travail maison, en classe entière ou en
   autonomie -- un seul choix, ou aucun. Gardée d'un exercice à l'autre (souvent la même pendant une séance). */
const COR_MODALITES = { maison: ['Correction du travail maison', 'home', '#8A4B08'], classe: ['En classe entière', 'groups', '#0C5BA0'], autonomie: ['En autonomie', 'person', '#2E7D32'] };
function corModalite(v){
  const cases = document.querySelectorAll('#corModalites input');
  if(v !== undefined){ cases.forEach(c=>{ c.checked = c.value===v; }); return v; }
  const c = [...cases].find(x=>x.checked); return c ? c.value : null;
}
function corChoisirModalite(el){ if(el.checked) document.querySelectorAll('#corModalites input').forEach(c=>{ if(c!==el) c.checked = false; }); }
function modaliteBadge(m){
  const d = COR_MODALITES[m]; if(!d) return '';
  return `<span class="nb-modalite" style="--c:${d[2]}"><span class="gicon">${d[1]}</span> ${d[0]}</span>`;
}
function clearCorrectionInput(){
  document.getElementById('correctionInput').value='';
  document.getElementById('corExoNum').value='';
  document.getElementById('corTitre').value='';
  blocksStores['global'] = [];
  corRows = [1];
  corCellBorders = {};
  if(corValidated) corToggleValidated();
  renderCorrectionPreview();
}

/* ================= CRÉER UNE ÉVALUATION : voir evaluation.js ================= */

async function removeCahierEntry(i){
  const entry = cahier[i];
  if(entry && editingEntryId===entry.id) cancelEditCahier();
  if(isSyncEnabled() && entry && entry.id){
    const res = await syncRemoveEntry(entry.id);
    if(!res.ok){ await niceAlert("Échec de la suppression sur le serveur : "+(res.error||'erreur inconnue')); return; }
  }
  cahier.splice(i,1); saveCahier(); renderCahier();
}
function clearCahier(btn){
  if(!cahier.length) return;
  if(btn && btn.dataset.armed!=='1'){
    btn.dataset.armed='1';
    const original = btn.textContent;
    btn.textContent = 'Confirmer ?';
    btn.style.background = 'rgba(211,90,60,.2)';
    setTimeout(()=>{ if(btn.isConnected){ btn.dataset.armed=''; btn.textContent=original; btn.style.background=''; } }, 2500);
    return;
  }
  cahier=[]; editingEntryId=null; saveCahier(); renderCahier();
}

function entryRowsHTML(e, idx, editable, showRemoveBtn){
  if(showRemoveBtn===undefined) showRemoveBtn = true; // rétrocompatible (accordéon élève)
  // exo==='' : entrée sans étiquette (ex. en-tête d'évaluation ajoutée au cahier), distinct de
  // '-' (déjà utilisé par l'outil de correction pour "numéro non renseigné", qui affiche encore
  // "Exercice -").
  const refLabel = e.exo==='' ? '' : e.exo==='Cours' ? 'Cours' : e.exo==='Interrogation' ? 'Interrogation' : (e.exo==='Questions flash' || e.exo==='Séance en direct') ? 'Questions flash' : (e.exo==='TD' ? 'Manuel' : ('Exercice '+e.exo)); // Interrogation : questionnaires-cahier.js
  // Vignettes de modalité cliquables (professeur, exercices seulement) -- demandé : « changer le type de
  // correction sans les rééditer, juste par des vignettes cliquables dans le bilan en dessous ».
  const modEditable = editable && !['', 'Cours', 'Interrogation', 'Questions flash', 'Séance en direct'].includes(e.exo);
  let html = `<div class="cahier-print-entry"><div class="nb-ref-row"><div class="nb-ref">${refLabel}${e.titre?' : '+escapeHtml(e.titre):''}${e.modalite && !modEditable ? ' '+modaliteBadge(e.modalite) : ''}</div>`;
  if(editable){
    // Le déplacement ne peut se faire QU'À L'INTÉRIEUR du même groupe (même date + même
    // chapitre) -- au-delà, ça mélangerait des exercices de jours différents et casserait le
    // regroupement affiché par date. Signalé : "ça les met dans des ordres incompréhensibles".
    const prev = cahier[idx-1];
    const next = cahier[idx+1];
    const sameGroup = (a,b) => a && b && (a.date||'')===(b.date||''); // même jour, même si le chapitre diffère (ex. une interrogation)
    const canUp = sameGroup(e, prev);
    const canDown = sameGroup(e, next);
    html += `<span style="display:flex;gap:4px;align-items:center;">
      <span class="nb-date-picker" title="Changer la date de cette entrée (${fmtDateFR(e.date)}) -- sans toucher à son contenu">
        <span class=gicon onclick="this.nextElementSibling.showPicker()">calendar_month</span>
        <input type="date" value="${e.date||''}" onchange="changeCahierEntryDate(${idx}, this.value)"/>
      </span>
      <button type="button" class="nb-remove-btn" onclick="moveCahierEntry(${idx},-1)" title="Monter (dans le même jour)" ${canUp?'':'disabled'}><span class=gicon>arrow_upward</span></button>
      <button type="button" class="nb-remove-btn" onclick="moveCahierEntry(${idx},1)" title="Descendre (dans le même jour)" ${canDown?'':'disabled'}><span class=gicon>arrow_downward</span></button>
      ${showRemoveBtn ? `<button type="button" class="nb-remove-btn" onclick="removeCahierEntryFromNotebook(${idx}, this)" title="Retirer ce bloc du cahier"><span class=gicon>close</span> Retirer</button>` : ''}
    </span>`;
  }
  html += `</div>`;
  if(modEditable) html += `<div class="nb-mod-choix">${Object.entries(COR_MODALITES).map(([k, d])=>`<button type="button" class="nb-mod-chip${e.modalite===k ? ' on' : ''}" style="--c:${d[2]}" onclick="changeCahierEntryModalite(${idx}, '${k}')" title="${e.modalite===k ? 'Retirer' : 'Marquer'} : ${d[0]}"><span class="gicon">${d[1]}</span> ${d[0]}</button>`).join('')}</div>`;
  // Partie de cours : lien direct vers le chapitre (sauf dans l'impression, où idx n'est pas donné).
  if(e.exo==='Cours' && e.chapitre && idx!==undefined && cahierChapitreDe(e)) html += `<button type="button" class="nb-cours-lien" onclick="cahierOuvrirCours(${idx})" title="Ouvrir ce chapitre à l'onglet Cours"><span class=gicon>menu_book</span> Revoir dans le cours</button><button type="button" class="nb-cours-lien nb-vivant-btn" onclick="cahierVivant(${idx}, this)" title="Animations, démos pas à pas et figures manipulables, ici même dans le cahier"><span class=gicon>play_circle</span> Interactif</button>`;
  html += `<div class="nb-body">${e.html!=null ? e.html : renderMathText(e.raw)}</div>`;
  if(e.figure) html += `<div class="nb-figure-row">${e.figure}</div>`;
  html += `</div>`;
  return html;
}
// Change UNIQUEMENT la date d'une entrée (Cours ou exercice), sans toucher à son contenu --
// volontairement séparée de editCahierEntry/addToCahier (qui reconstruisent le contenu depuis
// les blocs de correction, risqué pour un Cours qui n'a pas cette structure). Demandé :
// "permettre de modifier la date pour le cours et les exercices déjà posés".
// Change UNIQUEMENT la modalité (travail maison / classe entière / autonomie) ; re-cliquer la vignette active la retire.
async function changeCahierEntryModalite(idx, m){
  const e = cahier[idx]; if(!e) return;
  const avant = e.modalite || null, apres = avant===m ? null : m;
  e.modalite = apres; saveCahier(); renderCahier();
  if(isSyncEnabled() && e.id){
    const res = await syncUpdateEntry(e.id, {modalite: apres});
    if(!res.ok && !res.offline){
      e.modalite = avant; saveCahier(); renderCahier();
      await niceAlert("<span class=gicon>warning</span> Échec de la synchronisation avec le serveur : "+(res.error||'erreur inconnue')+". Le type de correction n'a pas été changé.");
    }
  }
}
async function changeCahierEntryDate(idx, newDate){
  const e = cahier[idx];
  if(!e || !newDate || e.date===newDate) return;
  const oldDate = e.date;
  e.date = newDate;
  sortCahierInPlace();
  saveCahier();
  renderCahier();
  if(document.getElementById('cahierEleveContent')) renderCahierEleveLocal();
  if(isSyncEnabled() && e.id){
    const res = await syncUpdateEntry(e.id, {date:newDate});
    if(res.ok){
      // Maintient le squelette de l'accordéon paresseux à jour SANS tout recharger (perdrait
      // les autres jours déjà dépliés) : décrémente/retire l'ancienne date, ajoute/incrémente
      // la nouvelle -- et considère cette dernière comme "chargée" puisqu'on a déjà son
      // contenu. Fait seulement ici, après confirmation du succès, pour ne jamais laisser le
      // squelette dans un état incohérent si la synchronisation échoue et que la date est
      // annulée localement (voir plus bas).
      if(cahierDatesList && cahierDatesList.length){
        const oldGrp = cahierDatesList.find(g=>g.date===oldDate);
        if(oldGrp){ oldGrp.count--; if(oldGrp.count<=0) cahierDatesList = cahierDatesList.filter(g=>g.date!==oldDate); }
        const newGrp = cahierDatesList.find(g=>g.date===newDate);
        if(newGrp) newGrp.count++; else cahierDatesList.push({date:newDate, count:1});
        cahierDatesList.sort((a,b)=>a.date.localeCompare(b.date));
        if(cahierLoadedDates) cahierLoadedDates.add(newDate);
        if(document.getElementById('cahierEleveContent')) renderCahierEleveLocal();
      }
    } else if(!res.offline){
      e.date = oldDate; // annule localement si la synchronisation a échoué, pour ne pas
                         // laisser croire que le changement a été enregistré
      sortCahierInPlace();
      saveCahier();
      renderCahier();
      if(document.getElementById('cahierEleveContent')) renderCahierEleveLocal();
      await niceAlert("<span class=gicon>warning</span> Échec de la synchronisation avec le serveur : "+(res.error||'erreur inconnue')+". La date n'a pas été changée.");
    }
  }
}
// Déplace une entrée du cahier vers le haut (-1) ou le bas (+1) -- demandé : "permettre au
// prof de modifier l'ordre des exercices corrigés". Fixe un ordre manuel explicite sur TOUTES
// les entrées dès le premier déplacement (nécessaire tant qu'elles n'en ont pas encore un --
// rétrocompatibilité, voir sortCahierInPlace), pour que le nouvel ordre reste stable même
// après une resynchronisation ultérieure.
async function moveCahierEntry(idx, direction){
  const otherIdx = idx+direction;
  if(otherIdx<0 || otherIdx>=cahier.length) return;
  // Défense en profondeur (déjà vérifié à l'affichage du bouton, voir entryRowsHTML) :
  // n'échange jamais 2 entrées de groupes différents (même date + même chapitre requis) --
  // sinon le regroupement par date affiché se retrouve cassé.
  const a = cahier[idx], b = cahier[otherIdx];
  if((a.date||'')!==(b.date||'')) return; // déplacement dans la même journée seulement (chapitres différents permis)
  // Numérote TOUS les blocs de cette journée dans l'ordre affiché avant l'échange : un bloc sans
  // ordre (ajouté plus tard) reprenait sinon sa place en fin de journée au tri suivant.
  const jour = a.date||'', modifies = new Set();
  cahier.forEach((e,i)=>{ if((e.date||'')===jour && e.ordre!==i){ e.ordre = i; modifies.add(e); } });
  const tmp = cahier[idx].ordre;
  cahier[idx].ordre = cahier[otherIdx].ordre;
  cahier[otherIdx].ordre = tmp;
  modifies.add(cahier[idx]); modifies.add(cahier[otherIdx]);
  [cahier[idx], cahier[otherIdx]] = [cahier[otherIdx], cahier[idx]];
  saveCahier();
  // Réaffiche IMMÉDIATEMENT depuis le tableau local (déjà à jour, pas besoin de resynchroniser
  // depuis le serveur) -- corrige "à chaque fois la page se recharge et tout se mélange", qui
  // venait d'une re-synchronisation (renderCahierEleve) écrasant ce changement local par
  // d'anciennes données avant que la sauvegarde serveur n'ait eu le temps de se terminer.
  nbAccJour = jour; // le jour de l'exercice déplacé reste ouvert, à la même hauteur de page
  const y = window.scrollY, book = document.getElementById('cahierEleveBook'), yBook = book ? book.scrollTop : 0;
  renderCahierEleveLocal();
  if(document.getElementById('cahierList')) renderCahier();
  window.scrollTo(0, y);
  // renderCahierEleveLocal descend le cahier tout en bas (image suivante) : on le remet où il était.
  requestAnimationFrame(()=>{ if(book) book.scrollTop = yBook; window.scrollTo(0, y); });
  if(isSyncEnabled()){
    // Sauvegarde serveur désormais ATTENDUE (jamais "tirée et oubliée") -- garantit qu'elle
    // est bien terminée avant toute resynchronisation future (ex. prochaine ouverture du
    // cahier), qui renverrait sinon encore l'ancien ordre.
    for(const e of modifies){ if(e.id) await syncUpdateEntryOrdre(e.id, e.ordre); }
  }
}
/* Regroupe par date + chapitre. Le chapitre s'affiche en "pied" de chaque groupe (aligné à
   droite), plutôt qu'en haut à côté de la date -- un vrai pied de PAGE physique n'est pas
   possible en HTML/CSS standard pour du contenu qui varie (la coupure des pages n'est connue
   qu'à l'impression), ceci en est l'équivalent le plus proche réalisable. */
function groupedEntriesHTML(entries, renderItem, dateExtra){
  let html=''; let lastKey=null; let currentChapitre=''; let lastDate=null;
  entries.forEach((e,i)=>{
    const key = (e.date||'')+'|'+(e.chapitre||'');
    if(key!==lastKey){
      if(lastKey!==null){ html += `<div class="nb-page-footer">${escapeHtml(currentChapitre)}</div><hr class="nb-daysep">`; }
      // La date n'est répétée qu'au changement de jour (plusieurs chapitres le même jour, ex. une interrogation).
      if((e.date||'')!==lastDate) html+=`<div class="nb-date-row"><div class="nb-date">${fmtDateFR(e.date)}</div>${dateExtra && e.date ? dateExtra(e.date) : ''}</div>`;
      lastDate = e.date||'';
      lastKey=key;
      currentChapitre = e.chapitre||'';
    }
    html+=renderItem(e,i);
  });
  if(lastKey!==null) html += `<div class="nb-page-footer">${escapeHtml(currentChapitre)}</div>`;
  return html;
}
/* Variante SANS l'en-tête de date répété (utilisée à l'intérieur d'une section d'accordéon,
   où la date est déjà affichée une fois dans l'en-tête cliquable) -- regroupe seulement par
   chapitre au sein d'une même date. */
function groupedByChapitreHTML(entries, renderItem){
  let html=''; let lastChapitre=null;
  entries.forEach((e,i)=>{
    const chap = e.chapitre||'';
    if(chap!==lastChapitre){
      if(lastChapitre!==null) html += `<div class="nb-page-footer">${escapeHtml(lastChapitre)}</div><hr class="nb-daysep">`;
      lastChapitre = chap;
    }
    html+=renderItem(e,i);
  });
  if(lastChapitre!==null) html += `<div class="nb-page-footer">${escapeHtml(lastChapitre)}</div>`;
  return html;
}
/* Regroupe les entrées en blocs accordéon PAR DATE -- demandé : "faire des blocs accordéon par
   date" (alternative à un simple agrandissement de la hauteur, plus utile à mesure que le
   cahier se remplit sur toute une année). Section la plus récente ouverte par défaut, les
   autres repliées. */
/* Demandé : « quand on ouvre un accordéon peut-on fermer les autres directement ? Et rester sur le même
   accordéon quand on déplace un exercice (monter ou descendre) ». Un seul jour ouvert à la fois ; le jour
   ouvert est mémorisé (nbAccJour) et reste ouvert quand le cahier se réaffiche. null : jour le plus récent
   (par défaut) ; '' : tout replié. */
let nbAccJour = null;
function nbAccEstOuvert(date, idx, dernier, dates){
  if(nbAccJour === '') return false;
  if(nbAccJour && dates.includes(nbAccJour)) return date === nbAccJour;
  return idx === dernier;
}
// Ferme tous les autres jours de la même liste.
function nbAccFermerAutres(body){
  const liste = body.closest('.nb-accordion-section') && body.closest('.nb-accordion-section').parentElement;
  if(!liste) return;
  liste.querySelectorAll(':scope > .nb-accordion-section > .nb-accordion-body.open').forEach(b=>{
    if(b === body) return;
    b.classList.remove('open');
    const ch = b.previousElementSibling && b.previousElementSibling.querySelector('.nb-accordion-chevron');
    if(ch) ch.classList.remove('open');
  });
}
/* Repère d'Oliv'IA sur les jours du cahier qui contiennent du cours -- demandé : « au niveau des dates du
   cahier de l'élève, mettre un repère avec Oliv'IA sur les jours qui contiennent des séances de cours ».
   Élément vide dessiné en CSS (olivia-deco.js) : rien à l'impression ni dans les PDF. */
function nbOlivCours(oui){ return oui ? '<span class="nb-oliv-cours" title="Ce jour-là, il y a du cours à revoir" aria-label="Jour de cours"></span>' : ''; }
function groupedEntriesAccordionHTML(entries, renderItem){
  const dateGroups = [];
  entries.forEach(e=>{
    const d = e.date||'';
    let grp = dateGroups.find(g=>g.date===d);
    if(!grp){ grp = {date:d, entries:[]}; dateGroups.push(grp); }
    grp.entries.push(e);
  });
  const mostRecentIdx = dateGroups.length-1, dates = dateGroups.map(g=>g.date);
  return dateGroups.map((grp, idx)=>{
    const isOpen = nbAccEstOuvert(grp.date, idx, mostRecentIdx, dates);
    const accId = 'nbacc-'+idx;
    const inner = groupedByChapitreHTML(grp.entries, renderItem);
    return `<div class="nb-accordion-section">
      <div class="nb-accordion-header" role="button" tabindex="0" onclick="toggleNbAccordion('${accId}','${grp.date}')" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();toggleNbAccordion('${accId}','${grp.date}');}">
        <span class="gicon nb-accordion-chevron${isOpen?' open':''}">expand_more</span>
        <span>${fmtDateFR(grp.date)}</span>${nbOlivCours(grp.entries.some(e=>e.exo==='Cours'))}
        <span class="nb-accordion-count">(${grp.entries.length})</span>
        <button type="button" class="nb-pdf-day-btn" onclick="event.stopPropagation(); exportCahierDayAsPDF('${grp.date}')" title="Générer un PDF de ce jour"><span class=gicon>picture_as_pdf</span></button>
        ${nbResumeDayBtn(grp.date)}
      </div>
      <div class="nb-accordion-body${isOpen?' open':''}" id="${accId}">${inner}</div>
    </div>`;
  }).join('');
}
function toggleNbAccordion(id, date){
  const body = document.getElementById(id);
  const isOpen = body.classList.toggle('open');
  if(isOpen) nbAccFermerAutres(body);
  nbAccJour = isOpen ? (date||null) : '';
  const chevron = body.previousElementSibling.querySelector('.nb-accordion-chevron');
  chevron.classList.toggle('open', isOpen);
}
// Variante PARESSEUSE de l'accordéon (mode par défaut du cahier) : construit le squelette à
// partir de cahierDatesList (juste des dates + comptes, léger) plutôt que d'entrées déjà
// chargées -- le contenu réel d'un jour n'est récupéré qu'à son dépli, voir expandCahierDay.
function lazyGroupedEntriesAccordionHTML(editable){
  cahierEditableMode = editable;
  const mostRecentIdx = cahierDatesList.length-1;
  // Jour mémorisé : seulement s'il est déjà chargé (sinon, rien ne lancerait son chargement).
  const dates = cahierDatesList.map(g=>g.date).filter(d=>d!==nbAccJour || cahierLoadedDates.has(d));
  return cahierDatesList.map((grp, idx)=>{
    const isOpen = nbAccEstOuvert(grp.date, idx, mostRecentIdx, dates);
    const accId = 'nbacc-'+idx;
    const loaded = cahierLoadedDates.has(grp.date);
    const inner = loaded
      ? groupedByChapitreHTML(cahier.filter(e=>e.date===grp.date), (e)=>entryRowsHTML(e, cahier.indexOf(e), editable))
      : (isOpen ? '<p class="hint" style="padding:8px;">Chargement…</p>' : '');
    return `<div class="nb-accordion-section">
      <div class="nb-accordion-header" role="button" tabindex="0" onclick="expandCahierDay('${accId}','${grp.date}')" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();expandCahierDay('${accId}','${grp.date}');}">
        <span class="gicon nb-accordion-chevron${isOpen?' open':''}">expand_more</span>
        <span>${fmtDateFR(grp.date)}</span>${nbOlivCours(grp.cours || (cahierLoadedDates.has(grp.date) && cahier.some(e=>e.date===grp.date && e.exo==='Cours')))}
        <span class="nb-accordion-count">(${grp.count})</span>
        <button type="button" class="nb-pdf-day-btn" onclick="event.stopPropagation(); exportCahierDayAsPDF('${grp.date}')" title="Générer un PDF de ce jour"><span class=gicon>picture_as_pdf</span></button>
        ${nbResumeDayBtn(grp.date)}
      </div>
      <div class="nb-accordion-body${isOpen?' open':''}" id="${accId}">${inner}</div>
    </div>`;
  }).join('');
}
// Dépli/repli d'un jour de l'accordéon paresseux : si son contenu n'a encore jamais été
// chargé, va le chercher en base (une seule requête, un seul jour) avant de l'afficher ; les
// dépliages suivants du même jour réutilisent ce qui est déjà en mémoire, sans re-requêter.
async function expandCahierDay(accId, date){
  const body = document.getElementById(accId);
  const chevron = body.previousElementSibling.querySelector('.nb-accordion-chevron');
  if(body.classList.contains('open')){
    body.classList.remove('open');
    chevron.classList.remove('open');
    nbAccJour = '';
    return;
  }
  body.classList.add('open');
  chevron.classList.add('open');
  nbAccFermerAutres(body);
  nbAccJour = date;
  if(!cahierLoadedDates.has(date)){
    body.innerHTML = '<p class="hint" style="padding:8px;">Chargement…</p>';
    const entries = await fetchCahierEntriesForDate(date);
    if(entries){
      const existingIds = new Set(cahier.map(e=>e.id));
      entries.forEach(e=>{ if(!existingIds.has(e.id)) cahier.push(e); });
      sortCahierInPlace(); // l'ordre du tableau ne doit jamais dépendre de l'ordre de
                            // CHARGEMENT (par jour ici) -- voir le commentaire similaire dans
                            // applyCorListFilter
      cahierLoadedDates.add(date);
      saveCahier();
    } else {
      body.innerHTML = '<p class="hint" style="padding:8px;"><span class=gicon>warning</span> Échec du chargement, réessayez.</p>';
      body.classList.remove('open');
      chevron.classList.remove('open');
      return;
    }
  }
  body.innerHTML = groupedByChapitreHTML(cahier.filter(e=>e.date===date), (e)=>entryRowsHTML(e, cahier.indexOf(e), cahierEditableMode));
}
/* Bas de la page Correction : le cahier par semaine, comme le cahier élève -- demandé : « Sur la
   partie basse, présenter le cahier comme dans cahier élève ». Vignettes des jours de la semaine,
   semaine précédente / suivante ; le jour déplié montre ses exercices avec Modifier / Retirer et le
   résumé pour le cahier de textes. Le champ date permet d'aller directement à une semaine. */
function corCahierCompte(){
  const c = document.getElementById('cahierCount'); if(!c) return;
  const n = currentClassId ? nbJours().reduce((t, j)=>t + j.count, 0) : 0;
  c.textContent = n + ' élément' + (n>1 ? 's' : '');
}
function renderCahier(){
  const list = document.getElementById('cahierList'); if(!list) return;
  const status = document.getElementById('corListFilterStatus'); if(status) status.textContent = '';
  if(!currentClassId){ list.innerHTML = '<div class="placeholder-box">Choisissez une classe ci-dessus pour voir et ajouter des corrections.</div>'; corCahierCompte(); return; }
  if(!document.getElementById('corSemaine')) list.innerHTML = '<div id="corSemaine"></div>';
  corCahierCompte();
  nbSemaineRendre('cor');
}
// Charge un jour du cahier (avant d'y ajouter un exercice localement) et ouvre sa semaine en bas de page.
async function corChargerJour(date){
  if(!date) return;
  if(isSyncEnabled() && !cahierLoadedDates.has(date)){
    const du = await fetchCahierEntriesForDate(date);
    if(du){ const ids = new Set(cahier.map(e=>e.id)); du.forEach(e=>{ if(!ids.has(e.id)) cahier.push(e); }); cahierLoadedDates.add(date); }
  }
  Object.assign(nbSemSt.cor, { classe: currentClassId, lundi: nbLundi(date), jour: date });
}
function corAllerDate(){
  const inp = document.getElementById('corListFilterDate'), d = inp && inp.value, status = document.getElementById('corListFilterStatus');
  if(!d || !currentClassId) return;
  const lundi = nbLundi(d), jours = nbJours();
  if(!jours.some(j=>nbLundi(j.date)===lundi)){ if(status) status.textContent = 'Aucune correction cette semaine-là.'; return; }
  if(status) status.textContent = '';
  Object.assign(nbSemSt.cor, { classe: currentClassId, lundi, jour: jours.some(j=>j.date===d) ? d : null });
  nbSemaineRendre('cor');
}
let cahierFilterFrom = null, cahierFilterTo = null;
let cahierFilterChapitre = '';
function filteredCahier(){
  if(!cahierFilterFrom && !cahierFilterTo && !cahierFilterChapitre) return cahier;
  return cahier.filter(e=>{
    if(cahierFilterFrom && (e.date||'') < cahierFilterFrom) return false;
    if(cahierFilterTo && (e.date||'') > cahierFilterTo) return false;
    if(cahierFilterChapitre && e.chapitre!==cahierFilterChapitre) return false;
    return true;
  });
}
function populateCahierChapitreFilter(){
  const sel = document.getElementById('cahierFilterChapitre');
  if(!sel) return;
  const current = sel.value;
  const chapitres = Array.from(new Set(cahier.map(e=>e.chapitre).filter(Boolean))).sort();
  sel.innerHTML = '<option value="">Tous</option>' + chapitres.map(c=>`<option value="${escapeHtml(c)}">${escapeHtml(c)}</option>`).join('');
  if(chapitres.includes(current)) sel.value = current;
}
function applyCahierFilter(){
  cahierFilterFrom = document.getElementById('cahierFilterFrom').value || null;
  cahierFilterTo = document.getElementById('cahierFilterTo').value || null;
  cahierFilterChapitre = document.getElementById('cahierFilterChapitre').value || '';
  renderCahierEleve();
}
function clearCahierFilter(){
  cahierFilterFrom = null; cahierFilterTo = null; cahierFilterChapitre = '';
  document.getElementById('cahierFilterFrom').value = '';
  document.getElementById('cahierFilterTo').value = '';
  const sel = document.getElementById('cahierFilterChapitre'); if(sel) sel.value = '';
  renderCahierEleve();
}
// Bouton "Afficher tout l'historique", réservé profs/admins -- par défaut, le cahier charge
// paresseusement jour par jour au dépli de l'accordéon (voir lazyGroupedEntriesAccordionHTML).
// Ce bouton permet de charger explicitement tout l'historique en une fois quand on en a besoin
// (ex. retrouver une correction ancienne sans naviguer jour par jour).
function toggleCahierShowAll(){
  if(currentUserRole!=='prof' && currentUserRole!=='admin') return; // réservé profs/admins
  cahierShowAll = !cahierShowAll;
  const btn = document.getElementById('btnCahierShowAll');
  if(btn) btn.textContent = cahierShowAll ? "Revenir au chargement par jour" : "Afficher tout l'historique";
  renderCahierEleve();
}
function buildCahierNotebookHTML(editable){
  const status = document.getElementById('cahierFilterStatus');
  const filtreActif = cahierFilterFrom||cahierFilterTo||cahierFilterChapitre;
  if(!filtreActif && !cahierShowAll){
    // Mode paresseux (par défaut) : cahierDatesList est la source de vérité pour "y a-t-il des
    // entrées ?", pas `cahier` (qui ne contient que les jours déjà dépliés).
    if(status) status.textContent = '';
    if(!cahierDatesList.length) return '<p class="hint">Le cahier est vide pour l\'instant.</p>';
    return lazyGroupedEntriesAccordionHTML(editable);
  }
  // Mode complet (filtre explicite ou "Afficher tout l'historique") : `cahier` contient déjà
  // tout, chargé par syncFetchAll() en amont.
  const list = filteredCahier();
  if(status){
    status.textContent = filtreActif ? `${list.length} résultat(s) sur ${cahier.length}` : '';
  }
  if(!cahier.length) return '<p class="hint">Le cahier est vide pour l\'instant.</p>';
  if(!list.length) return '<p class="hint">Aucune correction dans cette période.</p>';
  return groupedEntriesAccordionHTML(list, (e)=>entryRowsHTML(e, cahier.indexOf(e), editable));
}
async function removeCahierEntryFromNotebook(i, btn){
  if(btn && btn.dataset.armed!=='1'){
    btn.dataset.armed='1';
    btn.dataset.originalText = btn.textContent;
    btn.textContent = 'Confirmer ?';
    btn.style.background = 'rgba(211,90,60,.3)';
    btn.dataset.timeoutId = setTimeout(()=>{
      if(btn.isConnected){ btn.dataset.armed=''; btn.textContent=btn.dataset.originalText; btn.style.background=''; }
    }, 2500);
    return;
  }
  const entry = cahier[i];
  if(isSyncEnabled() && entry && entry.id){
    const res = await syncRemoveEntry(entry.id);
    if(!res.ok){
      await niceAlert(res.error==='unauthorized'
        ? "Seul le professeur peut retirer un élément de ce cahier partagé (code secret requis, configuré dans l'outil prof)."
        : "Échec de la suppression sur le serveur : "+(res.error||'erreur inconnue'));
      return;
    }
  }
  cahier.splice(i,1);
  saveCahier();
  renderCahierEleve();
  if(document.getElementById('cahierList')) renderCahier();
}
async function renderCahierEleve(){
  populateCahierChapitreFilter();
  if(typeof cdBoutonMaj==='function') cdBoutonMaj(); // Session COURS en direct (cours-direct.js), professeurs
  const btnShowAll = document.getElementById('btnCahierShowAll');
  if(btnShowAll) btnShowAll.style.display = (currentUserRole==='prof'||currentUserRole==='admin') ? '' : 'none';
  if(!currentClassId){
    document.getElementById('cahierEleveContent').innerHTML = '<p class="hint">Choisissez une classe ci-dessus pour voir son cahier.</p>';
    return;
  }
  await cahierClasseResoudre();
  // Groupe sans cahier choisi ailleurs : sur la page Cahier, on passe à sa classe d'origine.
  const vueCahier = document.getElementById('view-cahier-eleve');
  if(!cahierClasse.propre && cahierClasse.id && cahierClasse.id!==currentClassId && vueCahier && vueCahier.classList.contains('active') && accountClassesList.some(c=>c.id===cahierClasse.id)){
    await selectClassFromModal(cahierClasse.id);
    return;
  }
  if(!cahierClasseId()){
    document.getElementById('cahierEleveContent').innerHTML = '<p class="hint"><span class=gicon>info</span> Ce groupe n\'a pas de cahier (réglage du groupe, dans Mes classes › Groupes) et sa classe d\'origine n\'a pas été trouvée : choisissez une classe pour voir son cahier.</p>';
    return;
  }
  await cahierProfsCharger();
  let warning = cahierProfsOngletsHtml() + (cahierClasse.propre ? '' : `<p class="nb-cahier-de"><span class=gicon>info</span> Ce groupe n'a pas son propre cahier : ${currentUserRole==='eleve' ? 'voici le cahier de ta classe' : 'vous voyez et complétez le cahier de la classe'} <b>${escapeHtml(cahierClasse.nom)}</b>.</p>`);
  if(isSyncEnabled()){
    document.getElementById('cahierEleveContent').innerHTML = '<p class="hint">Chargement depuis le cahier partagé…</p>';
    const filtreActif = cahierFilterFrom||cahierFilterTo||cahierFilterChapitre;
    if(!filtreActif && !cahierShowAll){
      // Mode paresseux (par défaut) : juste le squelette des dates, puis le contenu du jour le
      // plus récent seulement -- les autres jours se chargent à leur dépli (expandCahierDay).
      cahierDatesList = await fetchCahierDatesList();
      cahier = [];
      cahierLoadedDates = new Set();
      if(cahierDatesList.length){
        const plusRecent = cahierDatesList[cahierDatesList.length-1].date;
        const entries = await fetchCahierEntriesForDate(plusRecent);
        if(entries){ cahier = entries; sortCahierInPlace(); cahierLoadedDates.add(plusRecent); }
        else warning = '<p class="hint"><span class=gicon>warning</span> Impossible de joindre le cahier partagé, affichage de la dernière copie connue sur cet appareil.</p>';
      }
      saveCahier();
      populateCahierChapitreFilter();
    } else {
      const remote = await syncFetchAll(cahierFilterFrom, cahierFilterTo);
      if(remote){
        cahier = remote;
        saveCahier();
        populateCahierChapitreFilter();
      } else {
        warning = '<p class="hint"><span class=gicon>warning</span> Impossible de joindre le cahier partagé, affichage de la dernière copie connue sur cet appareil.</p>';
      }
    }
  }
  renderCahierEleveLocal(warning);
}
/* Réaffiche le cahier depuis le tableau LOCAL déjà en mémoire, SANS re-synchroniser depuis le
   serveur -- utilisée après une action qui a déjà mis à jour ce tableau localement (ex.
   réorganisation), pour éviter qu'une re-synchronisation immédiate n'écrase ce changement par
   d'anciennes données si la sauvegarde serveur n'a pas encore eu le temps de se terminer. */
function renderCahierEleveLocal(warning){
  const editable = currentUserRole==='prof' || currentUserRole==='admin';
  // Vue par semaine (mode par défaut) ; un filtre ou « Afficher tout l'historique » garde l'accordéon.
  if(!(cahierFilterFrom||cahierFilterTo||cahierFilterChapitre) && !cahierShowAll){
    document.getElementById('cahierEleveContent').innerHTML = (warning||'') + '<div id="nbSemaine"></div>';
    cahierEditableMode = editable;
    nbSemaineRendre('nb');
    return;
  }
  document.getElementById('cahierEleveContent').innerHTML = (warning||'') + buildCahierNotebookHTML(editable);
  const book=document.getElementById('cahierEleveBook');
  requestAnimationFrame(()=>{ book.scrollTop = book.scrollHeight; });
}
/* ---------- Cahier : vue par semaine ----------
   Demandé : « une vision par semaine avec 5-6 vignettes maxi les unes à côté des autres qui se
   déplient quand on appuie dessus. Au-dessus des vignettes, semaine du ... au ..., avec semaine
   précédente, semaine suivante (si déjà réalisée) ». Une vignette par jour qui a des entrées (jour,
   date, chapitres travaillés, cours / exercices) ; un clic déplie le contenu du jour sous les
   vignettes (pleine largeur), un second clic le replie. Les jours de la semaine affichée sont chargés
   ensemble (une requête par jour, comme l'accordéon). S'ouvre sur la semaine la plus récente et son
   dernier jour ; la semaine et le jour choisis sont gardés tant qu'on reste sur la même classe. */
// Deux vues par semaine partagent ce code : le cahier élève (« nb ») et le bas de la page Correction
// (« cor », demandé : « présenter le cahier comme dans cahier élève »), chacune avec sa semaine et
// son jour ouverts. Côté Correction, chaque exercice garde ses boutons Modifier / Retirer.
const nbSemSt = { nb: { classe: null, lundi: null, jour: null }, cor: { classe: null, lundi: null, jour: null } };
const NBS_IDS = { nb: ['nbSemaine', 'nbsJour'], cor: ['corSemaine', 'corsJour'] };
const nbIso = d => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
function nbLundi(iso){ const d = new Date(iso+'T12:00:00'), k = (d.getDay()+6)%7; d.setDate(d.getDate()-k); return nbIso(d); }
function nbPlus(iso, n){ const d = new Date(iso+'T12:00:00'); d.setDate(d.getDate()+n); return nbIso(d); }
// Jours du cahier (dates, nombre d'entrées, cours) : la liste légère du serveur, complétée par le
// cahier local (un exercice qu'on vient d'ajouter à une nouvelle date a tout de suite sa vignette).
function nbJours(){
  const loc = new Map();
  cahier.filter(e=>e.date).forEach(e=>{ const g = loc.get(e.date) || { date: e.date, count: 0, cours: false }; g.count++; if(e.exo==='Cours') g.cours = true; loc.set(e.date, g); });
  const m = new Map(loc);
  (cahierDatesList||[]).forEach(g=>{
    const l = loc.get(g.date), charge = cahierLoadedDates.has(g.date) || !isSyncEnabled();
    if(charge){ if(!l) m.delete(g.date); return; } // jour chargé : le local fait foi (entrées retirées)
    m.set(g.date, { date: g.date, count: Math.max(g.count, l ? l.count : 0), cours: !!g.cours || !!(l && l.cours) });
  });
  return [...m.values()].sort((a,b)=>a.date.localeCompare(b.date));
}
async function nbSemaineRendre(k){
  k = k || 'nb';
  const box = document.getElementById(NBS_IDS[k][0]); if(!box) return;
  const st = nbSemSt[k], jours = nbJours();
  if(!jours.length){ box.innerHTML = k==='cor' ? '<div class="placeholder-box">Le cahier est vide pour l\'instant, ajoutez une correction ci-dessus.</div>' : '<p class="hint">Le cahier est vide pour l\'instant.</p>'; return; }
  const semaines = [...new Set(jours.map(j=>nbLundi(j.date)))].sort();
  if(st.classe !== currentClassId || !semaines.includes(st.lundi)) Object.assign(st, { classe: currentClassId, lundi: semaines[semaines.length-1], jour: null });
  const lundi = st.lundi, dimanche = nbPlus(lundi, 6), iS = semaines.indexOf(lundi);
  const js = jours.filter(j=>j.date>=lundi && j.date<=dimanche);
  if(st.jour === null || (st.jour && !js.some(j=>j.date===st.jour))) st.jour = js[js.length-1].date;
  // Contenu des jours de la semaine (pour les vignettes et le dépli).
  const aCharger = js.filter(j=>!cahierLoadedDates.has(j.date) && isSyncEnabled());
  const fin = js.some(j=>new Date(j.date+'T12:00:00').getDay()%6===0) ? dimanche : nbPlus(lundi, 4); // samedi/dimanche seulement s'il y a des entrées
  const f = (iso, o) => new Date(iso+'T12:00:00').toLocaleDateString('fr-FR', o);
  const memeMois = lundi.slice(0,7)===fin.slice(0,7);
  box.innerHTML = `<div class="nbs-tete">
      <button type="button" class="nbs-nav" ${iS>0 ? `onclick="nbSemaineAller(-1,'${k}')"` : 'disabled'} title="Semaine précédente"><span class=gicon>chevron_left</span><span class="nbs-nav-t">Semaine précédente</span></button>
      <div class="nbs-titre">Semaine du ${f(lundi, memeMois ? {weekday:'long', day:'numeric'} : {weekday:'long', day:'numeric', month:'long'})} au ${f(fin, {weekday:'long', day:'numeric', month:'long'})}</div>
      <button type="button" class="nbs-nav" ${iS<semaines.length-1 ? `onclick="nbSemaineAller(1,'${k}')"` : 'disabled'} title="Semaine suivante"><span class="nbs-nav-t">Semaine suivante</span><span class=gicon>chevron_right</span></button></div>
    <div class="nbs-vignettes">${js.map(j=>nbVignette(j, k)).join('')}</div>
    <div id="${NBS_IDS[k][1]}"></div>`;
  nbSemaineJour(k);
  if(aCharger.length){
    const res = await Promise.all(aCharger.map(j=>fetchCahierEntriesForDate(j.date)));
    if(st.lundi!==lundi || !document.getElementById(NBS_IDS[k][0])) return;
    const ids = new Set(cahier.map(e=>e.id));
    res.forEach((entries, i)=>{ if(!entries){ st.echec = (st.echec || new Set()).add(aCharger[i].date); return; } entries.forEach(e=>{ if(!ids.has(e.id)){ cahier.push(e); ids.add(e.id); } }); cahierLoadedDates.add(aCharger[i].date); });
    sortCahierInPlace(); saveCahier();
    const zone = document.getElementById(NBS_IDS[k][0]);
    js.forEach(j=>{ const v = zone && zone.querySelector(`.nbs-vig[data-jour="${j.date}"]`); if(v) v.outerHTML = nbVignette(j, k); });
    nbSemaineJour(k);
    if(k==='cor') corCahierCompte();
  }
}
function nbVignette(j, k){
  k = k || 'nb';
  const st = nbSemSt[k], d = new Date(j.date+'T12:00:00'), es = cahier.filter(e=>e.date===j.date), charge = cahierLoadedDates.has(j.date) || !isSyncEnabled();
  const chap = [...new Set(es.map(e=>String(e.chapitre||'').split(' · ').slice(1).join(' · ') || String(e.chapitre||'')).filter(Boolean))];
  const nC = es.filter(e=>e.exo==='Cours').length, nE = es.length - nC;
  return `<button type="button" class="nbs-vig${st.jour===j.date ? ' on' : ''}" data-jour="${j.date}" onclick="nbSemaineChoisir('${j.date}','${k}')">
    <span class="nbs-j">${d.toLocaleDateString('fr-FR', {weekday:'long'})}</span><span class="nbs-d">${d.toLocaleDateString('fr-FR', {day:'numeric', month:'short'})}</span>${nbOlivCours(j.cours || nC>0)}
    <span class="nbs-chap">${charge ? chap.map(c=>escapeHtml(c)).join('<br>') || '&nbsp;' : '…'}</span>
    <span class="nbs-n">${charge && es.length ? `${nC ? `<span class="nbs-c">${nC} cours</span>` : ''}${nE ? `<span class="nbs-e">${nE} exercice${nE>1 ? 's' : ''}</span>` : ''}` : `${j.count} élément${j.count>1 ? 's' : ''}`}</span>
    <span class=gicon>${st.jour===j.date ? 'expand_less' : 'expand_more'}</span></button>`;
}
// Page Correction : un exercice du cahier, avec ses boutons Modifier / Retirer (comme l'ancienne liste).
function corEntreeHTML(e){
  const i = cahier.indexOf(e);
  return `<div class="cahier-entry">
      <div style="flex:1;min-width:0;">${entryRowsHTML(e, i, true, false)}</div>
      <div style="display:flex;flex-direction:column;gap:6px;flex:none;">
        <button class="remove" style="color:var(--accent);" onclick="editCahierEntry(${i})">Modifier</button>
        <button class="remove" onclick="removeCahierEntry(${i})">Retirer</button>
      </div>
    </div>`;
}
function nbSemaineJour(k){
  k = k || 'nb';
  const box = document.getElementById(NBS_IDS[k][1]); if(!box) return;
  const st = nbSemSt[k], date = st.jour;
  if(!date){ box.innerHTML = ''; return; }
  const charge = cahierLoadedDates.has(date) || !isSyncEnabled();
  const es = cahier.filter(e=>e.date===date);
  const outils = k==='cor'
    ? `<button type="button" class="btn secondary nb-resume-cor-btn" onclick="resumeCahierJour('${date}')" title="Résumé de la séance à copier dans le cahier de textes (École Directe, Pronote…)"><span class="gicon">content_paste</span> Résumé pour le cahier de textes</button>`
    : `<button type="button" class="nb-pdf-day-btn" onclick="exportCahierDayAsPDF('${date}')" title="Générer un PDF de ce jour"><span class=gicon>picture_as_pdf</span></button>${nbResumeDayBtn(date)}`;
  box.innerHTML = `<div class="nbs-panneau"><div class="nbs-p-tete"><b>${fmtDateFR(date)}</b>${nbOlivCours(es.some(e=>e.exo==='Cours'))}${outils}</div>
    ${charge ? groupedByChapitreHTML(es, k==='cor' ? corEntreeHTML : (e)=>entryRowsHTML(e, cahier.indexOf(e), cahierEditableMode))
      : st.echec && st.echec.has(date) ? '<p class="hint" style="padding:8px;"><span class=gicon>warning</span> Échec du chargement : cliquez sur « Actualiser ».</p>' : '<p class="hint" style="padding:8px;">Chargement…</p>'}</div>`;
}
function nbSemaineChoisir(date, k){
  k = k || 'nb';
  if(typeof cahierVivFin==='function') cahierVivFin();
  const st = nbSemSt[k], zone = document.getElementById(NBS_IDS[k][0]);
  st.jour = st.jour===date ? '' : date;
  if(zone) zone.querySelectorAll('.nbs-vig').forEach(v=>{ const on = v.dataset.jour===st.jour; v.classList.toggle('on', on); const i = v.querySelector(':scope > .gicon'); if(i) i.textContent = on ? 'expand_less' : 'expand_more'; });
  nbSemaineJour(k);
  const p = document.getElementById(NBS_IDS[k][1]); if(p && st.jour) p.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
}
function nbSemaineAller(sens, k){
  k = k || 'nb';
  const st = nbSemSt[k], semaines = [...new Set(nbJours().map(j=>nbLundi(j.date)))].sort(), i = semaines.indexOf(st.lundi) + sens;
  if(i<0 || i>=semaines.length) return;
  if(typeof cahierVivFin==='function') cahierVivFin();
  st.lundi = semaines[i]; st.jour = null;
  nbSemaineRendre(k);
}
async function exportCahierAsPDF(){
  if(!cahier.length){ await niceAlert('Le cahier est vide : ajoutez au moins une correction avant de générer le PDF.'); return; }
  // Même choix que pour l'évaluation : la capture d'écran (html2canvas) donne une page blanche
  // de façon récurrente avec ce type de contenu (SVG notamment), malgré plusieurs correctifs
  // essayés. L'impression native du navigateur est fiable -- choisir "Enregistrer au format PDF"
  // comme destination dans la boîte d'impression (celle-ci bloque l'onglet tant qu'elle est
  // ouverte -- comportement normal du navigateur, pas un bug).
  const w = window.open('', '_blank', 'width=900,height=700');
  if(!w){ await niceAlert("La fenêtre n'a pas pu s'ouvrir : autorisez les pop-up pour ce site, ou utilisez Ctrl/Cmd+P."); return; }
  w.document.open();
  w.document.write(`<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Cahier de corrections</title>
    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/KaTeX/0.16.9/katex.min.css">
    <link rel="stylesheet" href="${document.querySelector('link[href*="styles.css"]').href}">
    <style>
      @page{ size:A4; margin:15mm; }
      body{ font-family:Inter,Arial,sans-serif; color:#20242E; font-size:12.5pt; line-height:1.7; margin:0; }
      .print-page{ max-width:680px; margin:0 auto; }
      .nb-figure-row{ margin:6px 0; }
      svg{ max-width:100%; }
      .katex{ font-size:1.18em; }
      * { -webkit-print-color-adjust:exact !important; print-color-adjust:exact !important; color-adjust:exact !important; }
      .nb-date{ font-weight:700; }
      .nb-ref{ text-decoration:underline; text-underline-offset:3px; }
      .nb-page-footer{ text-align:right; font-style:italic; color:#666; font-size:.92em; margin:8px 0 16px; }
      .cahier-print-entry{ page-break-inside:avoid; break-inside:avoid; }
      .nb-accordion-body{ max-height:none !important; overflow:visible !important; padding:14px 20px 18px !important; }
      .nb-accordion-chevron, .nb-pdf-day-btn{ display:none !important; }
      .print-trigger-btn{
        position:static; display:block; margin:0 auto 16px; padding:10px 18px;
        background:#0C5BA0; color:#fff; border:none; border-radius:24px; font-family:Inter,Arial,sans-serif;
        font-size:14px; font-weight:600; cursor:pointer;
      }
      @media print{ .print-trigger-btn{ display:none; } }
    </style>
  </head><body>
    <button type="button" class="print-trigger-btn" onclick="window.print()">🖨️ Imprimer / Enregistrer en PDF</button>
    <div class="print-page">${buildCahierNotebookHTML()}</div></body></html>`);
  w.document.close();
  w.onload = () => {
    setTimeout(()=>{
      syncDiskSizesForPrint(w.document);
      requestAnimationFrame(()=>requestAnimationFrame(()=>{
        w.focus();
        w.print();
      }));
    }, 200);
  };
}
function generateCahierPDF(){ exportCahierAsPDF(); }
function downloadCahierElevePDF(){ exportCahierAsPDF(); }
// Export PDF d'UN SEUL jour (pas tout le cahier) -- demandé : "un icone pdf qui permet de
// générer en pdf le contenu du jour". Réutilise le même gabarit d'impression que
// exportCahierAsPDF(). S'assure d'abord que le contenu de ce jour est bien chargé (le
// chargement paresseux ne charge par défaut que le jour le plus récent).
/* ---- Résumé d'une séance pour le cahier de textes -- demandé : « un bouton visible par le
   professeur qui récapitule ce qui a été fait pour permettre un copier coller vers le cahier de
   texte de classe (école directe ou autre). Mettre en forme avec des couleurs pour cours et
   exercices. Pour le cours, ne mettre que les titres. Préciser à chaque début de résumé quel est
   le chapitre travaillé ». ---- */
function nbResumeDayBtn(date){
  if(currentUserRole!=='prof' && currentUserRole!=='admin') return '';
  return `<button type="button" class="nb-pdf-day-btn nb-resume-day-btn" onclick="event.stopPropagation(); resumeCahierJour('${date}')" title="Résumé de la séance à copier dans le cahier de textes (École Directe…)"><span class=gicon>content_paste</span></button>`;
}
async function assurerJourCahierCharge(date){
  if(isSyncEnabled() && !cahierLoadedDates.has(date)){
    const entries = await fetchCahierEntriesForDate(date);
    if(entries){
      const existingIds = new Set(cahier.map(e=>e.id));
      entries.forEach(e=>{ if(!existingIds.has(e.id)) cahier.push(e); });
      sortCahierInPlace();
      cahierLoadedDates.add(date);
      saveCahier();
    }
  }
}
/* Titres d'une partie de cours pour le résumé -- demandé : « Pour les cours : mettre le numéro du
   paragraphe et les sous paragraphes aussi ». On relit les titres dans le HTML figé de l'entrée :
   « 1. Titre » (.lesson-header) puis ses sous-paragraphes « A. Titre » (.sub-header) ; une méthode
   (lettre M) garde son seul titre (« Méthode 1 : … »). Sans titre lisible : le titre de l'entrée. */
function resumeCoursTitres(e, titre){
  const tpl = document.createElement('template');
  tpl.innerHTML = e.html || '';
  const texte = el=>{ if(!el) return ''; const c = el.cloneNode(true); c.querySelectorAll('.katex-mathml, .gicon').forEach(x=>x.remove()); return c.textContent.replace(/\s+/g, ' ').trim(); };
  const out = [];
  tpl.content.querySelectorAll('.lesson-header, .sub-header').forEach(h=>{
    const t = texte(h.querySelector('h3,h4')); if(!t) return;
    if(h.classList.contains('lesson-header')){
      const n = texte(h.querySelector('.num'));
      out.push({t: (n ? n + '. ' : '') + t, subs: []});
    } else {
      const l = texte(h.querySelector('.letter'));
      const u = l && l !== 'M' && !/^M(é|e)thode/i.test(t) && l.length <= 3 ? l + '. ' + t : t; // M : méthode
      if(out.length) out[out.length-1].subs.push(u);
      else { const par = resumeParagrapheParent(e, t); out.push(par ? {t: par, subs: [u]} : {t: u, subs: []}); }
    }
  });
  return out.length ? out : (titre ? [{t: titre, subs: []}] : []);
}
// Sous-paragraphe (ou méthode) ajouté seul : on retrouve son paragraphe « 2. Titre » dans le cours du
// chapitre (conteneur du DEMO_REGISTRY), pour l'écrire sous son paragraphe dans le résumé.
function resumeParagrapheParent(e, sousTitre){
  try{
    const chap = String(e.chapitre||'').replace(/^[A-Z]{1,3}\d+[a-z]?\s*·\s*/, '').trim();
    const reg = typeof DEMO_REGISTRY !== 'undefined' && DEMO_REGISTRY[e.niveau + '|' + chap];
    const norm = t => String(t||'').replace(/\s+/g, ' ').trim();
    // Rubrique « Méthodes » du chapitre (à part du cours) : les méthodes sont regroupées sous ce titre.
    const meth = reg && reg.methode && document.getElementById(reg.methode);
    if(meth && [...meth.querySelectorAll('.sub-header h4')].some(h=>norm(h.textContent) === sousTitre)) return 'Méthodes';
    const cont = reg && reg.cours && document.getElementById(reg.cours);
    if(!cont) return null;
    let par = null;
    for(const h of cont.querySelectorAll('.lesson-header, .sub-header')){
      if(h.classList.contains('lesson-header')){ const n = h.querySelector('.num'), t = h.querySelector('h3'); par = (n ? norm(n.textContent) + '. ' : '') + norm(t && t.textContent); }
      else if(par && norm((h.querySelector('h4')||{}).textContent) === sousTitre) return par;
    }
  }catch(err){}
  return null;
}
/* Demandé ensuite : « Peux-tu respecter l'ordre du cahier pour faire le cahier de texte ? ». Le résumé
   suit l'ordre des blocs du cahier ce jour-là : un nouveau « Chapitre : » dès que le chapitre change, une
   nouvelle rubrique (Cours, Exercices, Interrogation, Questions flash) dès que le type de bloc change. */
function resumeSeanceContenu(date){
  if(typeof sortCahierInPlace === 'function') sortCahierInPlace();
  const entries = cahier.filter(e=>e.date===date);
  const blocs = [], coursVus = new Map(); // coursVus : chapitre → paragraphes déjà listés (doublons)
  const court = t => t.length > 110 ? t.slice(0, 107).replace(/\s+\S*$/, '') + '…' : t;
  entries.forEach(e=>{
    const nom = String(e.chapitre||'').replace(/^[A-Z]{1,3}\d+[a-z]?\s*·\s*/, '').trim() || 'Chapitre non précisé';
    const titre = String(e.titre||'').replace(/\s+/g, ' ').trim();
    const type = e.exo==='Cours' ? 'cours' : e.exo==='Interrogation' ? 'interro' : (e.exo==='Questions flash' || e.exo==='Séance en direct') ? 'flash' : (COR_MODALITES[e.modalite] ? 'exos-' + e.modalite : 'exos');
    let c = blocs[blocs.length-1];
    if(!c || c.nom!==nom){ c = {nom, rubs:[]}; blocs.push(c); }
    let r = c.rubs[c.rubs.length-1];
    const rubrique = ()=>{ if(!r || r.type!==type){ r = {type, items:[]}; c.rubs.push(r); } return r; };
    if(type==='cours'){
      if(!coursVus.has(nom)) coursVus.set(nom, []);
      const vus = coursVus.get(nom);
      resumeCoursTitres(e, titre).forEach(it=>{
        // Même paragraphe déjà listé ce jour-là : ses nouveaux sous-paragraphes le rejoignent.
        const deja = vus.find(x=>x.t===it.t);
        if(deja){ it.subs.forEach(u=>{ if(!deja.subs.includes(u)) deja.subs.push(u); }); return; }
        if(!it.subs.length && vus.some(x=>x.subs.includes(it.t))) return;
        vus.push(it); rubrique().items.push(it);
      });
    }
    // Interrogations et questions flash : rubriques à part, jamais dans « Exercices ».
    else if(type==='interro') rubrique().items.push(court(titre) || 'Interrogation');
    else if(type==='flash') rubrique().items.push(court(titre) || 'Questions flash');
    else if(e.exo==='TD') rubrique().items.push(titre || 'Exercices');
    else if(e.exo==='Construction') rubrique().items.push('Construction' + (titre && titre!=='Construction' ? ' : '+court(titre) : ''));
    else {
      const num = String(e.exo||'').trim(), n = num && num!=='-' ? 'Exercice '+num : 'Exercice';
      rubrique().items.push(n + (titre ? ' : '+court(titre) : ''));
    }
  });
  // Cours (bleu), Exercices (orange), Interrogation (violet, 📝), Questions flash (rouge, ⚡).
  const STYLE = { cours: ['Cours', '#0C5BA0', ''], exos: ['Exercices', '#C45F00', ''], interro: ['Interrogation', '#6B3FA0', '📝 '], flash: ['Questions flash', '#C62828', '⚡ '],
    'exos-maison': ['Correction du travail maison', '#8A4B08', '🏠 '], 'exos-classe': ['Exercices en classe entière', '#C45F00', ''], 'exos-autonomie': ['Exercices en autonomie', '#2E7D32', ''] };
  const ENCRE = '#20242E', esc = t => escapeHtml(t);
  let html = '', txt = '';
  blocs.forEach((c, i)=>{
    html += `<p style="margin:${i ? '14px' : '0'} 0 4px;font-weight:bold;color:${ENCRE};">Chapitre : ${esc(c.nom)}</p>`;
    txt += (i ? '\n' : '') + 'Chapitre : ' + c.nom + '\n';
    c.rubs.forEach(r=>{
      if(!r.items.length) return;
      const [nomR, coul, logo] = STYLE[r.type];
      const li = r.type==='cours'
        ? r.items.map(it=>`<li>${esc(it.t)}${it.subs.length ? `<ul style="margin:2px 0 0;padding-left:20px;list-style:circle;">${it.subs.map(u=>`<li>${esc(u)}</li>`).join('')}</ul>` : ''}</li>`).join('')
        : r.items.map(t=>`<li>${esc(t)}</li>`).join('');
      html += `<p style="margin:4px 0 2px;font-weight:bold;color:${coul};">${logo}${nomR}</p><ul style="margin:0 0 6px;padding-left:22px;color:${coul};">${li}</ul>`;
      txt += logo + nomR + ' :\n' + (r.type==='cours'
        ? r.items.map(it=>'  - '+it.t + it.subs.map(u=>'\n      '+u).join('')).join('\n')
        : r.items.map(t=>'  - '+t).join('\n')) + '\n';
    });
  });
  return {html, txt, vide: !entries.length};
}
async function resumeCahierJour(date){
  await assurerJourCahierCharge(date);
  const r = resumeSeanceContenu(date);
  if(r.vide){ await niceAlert('Rien dans le cahier ce jour-là.'); return; }
  const ov = document.createElement('div');
  ov.className = 'modal-overlay'; ov.id = 'resumeSeanceOverlay';
  ov.innerHTML = `<div class="modal-card" style="max-width:640px;">
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;">
      <strong style="font-family:'Space Grotesk',sans-serif;font-size:1.05rem;"><span class="gicon">content_paste</span> Résumé de la séance du ${fmtDateFR(date).replace(/^./, c=>c.toLowerCase())}</strong>
      <button class="modal-close" onclick="document.getElementById('resumeSeanceOverlay').remove()" aria-label="Fermer"><span class="gicon">close</span></button>
    </div>
    <p class="hint" style="margin:0 0 10px;">À coller dans le cahier de textes de la classe (École Directe, Pronote…). Le texte reste modifiable ici avant de le copier.</p>
    <div id="resumeSeanceApercu" contenteditable="true" style="border:1px solid rgba(28,43,57,.18);border-radius:10px;padding:12px 14px;max-height:52vh;overflow:auto;font-family:Arial,sans-serif;font-size:14px;line-height:1.5;background:#fff;">${r.html}</div>
    <div class="figure-toolbar" style="margin-top:12px;justify-content:flex-start;">
      <button class="btn" onclick="copierResumeSeance(true)"><span class="gicon">content_copy</span> Copier (avec les couleurs)</button>
      <button class="btn secondary" onclick="copierResumeSeance(false)">Copier en texte simple</button>
      <span id="resumeSeanceStatut" class="hint" style="margin:0;align-self:center;"></span>
    </div>
  </div>`;
  ov.addEventListener('click', e=>{ if(e.target===ov) ov.remove(); });
  document.body.appendChild(ov);
  window._resumeSeanceTexte = r.txt;
}
async function copierResumeSeance(avecCouleurs){
  const apercu = document.getElementById('resumeSeanceApercu'), statut = document.getElementById('resumeSeanceStatut');
  if(!apercu) return;
  const html = apercu.innerHTML, texte = apercu.innerText.replace(/\n{3,}/g, '\n\n').trim();
  let ok = false;
  try{
    if(avecCouleurs && window.ClipboardItem && navigator.clipboard && navigator.clipboard.write){
      await navigator.clipboard.write([new ClipboardItem({'text/html': new Blob([html], {type:'text/html'}), 'text/plain': new Blob([texte], {type:'text/plain'})})]);
      ok = true;
    } else if(!avecCouleurs && navigator.clipboard && navigator.clipboard.writeText){
      await navigator.clipboard.writeText(texte); ok = true;
    }
  }catch(e){ ok = false; }
  if(!ok){
    // Repli : sélection de l'aperçu et copie classique (garde la mise en forme).
    const sel = window.getSelection(), range = document.createRange();
    range.selectNodeContents(apercu); sel.removeAllRanges(); sel.addRange(range);
    try{ ok = document.execCommand('copy'); }catch(e){ ok = false; }
    sel.removeAllRanges();
  }
  if(statut) statut.textContent = ok ? '✓ Copié : collez-le dans le cahier de textes.' : 'Copie impossible : sélectionnez le texte ci-dessus et faites Ctrl+C.';
}
